-- ============================================================================
-- 025_shipping_delivery_microprocess_v10_11.sql
-- ============================================================================
begin;

-- V10.11 · Despachos y entregas guiados.
-- Mantiene dos etapas medibles: despacho/ruta y cierre de entrega.

create table if not exists erp_supply.delivery_milestones (
  id bigint generated always as identity primary key,
  organization_id uuid not null references erp_supply.organizations(id),
  order_id uuid not null references erp_supply.orders(id) on delete cascade,
  task_id uuid references erp_supply.order_tasks(id) on delete set null,
  delivery_id uuid references erp_supply.deliveries(id) on delete set null,
  milestone_code text not null check (milestone_code in (
    'GUIDE_ADDED','LOCATION_CAPTURED','DISPATCHED','CLOSURE_ASSIGNED',
    'DELIVERY_EVIDENCE_UPLOADED','DELIVERED','NO_DELIVERY_REPORTED'
  )),
  occurred_at timestamptz not null default now(),
  actor_profile_id uuid references erp_supply.profiles(id),
  metadata jsonb not null default '{}'::jsonb
);

create index if not exists idx_delivery_milestones_order_time
  on erp_supply.delivery_milestones(order_id,occurred_at);

-- La misma persona que despacha puede realizar el cierre final.
insert into erp_supply.step_roles(step_code,role_code,can_view,can_claim,can_assign,can_start,can_complete,can_block,can_override)
values
  ('CLOSURE','coordinador_logistico',true,true,false,true,true,true,false),
  ('CLOSURE','despacho_nacional',true,true,false,true,true,true,false)
on conflict(step_code,role_code) do update set
  can_view=excluded.can_view,can_claim=excluded.can_claim,can_start=excluded.can_start,
  can_complete=excluded.can_complete,can_block=excluded.can_block;

-- Ventas solo consulta el módulo para reportar novedades de no entrega.
insert into erp_supply.role_module_permissions(role_code,module_code,can_read,can_create,can_update,can_approve,can_admin)
values('ventas','shipping',true,false,false,false,false)
on conflict(role_code,module_code) do update set can_read=true,can_create=false,can_update=false;

create or replace function public.erp_x_shipping_save_guide(p_order_id uuid,p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_order erp_supply.orders%rowtype;
  v_task erp_supply.order_tasks%rowtype;
  v_delivery erp_supply.deliveries%rowtype;
  v_tracking text:=nullif(trim(p_payload->>'trackingNumber'),'');
  v_carrier text:=nullif(trim(p_payload->>'carrier'),'');
begin
  if not (erp_supply.can_access_module('shipping','update') or erp_supply.has_role('super_admin')) then
    raise exception 'No autorizado para gestionar despachos' using errcode='42501';
  end if;
  if v_tracking is null then raise exception 'Número de guía requerido'; end if;

  select * into v_order from erp_supply.orders
  where id=p_order_id and organization_id=v_org for update;
  if not found or v_order.current_step_code not in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH') then
    raise exception 'El pedido no está en una etapa de despacho';
  end if;
  select * into v_task from erp_supply.order_tasks
  where order_id=p_order_id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED')
  order by sequence_no desc limit 1 for update;
  if not found or v_task.status<>'IN_PROGRESS' then raise exception 'Primero debes tomar el pedido'; end if;
  if v_task.assigned_profile_id is distinct from v_actor and not (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica')) then
    raise exception 'El pedido está asignado a otra persona' using errcode='42501';
  end if;

  select * into v_delivery from erp_supply.deliveries
  where order_id=p_order_id and status not in('CANCELLED')
  order by created_at desc limit 1 for update;
  if not found then
    insert into erp_supply.deliveries(order_id,route_code,status,carrier,tracking_number,assigned_profile_id,metadata)
    values(p_order_id,v_order.delivery_route_code,'PLANNED',v_carrier,v_tracking,v_actor,
      jsonb_build_object('taskId',v_task.id,'guideAddedAt',now(),'guideFileId',p_payload->>'guideFileId'))
    returning * into v_delivery;
  else
    update erp_supply.deliveries set
      carrier=v_carrier,tracking_number=v_tracking,assigned_profile_id=v_actor,
      metadata=metadata||jsonb_build_object('taskId',v_task.id,'guideAddedAt',now(),'guideFileId',p_payload->>'guideFileId'),
      updated_at=now()
    where id=v_delivery.id returning * into v_delivery;
  end if;

  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_task.id,v_delivery.id,'GUIDE_ADDED',v_actor,jsonb_build_object('trackingNumber',v_tracking,'carrier',v_carrier,'guideFileId',p_payload->>'guideFileId'));
  insert into erp_supply.order_events(organization_id,order_id,task_id,event_type,action_code,from_step_code,to_step_code,from_status,to_status,actor_profile_id,actor_role_code,payload)
  values(v_org,p_order_id,v_task.id,'DOMAIN_RECORD','SHIPPING_GUIDE',v_order.current_step_code,v_order.current_step_code,v_order.status,v_order.status,v_actor,(erp_supply.current_roles())[1],jsonb_build_object('trackingNumber',v_tracking,'carrier',v_carrier));
  return jsonb_build_object('success',true,'delivery',to_jsonb(v_delivery));
end;
$$;

create or replace function public.erp_x_shipping_save_location(p_order_id uuid,p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_order erp_supply.orders%rowtype;
  v_task erp_supply.order_tasks%rowtype;
  v_delivery erp_supply.deliveries%rowtype;
  v_lat numeric;
  v_lon numeric;
  v_alt numeric;
  v_accuracy numeric;
  v_destination jsonb;
begin
  if not (erp_supply.can_access_module('shipping','update') or erp_supply.has_role('super_admin')) then
    raise exception 'No autorizado para gestionar despachos' using errcode='42501';
  end if;
  begin
    v_lat:=(p_payload->>'latitude')::numeric;
    v_lon:=(p_payload->>'longitude')::numeric;
    v_alt:=nullif(p_payload->>'altitude','')::numeric;
    v_accuracy:=nullif(p_payload->>'accuracy','')::numeric;
  exception when others then raise exception 'Coordenadas inválidas'; end;
  if v_lat not between -90 and 90 or v_lon not between -180 and 180 then raise exception 'Coordenadas fuera de rango'; end if;
  if nullif(trim(p_payload->>'municipality'),'') is null then raise exception 'Municipio requerido'; end if;
  if nullif(trim(p_payload->>'address'),'') is null then raise exception 'Dirección requerida'; end if;
  if nullif(trim(p_payload->>'placeLabel'),'') is null then raise exception 'Lugar o punto de referencia requerido'; end if;

  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org for update;
  if not found or v_order.current_step_code not in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH') then raise exception 'El pedido no está en despacho'; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found or v_task.status<>'IN_PROGRESS' then raise exception 'Primero debes tomar el pedido'; end if;
  if v_task.assigned_profile_id is distinct from v_actor and not (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica')) then raise exception 'El pedido está asignado a otra persona' using errcode='42501'; end if;

  select * into v_delivery from erp_supply.deliveries where order_id=p_order_id order by created_at desc limit 1 for update;
  if not found or nullif(trim(v_delivery.tracking_number),'') is null then raise exception 'Primero debes registrar la guía'; end if;
  v_destination:=jsonb_build_object(
    'placeLabel',trim(p_payload->>'placeLabel'),'municipality',trim(p_payload->>'municipality'),
    'department',nullif(trim(p_payload->>'department'),''),'address',trim(p_payload->>'address'),
    'latitude',v_lat,'longitude',v_lon,'altitude',v_alt,'accuracy',v_accuracy,
    'source',coalesce(nullif(p_payload->>'source',''),'DEVICE_GEOLOCATION'),'capturedAt',now()
  );
  update erp_supply.deliveries set metadata=metadata||jsonb_build_object('destination',v_destination,'locationCapturedAt',now()),updated_at=now()
  where id=v_delivery.id returning * into v_delivery;

  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_task.id,v_delivery.id,'LOCATION_CAPTURED',v_actor,v_destination);
  insert into erp_supply.order_events(organization_id,order_id,task_id,event_type,action_code,from_step_code,to_step_code,from_status,to_status,actor_profile_id,actor_role_code,payload)
  values(v_org,p_order_id,v_task.id,'DOMAIN_RECORD','SHIPPING_LOCATION',v_order.current_step_code,v_order.current_step_code,v_order.status,v_order.status,v_actor,(erp_supply.current_roles())[1],v_destination);
  return jsonb_build_object('success',true,'delivery',to_jsonb(v_delivery));
end;
$$;

create or replace function public.erp_x_shipping_send_to_closure(p_order_id uuid,p_payload jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_order erp_supply.orders%rowtype;
  v_task erp_supply.order_tasks%rowtype;
  v_delivery erp_supply.deliveries%rowtype;
  v_result jsonb;
  v_closure erp_supply.order_tasks%rowtype;
  v_role text:=coalesce((erp_supply.current_roles())[1],'coordinador_logistico');
begin
  if not (erp_supply.can_access_module('shipping','update') or erp_supply.has_role('super_admin')) then raise exception 'No autorizado para gestionar despachos' using errcode='42501'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org for update;
  if not found or v_order.current_step_code not in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH') then raise exception 'El pedido no está en despacho'; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found or v_task.status<>'IN_PROGRESS' then raise exception 'Primero debes tomar el pedido'; end if;
  if v_task.assigned_profile_id is distinct from v_actor and not (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica')) then raise exception 'El pedido está asignado a otra persona' using errcode='42501'; end if;
  select * into v_delivery from erp_supply.deliveries where order_id=p_order_id order by created_at desc limit 1 for update;
  if not found or nullif(trim(v_delivery.tracking_number),'') is null then raise exception 'Falta registrar la guía'; end if;
  if nullif(v_delivery.metadata#>>'{destination,municipality}','') is null or nullif(v_delivery.metadata#>>'{destination,address}','') is null then raise exception 'Falta confirmar el lugar de entrega'; end if;

  update erp_supply.deliveries set status='IN_TRANSIT',dispatched_at=coalesce(dispatched_at,now()),assigned_profile_id=v_actor,
    metadata=metadata||jsonb_build_object('sentToClosureAt',now()),updated_at=now()
  where id=v_delivery.id returning * into v_delivery;
  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_task.id,v_delivery.id,'DISPATCHED',v_actor,jsonb_build_object('trackingNumber',v_delivery.tracking_number,'route',v_order.delivery_route_code));

  v_result:=erp_supply.execute_action_internal(p_order_id,'COMPLETE',jsonb_build_object('detail',coalesce(nullif(p_payload->>'detail',''),'Pedido despachado y enviado a cierre'),'resultCode','DISPATCHED'),v_actor,false,v_order.version,gen_random_uuid()::text);

  select * into v_closure from erp_supply.order_tasks where order_id=p_order_id and step_code='CLOSURE' and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found then raise exception 'No fue posible crear la etapa de cierre'; end if;
  update erp_supply.order_tasks set assigned_profile_id=v_actor,assigned_role_code=v_role,assigned_at=coalesce(assigned_at,now()),status='ASSIGNED',metadata=metadata||jsonb_build_object('source','SHIPPING_V10_11','deliveryId',v_delivery.id)
  where id=v_closure.id returning * into v_closure;
  update erp_supply.orders set current_assignee_id=v_actor,current_role_code=v_role,status='ASSIGNED',version=version+1,updated_at=now() where id=p_order_id returning * into v_order;
  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_closure.id,v_delivery.id,'CLOSURE_ASSIGNED',v_actor,jsonb_build_object('previousTaskId',v_task.id));
  return jsonb_build_object('success',true,'orderId',p_order_id,'currentStep','CLOSURE','delivery',to_jsonb(v_delivery),'task',to_jsonb(v_closure));
end;
$$;

create or replace function public.erp_x_shipping_register_evidence(p_order_id uuid,p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();
  v_order erp_supply.orders%rowtype;v_task erp_supply.order_tasks%rowtype;v_delivery erp_supply.deliveries%rowtype;v_file erp_supply.drive_files%rowtype;
  v_file_id uuid;
begin
  if not (erp_supply.can_access_module('shipping','update') or erp_supply.has_role('super_admin')) then raise exception 'No autorizado para cerrar entregas' using errcode='42501'; end if;
  begin v_file_id:=(p_payload->>'fileId')::uuid; exception when others then raise exception 'Archivo de evidencia inválido'; end;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org for update;
  if not found or v_order.current_step_code<>'CLOSURE' then raise exception 'El pedido no está en cierre'; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and step_code='CLOSURE' and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found or v_task.status<>'IN_PROGRESS' then raise exception 'Primero debes tomar el pedido'; end if;
  if v_task.assigned_profile_id is distinct from v_actor and not (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica')) then raise exception 'El pedido está asignado a otra persona' using errcode='42501'; end if;
  select * into v_file from erp_supply.drive_files where id=v_file_id and order_id=p_order_id and task_id=v_task.id and file_category='DELIVERY_EVIDENCE';
  if not found then raise exception 'No se encontró la foto cargada para este cierre'; end if;
  select * into v_delivery from erp_supply.deliveries where order_id=p_order_id order by created_at desc limit 1 for update;
  if not found then raise exception 'No existe un despacho registrado'; end if;
  update erp_supply.deliveries set metadata=metadata||jsonb_build_object('deliveryEvidenceFileId',v_file.id,'deliveryEvidenceAt',now()),updated_at=now() where id=v_delivery.id returning * into v_delivery;
  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_task.id,v_delivery.id,'DELIVERY_EVIDENCE_UPLOADED',v_actor,jsonb_build_object('fileId',v_file.id,'fileName',v_file.file_name));
  return jsonb_build_object('success',true,'file',to_jsonb(v_file),'delivery',to_jsonb(v_delivery));
end;
$$;

create or replace function public.erp_x_shipping_finalize(p_order_id uuid,p_payload jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();
  v_order erp_supply.orders%rowtype;v_task erp_supply.order_tasks%rowtype;v_delivery erp_supply.deliveries%rowtype;v_result jsonb;v_file_id uuid;
begin
  if not (erp_supply.can_access_module('shipping','update') or erp_supply.has_role('super_admin')) then raise exception 'No autorizado para finalizar entregas' using errcode='42501'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org for update;
  if not found or v_order.current_step_code<>'CLOSURE' then raise exception 'El pedido no está en cierre'; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and step_code='CLOSURE' and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found or v_task.status<>'IN_PROGRESS' then raise exception 'Primero debes tomar el pedido'; end if;
  if v_task.assigned_profile_id is distinct from v_actor and not (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica')) then raise exception 'El pedido está asignado a otra persona' using errcode='42501'; end if;
  select f.id into v_file_id from erp_supply.drive_files f where f.order_id=p_order_id and f.task_id=v_task.id and f.file_category='DELIVERY_EVIDENCE' order by f.created_at desc limit 1;
  if v_file_id is null then raise exception 'Debes subir la foto de entrega antes de finalizar'; end if;
  select * into v_delivery from erp_supply.deliveries where order_id=p_order_id order by created_at desc limit 1 for update;
  if not found then raise exception 'No existe un despacho registrado'; end if;
  update erp_supply.deliveries set status='DELIVERED',delivered_at=now(),received_by=nullif(trim(p_payload->>'receivedBy'),''),assigned_profile_id=v_actor,
    metadata=metadata||jsonb_build_object('finalizedAt',now(),'deliveryEvidenceFileId',v_file_id),updated_at=now()
  where id=v_delivery.id returning * into v_delivery;
  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_task.id,v_delivery.id,'DELIVERED',v_actor,jsonb_build_object('receivedBy',v_delivery.received_by,'evidenceFileId',v_file_id));
  v_result:=erp_supply.execute_action_internal(p_order_id,'COMPLETE',jsonb_build_object('detail','Pedido entregado y finalizado','resultCode','DELIVERED','deliveryId',v_delivery.id,'evidenceFileId',v_file_id),v_actor,false,v_order.version,gen_random_uuid()::text);
  return jsonb_build_object('success',true,'delivery',to_jsonb(v_delivery),'workflow',v_result);
end;
$$;

create or replace function public.erp_x_shipping_sent_orders(p_search text default null,p_page integer default 1,p_page_size integer default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_page int:=greatest(coalesce(p_page,1),1);v_size int:=least(greatest(coalesce(p_page_size,30),1),100);v_total bigint;v_items jsonb;
begin
  if not (erp_supply.has_role('ventas') or erp_supply.has_role('super_admin')) then raise exception 'Solo Ventas o Superadministración pueden consultar pedidos enviados' using errcode='42501'; end if;
  select count(*) into v_total
  from erp_supply.orders o
  join lateral(select d.* from erp_supply.deliveries d where d.order_id=o.id and d.dispatched_at is not null order by d.created_at desc limit 1)d on true
  where o.organization_id=v_org and not o.is_test and (erp_supply.has_role('super_admin') or o.seller_profile_id=v_actor)
    and (p_search is null or lower(o.order_number||' '||o.client_name||' '||coalesce(d.tracking_number,'')) like '%'||lower(p_search)||'%');

  select coalesce(jsonb_agg(to_jsonb(x) order by x."dispatchedAt" desc),'[]'::jsonb) into v_items from(
    select o.id,o.order_number "orderNumber",o.client_name "clientName",o.priority,o.delivery_route_code route,o.current_step_code "currentStep",o.status,
      d.status "deliveryStatus",d.tracking_number "trackingNumber",d.carrier,d.dispatched_at "dispatchedAt",d.delivered_at "deliveredAt",
      d.metadata#>>'{destination,municipality}' municipality,d.metadata#>>'{destination,address}' address,
      coalesce(p.display_name,sp.display_name) "assigneeName",
      (d.status='NOT_DELIVERED' or lower(coalesce(o.metadata->>'deliveryExceptionOpen','false'))='true') "hasNoDelivery",
      (d.status in('DISPATCHED','IN_TRANSIT','REPROGRAMMED') and o.status<>'CLOSED') "canReportNoDelivery"
    from erp_supply.orders o
    join lateral(select dl.* from erp_supply.deliveries dl where dl.order_id=o.id and dl.dispatched_at is not null order by dl.created_at desc limit 1)d on true
    left join erp_supply.profiles p on p.id=d.assigned_profile_id
    left join erp_supply.profiles sp on sp.id=o.seller_profile_id
    where o.organization_id=v_org and not o.is_test and (erp_supply.has_role('super_admin') or o.seller_profile_id=v_actor)
      and (p_search is null or lower(o.order_number||' '||o.client_name||' '||coalesce(d.tracking_number,'')) like '%'||lower(p_search)||'%')
    order by d.dispatched_at desc offset(v_page-1)*v_size limit v_size
  )x;
  return jsonb_build_object('items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_size,'totalItems',v_total,'totalPages',ceil(v_total::numeric/v_size)::int));
end;
$$;

create or replace function public.erp_x_shipping_report_no_delivery(p_order_id uuid,p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_order erp_supply.orders%rowtype;v_delivery erp_supply.deliveries%rowtype;v_task erp_supply.order_tasks%rowtype;
  v_reason text:=nullif(trim(p_payload->>'reason'),'');v_action text:=coalesce(nullif(p_payload->>'requestedAction',''),'REVIEW');v_previous text;
begin
  if not (erp_supply.has_role('ventas') or erp_supply.has_role('super_admin')) then raise exception 'Solo Ventas o Superadministración pueden registrar una no entrega' using errcode='42501'; end if;
  if v_reason is null then raise exception 'Motivo de no entrega requerido'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org for update;
  if not found or (not erp_supply.has_role('super_admin') and v_order.seller_profile_id is distinct from v_actor) then raise exception 'Pedido no disponible para este asesor' using errcode='42501'; end if;
  select * into v_delivery from erp_supply.deliveries where order_id=p_order_id and dispatched_at is not null order by created_at desc limit 1 for update;
  if not found then raise exception 'El pedido todavía no figura como enviado'; end if;
  if v_delivery.status='DELIVERED' or v_order.status='CLOSED' then raise exception 'El pedido ya fue finalizado y no admite una no entrega'; end if;
  v_previous:=v_delivery.status;
  update erp_supply.deliveries set status='NOT_DELIVERED',no_delivery_reason=v_reason,
    metadata=metadata||jsonb_build_object('previousStatus',v_previous,'noDeliveryReportedAt',now(),'requestedAction',v_action,'reportedByRole',(erp_supply.current_roles())[1]),updated_at=now()
  where id=v_delivery.id returning * into v_delivery;
  update erp_supply.orders set metadata=metadata||jsonb_build_object('deliveryExceptionOpen',true,'noDeliveryReason',v_reason,'noDeliveryRequestedAction',v_action,'noDeliveryReportedAt',now()),updated_at=now(),version=version+1 where id=p_order_id returning * into v_order;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if found and v_order.current_step_code in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH','CLOSURE') then
    update erp_supply.task_sessions s set ended_at=now(),raw_seconds=greatest(0,extract(epoch from(now()-s.started_at))::bigint),business_seconds=erp_supply.business_seconds_between(v_org,s.started_at,now()) where s.task_id=v_task.id and s.ended_at is null;
    update erp_supply.order_tasks set status='WAITING',result_code='NO_DELIVERY',result_detail=v_reason,metadata=metadata||jsonb_build_object('requestedAction',v_action) where id=v_task.id;
    update erp_supply.orders set status='WAITING',version=version+1 where id=p_order_id returning * into v_order;
  end if;
  insert into erp_supply.order_comments(order_id,author_profile_id,comment_type,visibility,body,metadata)
  values(p_order_id,v_actor,'NOVELTY','ORDER',v_reason,jsonb_build_object('type','NO_DELIVERY','requestedAction',v_action,'deliveryId',v_delivery.id));
  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_task.id,v_delivery.id,'NO_DELIVERY_REPORTED',v_actor,jsonb_build_object('reason',v_reason,'requestedAction',v_action,'previousStatus',v_previous));
  insert into erp_supply.order_events(organization_id,order_id,task_id,event_type,action_code,from_step_code,to_step_code,from_status,to_status,actor_profile_id,actor_role_code,payload)
  values(v_org,p_order_id,v_task.id,'DOMAIN_RECORD','NO_DELIVERY',v_order.current_step_code,v_order.current_step_code,v_previous,'NOT_DELIVERED',v_actor,(erp_supply.current_roles())[1],jsonb_build_object('reason',v_reason,'requestedAction',v_action,'deliveryId',v_delivery.id));
  return jsonb_build_object('success',true,'delivery',to_jsonb(v_delivery),'order',to_jsonb(v_order));
end;
$$;

-- Regla de seguridad: la acción genérica NO_DELIVERY queda limitada a Ventas/Superadministración.
create or replace function public.erp_x_execute_action(p_order_id uuid,p_action_code text,p_payload jsonb default '{}'::jsonb,p_expected_version integer default null,p_idempotency_key text default null)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare v_actor uuid:=erp_supply.require_profile();v_order erp_supply.orders%rowtype;v_action text:=upper(trim(coalesce(p_action_code,'')));v_type text;
begin
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=erp_supply.current_org_id() and erp_supply.can_view_order(id);
  if not found then raise exception 'Pedido no disponible para este usuario' using errcode='42501'; end if;
  if v_action='NO_DELIVERY' and not (erp_supply.has_role('ventas') or erp_supply.has_role('super_admin')) then raise exception 'Solo Ventas o Superadministración pueden registrar una no entrega' using errcode='42501'; end if;
  if v_action='REPROGRAM' and not erp_supply.actor_can(v_actor,v_order.current_step_code,'RESUME',v_order.current_assignee_id) then raise exception 'No autorizado para reprogramar' using errcode='42501'; end if;
  if v_action='REQUEST_APPROVAL' then
    v_type:=upper(trim(coalesce(p_payload->>'requestType',''));
    if v_type not in('CANCELLATION','PRIORITY','ROUTE_CHANGE','REOPEN','STOCK_EXCEPTION','FLOW_EXCEPTION','PAYMENT_EXCEPTION','DATA_CORRECTION') then raise exception 'Tipo de solicitud inválido'; end if;
    if nullif(trim(p_payload->>'reason'),'') is null then raise exception 'Debe registrar el motivo'; end if;
    if v_type='PRIORITY' and upper(coalesce(p_payload->>'priority','')) not in('LOW','MEDIUM','HIGH','URGENT','CRITICAL') then raise exception 'Prioridad inválida'; end if;
    if v_type='ROUTE_CHANGE' and not exists(select 1 from erp_supply.delivery_routes where code=p_payload->>'route' and active) then raise exception 'Ruta inválida'; end if;
  end if;
  return erp_supply.execute_action_internal(p_order_id,v_action,coalesce(p_payload,'{}'::jsonb),v_actor,false,p_expected_version,p_idempotency_key);
end;
$$;

-- La función heredada tampoco permite que Logística marque una no entrega.
create or replace function public.erp_x_save_delivery(p_order_id uuid,p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare v_actor uuid:=erp_supply.require_profile();v_order erp_supply.orders%rowtype;v_delivery erp_supply.deliveries%rowtype;v_status text:=upper(coalesce(p_payload->>'status','PLANNED'));
begin
  if v_status='NOT_DELIVERED' then
    if not (erp_supply.has_role('ventas') or erp_supply.has_role('super_admin')) then raise exception 'Solo Ventas o Superadministración pueden registrar una no entrega' using errcode='42501'; end if;
  elsif not (erp_supply.can_access_module('shipping','update') or erp_supply.has_role('super_admin')) then raise exception 'No autorizado para despacho' using errcode='42501'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=erp_supply.current_org_id() and erp_supply.can_view_order(id);
  if not found then raise exception 'Pedido no encontrado'; end if;
  if v_status not in('PLANNED','DISPATCHED','IN_TRANSIT','DELIVERED','NOT_DELIVERED','REPROGRAMMED','CANCELLED') then raise exception 'Estado de entrega inválido'; end if;
  if v_status='NOT_DELIVERED' and nullif(trim(p_payload->>'noDeliveryReason'),'') is null then raise exception 'Debe registrar el motivo de no entrega'; end if;
  insert into erp_supply.deliveries(order_id,route_code,status,scheduled_at,dispatched_at,delivered_at,received_by,no_delivery_reason,carrier,tracking_number,assigned_profile_id,metadata)
  values(p_order_id,v_order.delivery_route_code,v_status,nullif(p_payload->>'scheduledAt','')::timestamptz,nullif(p_payload->>'dispatchedAt','')::timestamptz,case when v_status='DELIVERED' then coalesce(nullif(p_payload->>'deliveredAt','')::timestamptz,now()) else nullif(p_payload->>'deliveredAt','')::timestamptz end,p_payload->>'receivedBy',p_payload->>'noDeliveryReason',p_payload->>'carrier',p_payload->>'trackingNumber',v_actor,coalesce(p_payload->'metadata','{}'::jsonb)) returning * into v_delivery;
  return jsonb_build_object('success',true,'delivery',to_jsonb(v_delivery));
end;
$$;

-- Expediente con hitos y tiempos productivos/transcurridos por despacho y cierre.
create or replace function public.erp_x_get_order(p_order_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth
as $$
declare v_org uuid:=erp_supply.current_org_id();v_order erp_supply.orders%rowtype;
begin
  perform erp_supply.require_profile();
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org and erp_supply.can_view_order(id);
  if not found then raise exception 'Pedido no encontrado'; end if;
  return jsonb_build_object(
    'order',to_jsonb(v_order),
    'items',(select coalesce(jsonb_agg(to_jsonb(i) order by line_number),'[]'::jsonb) from erp_supply.order_items i where i.order_id=p_order_id and coalesce(i.metadata->>'receptionActive','true')<>'false'),
    'tasks',(select coalesce(jsonb_agg(to_jsonb(t) order by sequence_no),'[]'::jsonb) from erp_supply.order_tasks t where t.order_id=p_order_id),
    'sessions',(select coalesce(jsonb_agg(to_jsonb(s) order by s.started_at),'[]'::jsonb) from erp_supply.task_sessions s join erp_supply.order_tasks t on t.id=s.task_id where t.order_id=p_order_id),
    'checklist',(select coalesce(jsonb_agg(to_jsonb(c) order by c.sort_order),'[]'::jsonb) from erp_supply.task_checklist c join erp_supply.order_tasks t on t.id=c.task_id where t.order_id=p_order_id),
    'events',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'eventType',e.event_type,'actionCode',e.action_code,'fromStep',e.from_step_code,'toStep',e.to_step_code,'fromStatus',e.from_status,'toStatus',e.to_status,'actorName',p.display_name,'actorRole',e.actor_role_code,'payload',e.payload,'createdAt',e.created_at) order by e.created_at),'[]'::jsonb) from erp_supply.order_events e left join erp_supply.profiles p on p.id=e.actor_profile_id where e.order_id=p_order_id),
    'comments',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'type',c.comment_type,'visibility',c.visibility,'body',c.body,'metadata',c.metadata,'author',p.display_name,'createdAt',c.created_at) order by c.created_at),'[]'::jsonb) from erp_supply.order_comments c join erp_supply.profiles p on p.id=c.author_profile_id where c.order_id=p_order_id),
    'approvals',(select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at),'[]'::jsonb) from erp_supply.approval_requests a where a.order_id=p_order_id),
    'files',(select coalesce(jsonb_agg(to_jsonb(f) order by f.created_at),'[]'::jsonb) from erp_supply.drive_files f where f.order_id=p_order_id),
    'purchaseOrders',(select coalesce(jsonb_agg(to_jsonb(po) order by po.created_at),'[]'::jsonb) from erp_supply.purchase_orders po where po.order_id=p_order_id),
    'financialValidations',(select coalesce(jsonb_agg(to_jsonb(fv) order by fv.created_at),'[]'::jsonb) from erp_supply.financial_validations fv where fv.order_id=p_order_id),
    'receipts',(select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at),'[]'::jsonb) from erp_supply.receipts r where r.order_id=p_order_id),
    'cutJobs',(select coalesce(jsonb_agg(to_jsonb(c) order by c.created_at),'[]'::jsonb) from erp_supply.cut_jobs c where c.order_id=p_order_id),
    'cutRequirements',(select coalesce(jsonb_agg(to_jsonb(r) order by i.line_number),'[]'::jsonb) from erp_supply.cut_requirements r join erp_supply.order_items i on i.id=r.order_item_id where r.order_id=p_order_id),
    'cutBatches',(select coalesce(jsonb_agg(to_jsonb(b) order by b.executed_at),'[]'::jsonb) from erp_supply.cut_batches b where exists(select 1 from erp_supply.cut_requirements r where r.cut_batch_id=b.id and r.order_id=p_order_id)),
    'invoices',(select coalesce(jsonb_agg(to_jsonb(i) order by i.created_at),'[]'::jsonb) from erp_supply.invoices i where i.order_id=p_order_id),
    'deliveries',(select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at),'[]'::jsonb) from erp_supply.deliveries d where d.order_id=p_order_id),
    'deliveryMilestones',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'code',m.milestone_code,'occurredAt',m.occurred_at,'actorName',p.display_name,'metadata',m.metadata) order by m.occurred_at),'[]'::jsonb) from erp_supply.delivery_milestones m left join erp_supply.profiles p on p.id=m.actor_profile_id where m.order_id=p_order_id),
    'deliveryTimeTrace',(select jsonb_build_object(
      'dispatchBusinessSeconds',coalesce(sum(t.business_seconds) filter(where t.step_code in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH')),0),
      'dispatchElapsedSeconds',coalesce(sum(t.raw_seconds) filter(where t.step_code in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH')),0),
      'dispatchQueueBusinessSeconds',coalesce(sum(erp_supply.business_seconds_between(v_org,t.created_at,coalesce(t.started_at,t.completed_at,now()))) filter(where t.step_code in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH')),0),
      'closureBusinessSeconds',coalesce(sum(t.business_seconds) filter(where t.step_code='CLOSURE'),0),
      'closureElapsedSeconds',coalesce(sum(t.raw_seconds) filter(where t.step_code='CLOSURE'),0),
      'closureQueueBusinessSeconds',coalesce(sum(erp_supply.business_seconds_between(v_org,t.created_at,coalesce(t.started_at,t.completed_at,now()))) filter(where t.step_code='CLOSURE'),0),
      'transitBusinessSeconds',coalesce((select erp_supply.business_seconds_between(v_org,d.dispatched_at,coalesce(d.delivered_at,now())) from erp_supply.deliveries d where d.order_id=p_order_id and d.dispatched_at is not null order by d.created_at desc limit 1),0),
      'transitElapsedSeconds',coalesce((select greatest(0,extract(epoch from(coalesce(d.delivered_at,now())-d.dispatched_at))::bigint) from erp_supply.deliveries d where d.order_id=p_order_id and d.dispatched_at is not null order by d.created_at desc limit 1),0),
      'productiveBusinessSeconds',coalesce(sum(t.business_seconds),0),
      'flowBusinessSeconds',erp_supply.business_seconds_between(v_org,v_order.created_at,coalesce(v_order.closed_at,now())),
      'totalElapsedSeconds',greatest(0,extract(epoch from(coalesce(v_order.closed_at,now())-v_order.created_at))::bigint),
      'deadBusinessSeconds',greatest(0,erp_supply.business_seconds_between(v_org,v_order.created_at,coalesce(v_order.closed_at,now()))-coalesce(sum(t.business_seconds),0)),
      'deadTimeSeconds',greatest(0,erp_supply.business_seconds_between(v_org,v_order.created_at,coalesce(v_order.closed_at,now()))-coalesce(sum(t.business_seconds),0))
    ) from erp_supply.order_tasks t where t.order_id=p_order_id),
    'pickingRounds',(select coalesce(jsonb_agg(to_jsonb(r) order by r.round_no),'[]'::jsonb) from erp_supply.picking_rounds r where r.order_id=p_order_id),
    'pickingRoundItems',(select coalesce(jsonb_agg(to_jsonb(ri) order by r.round_no,i.line_number),'[]'::jsonb) from erp_supply.picking_round_items ri join erp_supply.picking_rounds r on r.id=ri.picking_round_id join erp_supply.order_items i on i.id=ri.order_item_id where r.order_id=p_order_id),
    'actions',public.erp_x_get_actions(p_order_id)
  );
end;
$$;

-- Oculta el esquema interno y reconcilia permisos para los RPC nuevos.
revoke all on table erp_supply.delivery_milestones from public,anon,authenticated;
do $$
declare r record;
begin
  for r in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'erp_x_%'
  loop execute format('revoke all on function %s from public,anon,authenticated',r.sig); end loop;
  for r in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'erp_x_%'
  loop execute format('grant execute on function %s to authenticated',r.sig); end loop;
end $$;

notify pgrst,'reload schema';
commit;

-- ============================================================================
-- 026_sales_address_and_simple_shipping_v10_11_6.sql
-- ============================================================================
begin;

-- V10.11.6 · La dirección se registra obligatoriamente en Ventas.
-- Despachos solo agrega la guía y envía el pedido a Cierre.

create or replace function public.erp_x_create_order(p_payload jsonb,p_idempotency_key text default null)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_order erp_supply.orders%rowtype;
  v_task erp_supply.order_tasks%rowtype;
  v_item jsonb;
  v_items jsonb;
  v_initial text;
  v_number text;
  v_order_type text;
  v_payment text;
  v_route text;
  v_client text;
  v_department text;
  v_city text;
  v_address text;
  v_priority text;
  v_requires_purchase boolean;
  v_requires_cut boolean;
  v_item_cut boolean;
  v_has_credit_arrears boolean;
  v_held_by_cashier boolean;
  v_quantity numeric;
  v_cut_length numeric;
  v_requested_date date;
  v_promised_at timestamptz;
  v_line integer:=0;
  v_metadata jsonb;
begin
  if not (erp_supply.can_access_module('orders','create') or erp_supply.can_access_module('sales','create')) then
    raise exception 'Rol no autorizado para crear pedidos' using errcode='42501';
  end if;
  if p_payload is null or jsonb_typeof(p_payload)<>'object' then raise exception 'El pedido debe enviarse como un objeto válido'; end if;

  v_number:=nullif(trim(p_payload->>'orderNumber'),'');
  v_order_type:=upper(nullif(trim(p_payload->>'orderType'),''));
  v_payment:=upper(nullif(trim(p_payload->>'paymentCondition'),''));
  v_route:=upper(nullif(trim(p_payload->>'deliveryRoute'),''));
  v_client:=nullif(trim(p_payload->>'clientName'),'');
  v_department:=nullif(trim(p_payload->>'clientDepartment'),'');
  v_city:=nullif(trim(p_payload->>'clientCity'),'');
  v_address:=nullif(trim(p_payload->>'clientAddress'),'');
  v_priority:=upper(coalesce(nullif(trim(p_payload->>'priority'),''),'MEDIUM'));
  v_requested_date:=erp_supply.safe_date(p_payload->>'requestedDeliveryDate');
  v_promised_at:=erp_supply.safe_timestamptz(p_payload->>'promisedAt');
  v_items:=coalesce(p_payload->'items','[]'::jsonb);

  if v_number is null then raise exception 'Número de pedido requerido'; end if;
  if v_client is null then raise exception 'Cliente requerido'; end if;
  if v_department is null then raise exception 'Departamento de entrega requerido'; end if;
  if v_city is null then raise exception 'Municipio o ciudad de entrega requerido'; end if;
  if v_address is null or length(v_address)<5 then raise exception 'Dirección de entrega requerida'; end if;
  if not exists(select 1 from erp_supply.order_types where code=v_order_type and active) then raise exception 'Tipo de pedido inválido: %',coalesce(v_order_type,'vacío'); end if;
  if not exists(select 1 from erp_supply.payment_conditions where code=v_payment and active) then raise exception 'Condición de pago inválida: %',coalesce(v_payment,'vacía'); end if;
  if not exists(select 1 from erp_supply.delivery_routes where code=v_route and active) then raise exception 'Modalidad de entrega inválida: %',coalesce(v_route,'vacía'); end if;
  if v_priority not in('LOW','MEDIUM','HIGH','URGENT','CRITICAL') then raise exception 'Prioridad inválida'; end if;
  if jsonb_typeof(v_items)<>'array' or jsonb_array_length(v_items)=0 then raise exception 'El pedido debe contener al menos un ítem'; end if;
  if (p_payload ? 'requestedDeliveryDate') and nullif(trim(p_payload->>'requestedDeliveryDate'),'') is not null and v_requested_date is null then raise exception 'Fecha solicitada inválida'; end if;
  if (p_payload ? 'promisedAt') and nullif(trim(p_payload->>'promisedAt'),'') is not null and v_promised_at is null then raise exception 'Fecha prometida inválida'; end if;

  if p_idempotency_key is not null and exists(
    select 1 from erp_supply.order_events where organization_id=v_org and idempotency_key=p_idempotency_key
  ) then
    select o.* into v_order
    from erp_supply.orders o
    join erp_supply.order_events e on e.order_id=o.id
    where e.organization_id=v_org and e.idempotency_key=p_idempotency_key
    limit 1;
    return jsonb_build_object('success',true,'idempotent',true,'orderId',v_order.id,'orderNumber',v_order.order_number,'currentStep',v_order.current_step_code,'status',v_order.status,'version',v_order.version);
  end if;

  v_requires_purchase:=coalesce(
    erp_supply.safe_boolean(p_payload->>'requiresPurchase',null),
    (select requires_purchase_default from erp_supply.order_types where code=v_order_type),
    false
  );
  v_requires_cut:=coalesce(erp_supply.safe_boolean(p_payload->>'requiresCut',false),false);
  v_has_credit_arrears:=v_order_type in('PVC','PVP') and coalesce(erp_supply.safe_boolean(p_payload->>'hasCreditArrears',false),false);
  v_held_by_cashier:=v_order_type='PVN' and coalesce(erp_supply.safe_boolean(p_payload->>'heldByCashier',false),false);

  for v_item in select value from jsonb_array_elements(v_items) loop
    if jsonb_typeof(v_item)<>'object' then raise exception 'Cada línea del pedido debe ser un objeto'; end if;
    v_item_cut:=coalesce(erp_supply.safe_boolean(v_item->>'requiresCut',false),false);
    if v_item_cut then v_requires_cut:=true; end if;
  end loop;

  v_initial:=erp_supply.initial_step(v_order_type,v_payment,v_requires_purchase,v_has_credit_arrears,v_held_by_cashier);
  v_metadata:=(case when jsonb_typeof(coalesce(p_payload->'metadata','{}'::jsonb))='object' then coalesce(p_payload->'metadata','{}'::jsonb) else '{}'::jsonb end)
    ||jsonb_build_object(
      'hasCreditArrears',v_has_credit_arrears,
      'heldByCashier',v_held_by_cashier,
      'initialRouting',v_initial,
      'routingVersion','10.7',
      'clientCountry',coalesce(nullif(trim(p_payload->>'clientCountry'),''),'Colombia'),
      'clientDepartment',v_department,
      'clientCity',v_city,
      'clientAddress',v_address,
      'addressCaptureVersion','10.11.6'
    );

  insert into erp_supply.orders(
    organization_id,order_number,external_reference,order_type_code,payment_condition_code,delivery_route_code,
    client_name,client_document,client_city,client_address,client_phone,seller_profile_id,current_step_code,status,
    priority,requires_cut,requires_purchase,promised_at,requested_delivery_date,metadata
  ) values(
    v_org,v_number,nullif(trim(p_payload->>'externalReference'),''),v_order_type,v_payment,v_route,
    v_client,nullif(trim(p_payload->>'clientDocument'),''),v_city,
    v_address,nullif(trim(p_payload->>'clientPhone'),''),v_actor,v_initial,'QUEUED',
    v_priority,v_requires_cut,v_requires_purchase,v_promised_at,v_requested_date,v_metadata
  ) returning * into v_order;

  for v_item in select value from jsonb_array_elements(v_items) loop
    v_line:=v_line+1;
    v_quantity:=erp_supply.safe_numeric(v_item->>'quantity');
    v_item_cut:=coalesce(erp_supply.safe_boolean(v_item->>'requiresCut',false),false);
    v_cut_length:=erp_supply.safe_numeric(v_item->>'requestedCutLength');
    if nullif(trim(v_item->>'description'),'') is null then raise exception 'La línea % no tiene descripción',v_line; end if;
    if v_quantity is null or v_quantity<=0 then raise exception 'Cantidad inválida en la línea %',v_line; end if;
    if v_item_cut and (v_cut_length is null or v_cut_length<=0) then raise exception 'La línea % requiere una longitud de corte válida',v_line; end if;
    insert into erp_supply.order_items(
      order_id,line_number,sku,reference,description,quantity,unit,warehouse_location,requires_cut,
      requested_cut_length,dimensions,metadata
    ) values(
      v_order.id,coalesce(erp_supply.safe_integer(v_item->>'lineNumber'),v_line),nullif(trim(v_item->>'sku'),''),
      nullif(trim(v_item->>'reference'),''),trim(v_item->>'description'),v_quantity,
      coalesce(nullif(trim(v_item->>'unit'),''),'UND'),nullif(trim(v_item->>'warehouseLocation'),''),v_item_cut,
      v_cut_length,case when jsonb_typeof(coalesce(v_item->'dimensions','{}'::jsonb))='object' then coalesce(v_item->'dimensions','{}'::jsonb) else '{}'::jsonb end,
      case when jsonb_typeof(coalesce(v_item->'metadata','{}'::jsonb))='object' then coalesce(v_item->'metadata','{}'::jsonb) else '{}'::jsonb end
    );
  end loop;

  select * into v_task from erp_supply.create_task(v_order,v_initial,1);
  select * into v_order from erp_supply.orders where id=v_order.id;
  insert into erp_supply.order_events(
    organization_id,order_id,task_id,event_type,action_code,to_step_code,to_status,actor_profile_id,actor_role_code,idempotency_key,payload
  ) values(
    v_org,v_order.id,v_task.id,'ORDER_CREATED','CREATE',v_initial,v_order.status,v_actor,(erp_supply.current_roles())[1],p_idempotency_key,
    p_payload||jsonb_build_object('resolvedInitialStep',v_initial,'hasCreditArrears',v_has_credit_arrears,'heldByCashier',v_held_by_cashier,'clientDepartment',v_department,'clientCity',v_city,'clientAddress',v_address)
  );

  return jsonb_build_object('success',true,'orderId',v_order.id,'orderNumber',v_order.order_number,'currentStep',v_order.current_step_code,'status',v_order.status,'version',v_order.version);
exception
  when unique_violation then raise exception 'Ya existe un pedido con el número %',v_number;
end;
$$;

create or replace function public.erp_x_shipping_send_to_closure(p_order_id uuid,p_payload jsonb default '{}'::jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_order erp_supply.orders%rowtype;
  v_task erp_supply.order_tasks%rowtype;
  v_delivery erp_supply.deliveries%rowtype;
  v_result jsonb;
  v_closure erp_supply.order_tasks%rowtype;
  v_role text:=coalesce((erp_supply.current_roles())[1],'coordinador_logistico');
  v_department text;
  v_municipality text;
  v_address text;
  v_destination jsonb;
begin
  if not (erp_supply.can_access_module('shipping','update') or erp_supply.has_role('super_admin')) then raise exception 'No autorizado para gestionar despachos' using errcode='42501'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org for update;
  if not found or v_order.current_step_code not in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH') then raise exception 'El pedido no está en despacho'; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found or v_task.status<>'IN_PROGRESS' then raise exception 'Primero debes tomar el pedido'; end if;
  if v_task.assigned_profile_id is distinct from v_actor and not (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica')) then raise exception 'El pedido está asignado a otra persona' using errcode='42501'; end if;
  select * into v_delivery from erp_supply.deliveries where order_id=p_order_id order by created_at desc limit 1 for update;
  if not found or nullif(trim(v_delivery.tracking_number),'') is null then raise exception 'Falta registrar la guía'; end if;

  v_department:=coalesce(
    nullif(trim(v_delivery.metadata#>>'{destination,department}'),''),
    nullif(trim(v_order.metadata->>'clientDepartment'),'')
  );
  v_municipality:=coalesce(
    nullif(trim(v_delivery.metadata#>>'{destination,municipality}'),''),
    nullif(trim(v_order.client_city),'')
  );
  v_address:=coalesce(
    nullif(trim(v_delivery.metadata#>>'{destination,address}'),''),
    nullif(trim(v_order.client_address),'')
  );
  if v_municipality is null or v_address is null then
    raise exception 'El pedido no tiene dirección completa. Ventas debe registrar municipio y dirección antes del despacho';
  end if;
  v_destination:=jsonb_build_object(
    'country',coalesce(nullif(trim(v_order.metadata->>'clientCountry'),''),'Colombia'),
    'department',v_department,
    'municipality',v_municipality,
    'address',v_address,
    'source','SALES_ORDER_ADDRESS',
    'capturedAt',coalesce(v_order.metadata->>'addressCapturedAt',v_order.created_at::text)
  );

  update erp_supply.deliveries set status='IN_TRANSIT',dispatched_at=coalesce(dispatched_at,now()),assigned_profile_id=v_actor,
    metadata=metadata||jsonb_build_object('sentToClosureAt',now(),'destination',v_destination),updated_at=now()
  where id=v_delivery.id returning * into v_delivery;
  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_task.id,v_delivery.id,'DISPATCHED',v_actor,jsonb_build_object('trackingNumber',v_delivery.tracking_number,'route',v_order.delivery_route_code,'destination',v_destination));

  v_result:=erp_supply.execute_action_internal(p_order_id,'COMPLETE',jsonb_build_object('detail',coalesce(nullif(p_payload->>'detail',''),'Pedido despachado y enviado a cierre'),'resultCode','DISPATCHED'),v_actor,false,v_order.version,gen_random_uuid()::text);

  select * into v_closure from erp_supply.order_tasks where order_id=p_order_id and step_code='CLOSURE' and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found then raise exception 'No fue posible crear la etapa de cierre'; end if;
  update erp_supply.order_tasks set assigned_profile_id=v_actor,assigned_role_code=v_role,assigned_at=coalesce(assigned_at,now()),status='ASSIGNED',metadata=metadata||jsonb_build_object('source','SHIPPING_V10_11','deliveryId',v_delivery.id)
  where id=v_closure.id returning * into v_closure;
  update erp_supply.orders set current_assignee_id=v_actor,current_role_code=v_role,status='ASSIGNED',version=version+1,updated_at=now() where id=p_order_id returning * into v_order;
  insert into erp_supply.delivery_milestones(organization_id,order_id,task_id,delivery_id,milestone_code,actor_profile_id,metadata)
  values(v_org,p_order_id,v_closure.id,v_delivery.id,'CLOSURE_ASSIGNED',v_actor,jsonb_build_object('previousTaskId',v_task.id));
  return jsonb_build_object('success',true,'orderId',p_order_id,'currentStep','CLOSURE','delivery',to_jsonb(v_delivery),'task',to_jsonb(v_closure));
end;
$$;


-- Normaliza metadatos de pedidos existentes que ya tenían ciudad y dirección.
update erp_supply.orders
set metadata=metadata||jsonb_strip_nulls(jsonb_build_object(
  'clientCountry',coalesce(nullif(metadata->>'clientCountry',''),'Colombia'),
  'clientCity',coalesce(nullif(metadata->>'clientCity',''),client_city),
  'clientAddress',coalesce(nullif(metadata->>'clientAddress',''),client_address)
)),updated_at=updated_at
where (client_city is not null or client_address is not null)
  and (metadata->>'clientCity' is null or metadata->>'clientAddress' is null);

grant execute on function public.erp_x_create_order(jsonb,text) to authenticated;
grant execute on function public.erp_x_shipping_send_to_closure(uuid,jsonb) to authenticated;

notify pgrst,'reload schema';
commit;

-- ============================================================================
-- 028_parallel_flow_exceptions_approvals_v10_12.sql
-- ============================================================================
-- ERP EI V10.12
-- Motor transversal de excepciones, aprobaciones, Compras/Recepción paralela y Corte/Alistamiento paralelo.
-- Base requerida: V10.11.9 + migraciones previas aplicadas.

begin;

create table if not exists erp_supply.order_issues (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references erp_supply.organizations(id),
  order_id uuid not null references erp_supply.orders(id) on delete cascade,
  task_id uuid references erp_supply.order_tasks(id) on delete set null,
  issue_type text not null check (issue_type in ('NOTE','NOVELTY','REPORT')),
  source_code text,
  title text not null,
  detail text not null,
  status text not null default 'OPEN' check (status in ('OPEN','RESOLVED','CLOSED')),
  blocking boolean not null default false,
  target_role_code text references erp_supply.roles(code),
  created_by uuid not null references erp_supply.profiles(id),
  resolved_by uuid references erp_supply.profiles(id),
  resolution text,
  resolution_code text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  metadata jsonb not null default '{}'::jsonb
);
create index if not exists idx_order_issues_open on erp_supply.order_issues(organization_id,status,issue_type,created_at);
create index if not exists idx_order_issues_order on erp_supply.order_issues(order_id,created_at desc);

-- Visibilidad especial y acotada: Recepción puede seguir un PVE mientras Compras sigue siendo la tarea principal.
create or replace function erp_supply.can_view_order_or_reception_shadow(p_order_id uuid)
returns boolean
language sql
stable
security definer
set search_path=erp_supply,public,auth
as $$
  select erp_supply.can_view_order(p_order_id) or exists(
    select 1 from erp_supply.orders o
    where o.id=p_order_id
      and o.organization_id=erp_supply.current_org_id()
      and o.order_type_code='PVE'
      and o.current_step_code in('COMPRAS','RECEPCION_MERCANCIA')
      and erp_supply.has_role('coordinador_logistico')
  )
$$;

-- Permite varias aprobaciones pendientes del mismo tipo si corresponden a excepciones distintas.
drop index if exists erp_supply.uq_pending_approval_type;
create unique index if not exists uq_pending_approval_exception
on erp_supply.approval_requests(order_id,request_type,(coalesce(request_payload->>'exceptionCode','')))
where status='PENDING';

-- Gate transaccional común: una incidencia bloqueante impide retomar o avanzar el flujo.
create or replace function public.erp_x_execute_action(
  p_order_id uuid,p_action_code text,p_payload jsonb default '{}'::jsonb,
  p_expected_version integer default null,p_idempotency_key text default null
)
returns jsonb language plpgsql security definer set search_path=erp_supply,public,auth as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_order erp_supply.orders%rowtype;
  v_action text:=upper(trim(coalesce(p_action_code,'')));
  v_type text;
  v_assigned text;
begin
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=erp_supply.current_org_id() and erp_supply.can_view_order_or_reception_shadow(id);
  if not found then raise exception 'Pedido no disponible para este usuario' using errcode='42501'; end if;

  if v_action in('CLAIM','START','RESUME','COMPLETE') and exists(
    select 1 from erp_supply.order_issues i where i.order_id=p_order_id and i.blocking and i.status='OPEN'
  ) then
    raise exception 'El pedido está en espera por una novedad o reporte. Debes solucionar y cerrar la gestión antes de continuar.';
  end if;

  if v_action='NO_DELIVERY' and not (erp_supply.has_role('ventas') or erp_supply.has_role('super_admin')) then
    raise exception 'Solo Ventas o Superadministración pueden registrar una no entrega' using errcode='42501';
  end if;
  if v_action='REPROGRAM' and not erp_supply.actor_can(v_actor,v_order.current_step_code,'RESUME',v_order.current_assignee_id) then
    raise exception 'No autorizado para reprogramar' using errcode='42501';
  end if;
  if v_action='REQUEST_APPROVAL' then
    v_type:=upper(trim(coalesce(p_payload->>'requestType','')));
    v_assigned:=coalesce(nullif(trim(p_payload->>'assignedRole'),''),'jefe_logistica');
    if v_type not in('CANCELLATION','PRIORITY','ROUTE_CHANGE','REOPEN','STOCK_EXCEPTION','FLOW_EXCEPTION','PAYMENT_EXCEPTION','DATA_CORRECTION') then raise exception 'Tipo de solicitud inválido'; end if;
    if nullif(trim(p_payload->>'reason'),'') is null then raise exception 'Debe registrar el motivo'; end if;
    if v_assigned not in('auditoria','gerencia','jefe_logistica') then raise exception 'La aprobación debe dirigirse a Auditoría, Gerencia o Jefatura Logística'; end if;
    if v_type='PRIORITY' and upper(coalesce(p_payload->>'priority','')) not in('LOW','MEDIUM','HIGH','URGENT','CRITICAL') then raise exception 'Prioridad inválida'; end if;
    if v_type='ROUTE_CHANGE' and not exists(select 1 from erp_supply.delivery_routes where code=p_payload->>'route' and active) then raise exception 'Ruta inválida'; end if;
  end if;
  return erp_supply.execute_action_internal(p_order_id,v_action,coalesce(p_payload,'{}'::jsonb),v_actor,false,p_expected_version,p_idempotency_key);
end;$$;
grant execute on function public.erp_x_execute_action(uuid,text,jsonb,integer,text) to authenticated;

create table if not exists erp_supply.purchase_arrival_state (
  order_id uuid primary key references erp_supply.orders(id) on delete cascade,
  organization_id uuid not null references erp_supply.organizations(id),
  status text not null check (status in ('WAITING','ARRIVED')),
  marked_by uuid not null references erp_supply.profiles(id),
  marked_at timestamptz not null default now(),
  arrived_at timestamptz,
  metadata jsonb not null default '{}'::jsonb
);

create table if not exists erp_supply.picking_prechecks (
  order_item_id uuid primary key references erp_supply.order_items(id) on delete cascade,
  organization_id uuid not null references erp_supply.organizations(id),
  order_id uuid not null references erp_supply.orders(id) on delete cascade,
  task_id uuid references erp_supply.order_tasks(id) on delete set null,
  result text not null check (result in ('FOUND','MISSING')),
  novelty text,
  checked_by uuid not null references erp_supply.profiles(id),
  checked_at timestamptz not null default now(),
  metadata jsonb not null default '{}'::jsonb,
  check (result='FOUND' or nullif(trim(novelty),'') is not null)
);
create index if not exists idx_picking_prechecks_order on erp_supply.picking_prechecks(order_id,checked_at);

-- El pedido principal siempre entra a Alistamiento; las líneas de Corte se gestionan en paralelo.
create or replace function erp_supply.next_step(
  p_current_step text,
  p_order_type text,
  p_payment_condition text,
  p_delivery_route text,
  p_requires_cut boolean,
  p_requires_purchase boolean
)
returns text
language sql
immutable
as $$
  select case p_current_step
    when 'CARTERA' then 'RECEPCION_PEDIDO'
    when 'CAJA' then 'RECEPCION_PEDIDO'
    when 'COMPRAS' then 'RECEPCION_MERCANCIA'
    when 'RECEPCION_MERCANCIA' then 'RECEPCION_PEDIDO'
    when 'RECEPCION_PEDIDO' then 'ALISTAMIENTO'
    when 'CORTE' then 'ALISTAMIENTO'
    when 'ALISTAMIENTO' then case when upper(p_order_type) in('PVN','PNV') then 'CAJA_FACTURACION' else 'FACTURACION' end
    when 'CAJA_FACTURACION' then p_delivery_route
    when 'FACTURACION' then p_delivery_route
    when 'CLIENT_POINT' then 'CLOSURE'
    when 'CLIENT_PICKUP' then 'CLOSURE'
    when 'LOCAL_DISPATCH' then 'CLOSURE'
    when 'NATIONAL_DISPATCH' then 'CLOSURE'
    when 'CLOSURE' then 'CLOSED'
    else 'CLOSED'
  end
$$;

create or replace function erp_supply.sync_parallel_cut_requirements(p_order_id uuid)
returns integer
language plpgsql
security definer
set search_path=erp_supply,public
as $$
declare
  v_order erp_supply.orders%rowtype;
  v_cut_profile uuid;
  v_count integer:=0;
begin
  select * into v_order from erp_supply.orders where id=p_order_id for update;
  if not found then return 0; end if;
  v_cut_profile:=erp_supply.safe_uuid(v_order.metadata#>>'{receptionAssignment,cutProfileId}');

  delete from erp_supply.cut_requirements r
  where r.order_id=p_order_id and r.process_status='PENDING'
    and not exists(select 1 from erp_supply.order_items i where i.id=r.order_item_id and i.requires_cut and coalesce(i.metadata->>'receptionActive','true')<>'false');

  insert into erp_supply.cut_requirements(
    organization_id,order_id,order_item_id,task_id,group_key,sku,reference,description,
    unit,units_required,length_each,total_length,assigned_profile_id,metadata
  )
  select v_order.organization_id,v_order.id,i.id,null,
    erp_supply.cut_group_key(i.reference,i.sku,i.description),i.sku,i.reference,i.description,
    'M',i.quantity,i.requested_cut_length,round((i.quantity*i.requested_cut_length)::numeric,4),v_cut_profile,
    jsonb_build_object('lineNumber',i.line_number,'source','PARALLEL_CUT_V10_12')
  from erp_supply.order_items i
  where i.order_id=v_order.id and coalesce(i.metadata->>'receptionActive','true')<>'false'
    and i.requires_cut and i.requested_cut_length is not null and i.requested_cut_length>0
  on conflict(order_item_id) do update set
    group_key=excluded.group_key,sku=excluded.sku,reference=excluded.reference,description=excluded.description,
    units_required=excluded.units_required,length_each=excluded.length_each,total_length=excluded.total_length,
    assigned_profile_id=coalesce(excluded.assigned_profile_id,erp_supply.cut_requirements.assigned_profile_id),
    metadata=erp_supply.cut_requirements.metadata||excluded.metadata,updated_at=now();
  get diagnostics v_count=row_count;
  update erp_supply.orders set metadata=metadata||jsonb_build_object('cutFlow',coalesce(metadata->'cutFlow','{}'::jsonb)||jsonb_build_object(
    'version','10.12','parallel',true,'syncedAt',now(),'pendingRequirements',(select count(*) from erp_supply.cut_requirements where order_id=p_order_id and process_status<>'READY')
  )),updated_at=now() where id=p_order_id;
  return v_count;
end;
$$;

create or replace function erp_supply.trg_parallel_cut_sync()
returns trigger language plpgsql security definer set search_path=erp_supply,public as $$
begin
  if new.current_step_code='RECEPCION_PEDIDO' and (
    new.requires_cut is distinct from old.requires_cut or new.metadata#>'{receptionAssignment}' is distinct from old.metadata#>'{receptionAssignment}'
  ) then perform erp_supply.sync_parallel_cut_requirements(new.id); end if;
  return new;
end;
$$;
drop trigger if exists trg_parallel_cut_sync on erp_supply.orders;
create trigger trg_parallel_cut_sync after update of requires_cut,metadata on erp_supply.orders
for each row execute function erp_supply.trg_parallel_cut_sync();

-- Migra pedidos activos que habían quedado con CORTE como etapa principal en V10.10.
-- Se conserva toda la trazabilidad de Corte, pero la tarea principal pasa a Alistamiento.
do $$
declare
  r record;
  v_order erp_supply.orders%rowtype;
  v_task erp_supply.order_tasks%rowtype;
  v_new_task erp_supply.order_tasks%rowtype;
  v_seq integer;
begin
  for r in select id from erp_supply.orders where current_step_code='CORTE' and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') loop
    select * into v_task from erp_supply.order_tasks where order_id=r.id and step_code='CORTE' and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
    if found then
      update erp_supply.task_sessions s set ended_at=now(),raw_seconds=greatest(0,extract(epoch from(now()-s.started_at))::bigint),business_seconds=erp_supply.business_seconds_between((select organization_id from erp_supply.orders where id=r.id),s.started_at,now()),note=coalesce(s.note,'')||' · Migrada a Corte paralelo V10.12' where s.task_id=v_task.id and s.ended_at is null;
      update erp_supply.order_tasks set status='CANCELLED',completed_at=now(),result_code='PARALLEL_CUT_MIGRATION',result_detail='Corte continúa como subflujo paralelo; Alistamiento pasa a ser la etapa principal' where id=v_task.id;
    end if;
    select * into v_order from erp_supply.orders where id=r.id for update;
    v_seq:=(select coalesce(max(sequence_no),0)+1 from erp_supply.order_tasks where order_id=r.id);
    perform erp_supply.create_task(v_order,'ALISTAMIENTO',v_seq);
    select * into v_new_task from erp_supply.order_tasks where order_id=r.id and step_code='ALISTAMIENTO' and sequence_no=v_seq order by created_at desc limit 1;
    perform erp_supply.sync_parallel_cut_requirements(r.id);
    update erp_supply.orders set
      current_step_code='ALISTAMIENTO',
      current_role_code=v_new_task.assigned_role_code,
      current_assignee_id=v_new_task.assigned_profile_id,
      status=v_new_task.status,
      updated_at=now(),
      version=version+1,
      metadata=metadata||jsonb_build_object('cutFlowMigration',jsonb_build_object('from','CORTE','to','ALISTAMIENTO','at',now(),'version','10.12'))
    where id=r.id;
  end loop;
end;$$;

-- Funciones de Corte ajustadas para consumir cut_requirements aunque el pedido principal esté en Alistamiento.
create or replace function public.erp_x_cutting_groups(
  p_search text default null,
  p_page integer default 1,
  p_page_size integer default 50
)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_org uuid:=erp_supply.current_org_id();
  v_actor uuid:=erp_supply.require_profile();
  v_page integer:=greatest(coalesce(p_page,1),1);
  v_size integer:=least(greatest(coalesce(p_page_size,50),1),100);
  v_override boolean:=erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica');
  v_total bigint;
  v_items jsonb;
begin
  if not (erp_supply.can_access_module('cutting','read') or erp_supply.has_role('auxiliar_corte') or v_override) then
    raise exception 'No autorizado para consultar Corte' using errcode='42501';
  end if;
  with eligible as (
    select r.* from erp_supply.cut_requirements r
    join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
    where r.organization_id=v_org and r.process_status<>'READY'
      and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
      and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)
      and (p_search is null or p_search='' or lower(coalesce(r.reference,'')||' '||coalesce(r.sku,'')||' '||r.description) like '%'||lower(p_search)||'%')
  ), grouped as (select group_key from eligible group by group_key)
  select count(*) into v_total from grouped;
  with eligible as (
    select r.*,o.order_number,o.client_name,o.priority from erp_supply.cut_requirements r
    join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
    where r.organization_id=v_org and r.process_status<>'READY'
      and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
      and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)
      and (p_search is null or p_search='' or lower(coalesce(r.reference,'')||' '||coalesce(r.sku,'')||' '||r.description) like '%'||lower(p_search)||'%')
  ), grouped as (
    select group_key,max(reference) reference,max(sku) sku,max(description) description,
      count(*)::integer item_count,count(distinct order_id)::integer order_count,
      sum(units_required) cut_count,sum(total_length) total_length,min(created_at) oldest_at,
      bool_or(process_status='IN_PROGRESS') in_progress
    from eligible group by group_key order by in_progress desc,oldest_at offset (v_page-1)*v_size limit v_size
  )
  select coalesce(jsonb_agg(jsonb_build_object('groupKey',group_key,'reference',reference,'sku',sku,'description',description,
    'itemCount',item_count,'orderCount',order_count,'cutCount',cut_count,'totalLength',total_length,'oldestAt',oldest_at,'inProgress',in_progress)),'[]'::jsonb)
  into v_items from grouped;
  return jsonb_build_object('items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_size,'totalItems',v_total,'totalPages',ceil(v_total::numeric/v_size)::integer),'generatedAt',now());
end;
$$;

create or replace function public.erp_x_cutting_group(p_group_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_org uuid:=erp_supply.current_org_id();
  v_actor uuid:=erp_supply.require_profile();
  v_override boolean:=erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica');
  v_reference text;v_sku text;v_description text;
begin
  if nullif(trim(p_group_key),'') is null then raise exception 'Grupo de corte requerido'; end if;
  if not (erp_supply.can_access_module('cutting','read') or erp_supply.has_role('auxiliar_corte') or v_override) then raise exception 'No autorizado para consultar Corte' using errcode='42501'; end if;
  select max(r.reference),max(r.sku),max(r.description) into v_reference,v_sku,v_description
  from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
  where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
    and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
    and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor);
  if v_description is null then raise exception 'El grupo ya no tiene cortes pendientes'; end if;
  return jsonb_build_object(
    'group',jsonb_build_object('groupKey',p_group_key,'reference',v_reference,'sku',v_sku,'description',v_description,
      'itemCount',(select count(*) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
      'orderCount',(select count(distinct r.order_id) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
      'cutCount',(select coalesce(sum(r.units_required),0) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
      'totalLength',(select coalesce(sum(r.total_length),0) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor))
    ),
    'items',(select coalesce(jsonb_agg(jsonb_build_object('requirementId',r.id,'orderId',r.order_id,'orderNumber',o.order_number,'clientName',o.client_name,
      'priority',o.priority,'orderItemId',r.order_item_id,'lineNumber',i.line_number,'sku',r.sku,'reference',r.reference,'description',r.description,'unit',r.unit,
      'unitsRequired',r.units_required,'lengthEach',r.length_each,'totalLength',r.total_length,'processStatus',r.process_status,
      'taskStatus',case when r.process_status='IN_PROGRESS' then 'IN_PROGRESS' else 'PENDING' end,'assigneeId',r.assigned_profile_id,'assigneeName',p.display_name
    ) order by o.priority desc,o.order_number,i.line_number),'[]'::jsonb)
      from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
      join erp_supply.order_items i on i.id=r.order_item_id left join erp_supply.profiles p on p.id=r.assigned_profile_id
      where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
        and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
        and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
    'reels',(select coalesce(jsonb_agg(jsonb_build_object('lotId',l.id,'inventoryItemId',ii.id,'lotNumber',l.lot_number,'location',l.location,'quantityAvailable',l.quantity_available,'unit',ii.unit,'updatedAt',ii.updated_at) order by l.quantity_available desc),'[]'::jsonb)
      from erp_supply.inventory_items ii join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
      where ii.organization_id=v_org and ii.active and l.quantity_available>0 and ((v_sku is not null and ii.sku=v_sku) or (v_reference is not null and ii.reference=v_reference) or ii.metadata->>'cutGroupKey'=p_group_key)),
    'recentBatches',(select coalesce(jsonb_agg(to_jsonb(b) order by b.executed_at desc),'[]'::jsonb) from (select * from erp_supply.cut_batches where organization_id=v_org and group_key=p_group_key order by executed_at desc limit 5) b)
  );
end;
$$;

create or replace function public.erp_x_execute_cut_group(p_group_key text,p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_override boolean:=erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica');
  v_reel numeric:=erp_supply.safe_numeric(p_payload->>'reelLength');
  v_scrap numeric:=coalesce(erp_supply.safe_numeric(p_payload->>'scrapLength'),0);
  v_needed numeric;
  v_reference text;
  v_sku text;
  v_description text;
  v_inventory_item erp_supply.inventory_items%rowtype;
  v_lot erp_supply.inventory_lots%rowtype;
  v_lot_id uuid:=erp_supply.safe_uuid(p_payload->>'inventoryLotId');
  v_batch erp_supply.cut_batches%rowtype;
  v_req erp_supply.cut_requirements%rowtype;
  v_job erp_supply.cut_jobs%rowtype;
  v_orders uuid[]:='{}'::uuid[];
  v_order_id uuid;
  v_difference numeric;
  v_count integer:=0;
begin
  if not (erp_supply.can_access_module('cutting','update') or erp_supply.has_role('auxiliar_corte') or v_override) then
    raise exception 'No autorizado para ejecutar cortes' using errcode='42501';
  end if;
  if nullif(trim(p_group_key),'') is null then raise exception 'Grupo de corte requerido'; end if;
  if v_reel is null or v_reel<=0 then raise exception 'Indica cuánto tiene el carreto'; end if;
  if v_scrap<0 then raise exception 'La merma no puede ser negativa'; end if;

  select coalesce(sum(r.total_length),0),max(r.reference),max(r.sku),max(r.description)
  into v_needed,v_reference,v_sku,v_description
  from erp_supply.cut_requirements r
  join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
  where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
   
    and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
    and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor);
  if v_needed<=0 then raise exception 'El grupo ya no tiene cortes pendientes'; end if;
  if v_reel<v_needed+v_scrap then
    raise exception 'El carreto tiene % y se necesitan % incluyendo la merma',v_reel,v_needed+v_scrap;
  end if;
  if (v_reel-v_needed-v_scrap)>0 and (v_reel-v_needed-v_scrap)<50 and not exists(
    select 1 from erp_supply.approval_requests a
    where a.order_id in (
      select r2.order_id from erp_supply.cut_requirements r2
      where r2.organization_id=v_org and r2.group_key=p_group_key and r2.process_status<>'READY'
    )
      and a.request_type='STOCK_EXCEPTION'
      and upper(coalesce(a.request_payload->>'exceptionCode',''))='LOW_REEL_REMAINDER'
      and a.request_payload->>'groupKey'=p_group_key
      and a.status in('APPROVED','EXECUTED')
  ) then
    raise exception 'APROBACION_REQUERIDA: el remanente quedaría en % m, menor a 50 m. Solicita aprobación antes de ejecutar el corte.', round(v_reel-v_needed-v_scrap,3);
  end if;

  select * into v_inventory_item
  from erp_supply.inventory_items ii
  where ii.organization_id=v_org
    and ((v_sku is not null and ii.sku=v_sku) or (v_reference is not null and ii.reference=v_reference)
      or ii.metadata->>'cutGroupKey'=p_group_key)
  order by (ii.metadata->>'cutGroupKey'=p_group_key) desc limit 1 for update;

  if not found then
    insert into erp_supply.inventory_items(organization_id,sku,reference,description,unit,item_type,metadata)
    values(v_org,coalesce(v_sku,v_reference,'CUT-'||substr(p_group_key,1,12)),v_reference,v_description,'M','CUT_REEL',jsonb_build_object('cutGroupKey',p_group_key,'source','CUT_FIRST_V10_10'))
    returning * into v_inventory_item;
  else
    update erp_supply.inventory_items set metadata=metadata||jsonb_build_object('cutGroupKey',p_group_key),updated_at=now()
    where id=v_inventory_item.id returning * into v_inventory_item;
  end if;

  if v_lot_id is not null then
    select * into v_lot from erp_supply.inventory_lots
    where id=v_lot_id and inventory_item_id=v_inventory_item.id for update;
    if not found then raise exception 'El carreto seleccionado no corresponde a esta referencia'; end if;
    v_difference:=v_reel-v_lot.quantity_available;
    if abs(v_difference)>0.0001 then
      update erp_supply.inventory_lots set quantity_available=v_reel where id=v_lot.id returning * into v_lot;
      insert into erp_supply.inventory_movements(
        organization_id,inventory_item_id,lot_id,movement_type,quantity,unit,from_location,to_location,
        actor_profile_id,reference,metadata
      ) values(
        v_org,v_inventory_item.id,v_lot.id,case when v_difference>0 then 'ADJUSTMENT_IN' else 'ADJUSTMENT_OUT' end,
        abs(v_difference),'M',v_lot.location,v_lot.location,v_actor,'RECUENTO-CARRETO',
        jsonb_build_object('previousLength',v_reel-v_difference,'confirmedLength',v_reel,'source','CUT_FIRST_V10_10')
      );
    end if;
  else
    insert into erp_supply.inventory_lots(
      inventory_item_id,lot_number,location,quantity_available,received_at,metadata
    ) values(
      v_inventory_item.id,
      coalesce(nullif(trim(p_payload->>'lotNumber'),''),'CARRETO-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISS-MS')),
      coalesce(nullif(trim(p_payload->>'location'),''),'CORTE'),v_reel,now(),
      jsonb_build_object('cutGroupKey',p_group_key,'source','CUT_FIRST_V10_10')
    ) returning * into v_lot;
    insert into erp_supply.inventory_movements(
      organization_id,inventory_item_id,lot_id,movement_type,quantity,unit,to_location,
      actor_profile_id,reference,metadata
    ) values(v_org,v_inventory_item.id,v_lot.id,'CUT_REEL_ENTRY',v_reel,'M',v_lot.location,v_actor,v_lot.lot_number,jsonb_build_object('source','CUT_FIRST_V10_10'));
  end if;

  insert into erp_supply.cut_batches(
    organization_id,group_key,reference,description,inventory_item_id,inventory_lot_id,
    resolution_code,reel_initial_length,requested_length,scrap_length,remaining_length,executed_by,metadata
  ) values(
    v_org,p_group_key,v_reference,v_description,v_inventory_item.id,v_lot.id,'CUT',
    v_reel,v_needed,v_scrap,v_reel-v_needed-v_scrap,v_actor,
    jsonb_build_object('lotNumber',v_lot.lot_number,'location',v_lot.location,'version','10.10')
  ) returning * into v_batch;

  for v_req in
    select r.*
    from erp_supply.cut_requirements r
    join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
    where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
     
      and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
      and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)
    order by r.created_at for update of r
  loop
    -- V10.12: Corte es subflujo paralelo; no reclama la tarea principal de Alistamiento.
    insert into erp_supply.cut_jobs(
      order_id,order_item_id,inventory_lot_id,requested_length,actual_length,scrap_length,
      status,assigned_profile_id,started_at,completed_at,metadata
    ) values(
      v_req.order_id,v_req.order_item_id,v_lot.id,v_req.total_length,v_req.total_length,0,
      'COMPLETED',v_actor,now(),now(),jsonb_build_object(
        'mode','CUT','batchId',v_batch.id,'units',v_req.units_required,'lengthEach',v_req.length_each,'cutFlowVersion','10.10'
      )
    ) returning * into v_job;

    update erp_supply.cut_requirements
    set process_status='READY',resolution_code='CUT',collection_status='PENDING',
        cut_batch_id=v_batch.id,cut_job_id=v_job.id,inventory_lot_id=v_lot.id,
        ready_at=now(),ready_by=v_actor,assigned_profile_id=v_actor,updated_at=now()
    where id=v_req.id;

    update erp_supply.order_items
    set metadata=metadata||jsonb_build_object(
      'cutStatus','READY','cutResolution','CUT','cutRequirementId',v_req.id,
      'cutBatchId',v_batch.id,'cutReadyAt',now(),'cutReadyBy',v_actor
    ),updated_at=now() where id=v_req.order_item_id;

    if not (v_req.order_id=any(v_orders)) then v_orders:=array_append(v_orders,v_req.order_id); end if;
    v_count:=v_count+1;
  end loop;

  update erp_supply.inventory_lots
  set quantity_available=v_reel-v_needed-v_scrap,
      metadata=metadata||jsonb_build_object('lastCutBatchId',v_batch.id,'lastCutAt',now())
  where id=v_lot.id;

  insert into erp_supply.inventory_movements(
    organization_id,inventory_item_id,lot_id,movement_type,quantity,unit,from_location,
    actor_profile_id,reference,metadata
  ) values(
    v_org,v_inventory_item.id,v_lot.id,'CUT_CONSUMPTION',v_needed+v_scrap,'M',v_lot.location,
    v_actor,v_batch.id::text,jsonb_build_object('requestedLength',v_needed,'scrapLength',v_scrap,'remainingLength',v_reel-v_needed-v_scrap,'groupKey',p_group_key)
  );

  foreach v_order_id in array v_orders loop
    perform erp_supply.advance_cut_order_if_ready(v_order_id,v_actor);
  end loop;

  return jsonb_build_object('success',true,'batchId',v_batch.id,'processedItems',v_count,
    'requestedLength',v_needed,'scrapLength',v_scrap,'remainingLength',v_reel-v_needed-v_scrap,
    'inventoryLotId',v_lot.id,'lotNumber',v_lot.lot_number);
end;
$$;

create or replace function public.erp_x_resolve_cut_requirement(
  p_requirement_id uuid,
  p_resolution text,
  p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_override boolean:=erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica');
  v_resolution text:=upper(trim(coalesce(p_resolution,'')));
  v_req erp_supply.cut_requirements%rowtype;
  v_order erp_supply.orders%rowtype;
  v_reason text:=nullif(trim(p_payload->>'reason'),'');
  v_reel numeric:=erp_supply.safe_numeric(p_payload->>'reelLength');
  v_inventory_item erp_supply.inventory_items%rowtype;
  v_lot erp_supply.inventory_lots%rowtype;
  v_lot_id uuid:=erp_supply.safe_uuid(p_payload->>'inventoryLotId');
  v_batch erp_supply.cut_batches%rowtype;
  v_job erp_supply.cut_jobs%rowtype;
  v_difference numeric;
begin
  if not (erp_supply.can_access_module('cutting','update') or erp_supply.has_role('auxiliar_corte') or v_override) then
    raise exception 'No autorizado para resolver cortes' using errcode='42501';
  end if;
  if v_resolution not in('FULL_REEL','NO_CUT') then raise exception 'Resolución de corte inválida'; end if;

  select r.* into v_req
  from erp_supply.cut_requirements r
  where r.id=p_requirement_id and r.organization_id=v_org and r.process_status<>'READY'
    and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)
  for update of r;
  if not found then raise exception 'El corte ya fue resuelto o no está disponible'; end if;

  select * into v_order from erp_supply.orders where id=v_req.order_id and status not in('CLOSED','CANCELLED') for update;
  if not found then raise exception 'El pedido ya no está activo'; end if;
  if exists(select 1 from erp_supply.order_issues oi where oi.order_id=v_order.id and oi.blocking and oi.status='OPEN') then
    raise exception 'El pedido está detenido por una novedad o reporte pendiente. Resuélvelo antes de continuar Corte.';
  end if;
  -- V10.12: Corte es subflujo paralelo; no reclama la tarea principal de Alistamiento.

  if v_resolution='NO_CUT' then
    if v_reason is null then raise exception 'Explica por qué la referencia no necesita corte'; end if;

    update erp_supply.cut_requirements
    set process_status='READY',resolution_code='NO_CUT',collection_status='PENDING',
        ready_at=now(),ready_by=v_actor,assigned_profile_id=v_actor,
        metadata=metadata||jsonb_build_object('reason',v_reason),updated_at=now()
    where id=v_req.id;

    update erp_supply.order_items
    set requires_cut=false,requested_cut_length=null,
        metadata=metadata||jsonb_build_object(
          'cutStatus','READY','cutResolution','NO_CUT','cutRequirementId',v_req.id,
          'cutReadyAt',now(),'cutReadyBy',v_actor,'cutNoNeedReason',v_reason,
          'originalRequestedCutLength',v_req.length_each
        ),updated_at=now()
    where id=v_req.order_item_id;

    insert into erp_supply.order_comments(order_id,author_profile_id,comment_type,visibility,body,metadata)
    values(v_req.order_id,v_actor,'NOVELTY','INTERNAL',
      format('Corte corregido: la referencia %s no necesita corte. %s',coalesce(v_req.reference,v_req.sku,v_req.description),v_reason),
      jsonb_build_object('source','CORTE','resolution','NO_CUT','requirementId',v_req.id));
  else
    if v_reel is null or v_reel<=0 then raise exception 'Indica la medida del carreto completo'; end if;
    if abs(v_reel-v_req.total_length)>0.0001 then
      raise exception 'Carreto completo solo aplica cuando la medida del carreto (%) coincide con lo solicitado (%)',v_reel,v_req.total_length;
    end if;

    select * into v_inventory_item from erp_supply.inventory_items ii
    where ii.organization_id=v_org and ((v_req.sku is not null and ii.sku=v_req.sku)
      or (v_req.reference is not null and ii.reference=v_req.reference)
      or ii.metadata->>'cutGroupKey'=v_req.group_key)
    order by (ii.metadata->>'cutGroupKey'=v_req.group_key) desc limit 1 for update;

    if not found then
      insert into erp_supply.inventory_items(organization_id,sku,reference,description,unit,item_type,metadata)
      values(v_org,coalesce(v_req.sku,v_req.reference,'CUT-'||substr(v_req.group_key,1,12)),v_req.reference,v_req.description,'M','CUT_REEL',jsonb_build_object('cutGroupKey',v_req.group_key,'source','CUT_FIRST_V10_10'))
      returning * into v_inventory_item;
    end if;

    if v_lot_id is not null then
      select * into v_lot from erp_supply.inventory_lots where id=v_lot_id and inventory_item_id=v_inventory_item.id for update;
      if not found then raise exception 'El carreto seleccionado no corresponde a esta referencia'; end if;
      v_difference:=v_reel-v_lot.quantity_available;
      if abs(v_difference)>0.0001 then
        update erp_supply.inventory_lots set quantity_available=v_reel where id=v_lot.id returning * into v_lot;
        insert into erp_supply.inventory_movements(organization_id,inventory_item_id,lot_id,movement_type,quantity,unit,from_location,to_location,actor_profile_id,reference,metadata)
        values(v_org,v_inventory_item.id,v_lot.id,case when v_difference>0 then 'ADJUSTMENT_IN' else 'ADJUSTMENT_OUT' end,abs(v_difference),'M',v_lot.location,v_lot.location,v_actor,'RECUENTO-CARRETO',jsonb_build_object('confirmedLength',v_reel));
      end if;
    else
      insert into erp_supply.inventory_lots(inventory_item_id,lot_number,location,quantity_available,received_at,metadata)
      values(v_inventory_item.id,coalesce(nullif(trim(p_payload->>'lotNumber'),''),'CARRETO-'||to_char(clock_timestamp(),'YYYYMMDD-HH24MISS-MS')),coalesce(nullif(trim(p_payload->>'location'),''),'CORTE'),v_reel,now(),jsonb_build_object('cutGroupKey',v_req.group_key,'source','CUT_FIRST_V10_10'))
      returning * into v_lot;
      insert into erp_supply.inventory_movements(organization_id,inventory_item_id,lot_id,movement_type,quantity,unit,to_location,actor_profile_id,reference,metadata)
      values(v_org,v_inventory_item.id,v_lot.id,'CUT_REEL_ENTRY',v_reel,'M',v_lot.location,v_actor,v_lot.lot_number,jsonb_build_object('source','CUT_FIRST_V10_10'));
    end if;

    insert into erp_supply.cut_batches(organization_id,group_key,reference,description,inventory_item_id,inventory_lot_id,resolution_code,reel_initial_length,requested_length,scrap_length,remaining_length,executed_by,metadata)
    values(v_org,v_req.group_key,v_req.reference,v_req.description,v_inventory_item.id,v_lot.id,'FULL_REEL',v_reel,v_req.total_length,0,0,v_actor,jsonb_build_object('requirementId',v_req.id,'version','10.10'))
    returning * into v_batch;

    insert into erp_supply.cut_jobs(order_id,order_item_id,inventory_lot_id,requested_length,actual_length,scrap_length,status,assigned_profile_id,started_at,completed_at,metadata)
    values(v_req.order_id,v_req.order_item_id,v_lot.id,v_req.total_length,v_req.total_length,0,'COMPLETED',v_actor,now(),now(),jsonb_build_object('mode','FULL_REEL','batchId',v_batch.id,'cutFlowVersion','10.10'))
    returning * into v_job;

    update erp_supply.inventory_lots set quantity_available=0,metadata=metadata||jsonb_build_object('issuedCompleteAt',now(),'cutBatchId',v_batch.id) where id=v_lot.id;
    insert into erp_supply.inventory_movements(organization_id,inventory_item_id,lot_id,order_id,movement_type,quantity,unit,from_location,actor_profile_id,reference,metadata)
    values(v_org,v_inventory_item.id,v_lot.id,v_req.order_id,'FULL_REEL_ISSUE',v_req.total_length,'M',v_lot.location,v_actor,v_batch.id::text,jsonb_build_object('requirementId',v_req.id));

    update erp_supply.cut_requirements
    set process_status='READY',resolution_code='FULL_REEL',collection_status='PENDING',
        cut_batch_id=v_batch.id,cut_job_id=v_job.id,inventory_lot_id=v_lot.id,
        ready_at=now(),ready_by=v_actor,assigned_profile_id=v_actor,updated_at=now()
    where id=v_req.id;

    update erp_supply.order_items
    set metadata=metadata||jsonb_build_object(
      'cutStatus','READY','cutResolution','FULL_REEL','cutRequirementId',v_req.id,
      'cutBatchId',v_batch.id,'cutReadyAt',now(),'cutReadyBy',v_actor
    ),updated_at=now() where id=v_req.order_item_id;
  end if;

  insert into erp_supply.order_events(organization_id,order_id,task_id,event_type,action_code,from_step_code,to_step_code,actor_profile_id,actor_role_code,payload)
  values(v_org,v_req.order_id,v_req.task_id,'DOMAIN_RECORD',v_resolution,'CORTE','CORTE',v_actor,(erp_supply.current_roles())[1],jsonb_build_object('requirementId',v_req.id,'reason',v_reason));

  perform erp_supply.advance_cut_order_if_ready(v_req.order_id,v_actor);
  return jsonb_build_object('success',true,'requirementId',v_req.id,'resolution',v_resolution,'orderId',v_req.order_id);
end;
$$;


-- Al terminar Corte ya no se mueve la tarea principal; solo queda lista la recogida.
create or replace function erp_supply.advance_cut_order_if_ready(p_order_id uuid,p_actor uuid)
returns boolean language plpgsql security definer set search_path=erp_supply,public as $$
begin
  if exists(select 1 from erp_supply.cut_requirements where order_id=p_order_id and process_status<>'READY') then return false; end if;
  update erp_supply.orders set metadata=metadata||jsonb_build_object('cutFlow',coalesce(metadata->'cutFlow','{}'::jsonb)||jsonb_build_object(
    'completedAt',now(),'completedBy',p_actor,'parallel',true,
    'pendingCollection',(select count(*) from erp_supply.cut_requirements where order_id=p_order_id and collection_status='PENDING')
  )),updated_at=now(),version=version+1 where id=p_order_id;
  return found;
end;
$$;

-- Avance parcial de Alistamiento mientras Corte trabaja.
create or replace function public.erp_x_picking_precheck(p_order_id uuid)
returns jsonb language plpgsql stable security definer set search_path=erp_supply,public,auth as $$
declare v_org uuid:=erp_supply.current_org_id();begin
  perform erp_supply.require_profile();
  if not exists(select 1 from erp_supply.orders where id=p_order_id and organization_id=v_org and erp_supply.can_view_order(id)) then raise exception 'Pedido no disponible' using errcode='42501'; end if;
  return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object(
    'orderItemId',p.order_item_id,'result',p.result,'novelty',p.novelty,'checkedAt',p.checked_at,'checkedBy',pr.display_name
  ) order by p.checked_at),'[]'::jsonb) from erp_supply.picking_prechecks p left join erp_supply.profiles pr on pr.id=p.checked_by where p.order_id=p_order_id));
end;$$;

create or replace function public.erp_x_save_picking_precheck(p_order_id uuid,p_items jsonb)
returns jsonb language plpgsql security definer set search_path=erp_supply,public,auth as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_task erp_supply.order_tasks%rowtype;v_row jsonb;v_item erp_supply.order_items%rowtype;v_id uuid;v_result text;v_novelty text;v_count int:=0;begin
  if not (erp_supply.can_access_module('picking','update') or erp_supply.has_role('aux_logistica') or erp_supply.has_role('jefe_logistica') or erp_supply.has_role('super_admin')) then raise exception 'No autorizado para guardar Alistamiento' using errcode='42501'; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and step_code='ALISTAMIENTO' and status='IN_PROGRESS' order by sequence_no desc limit 1;
  if not found then raise exception 'Primero debes tomar el pedido en Alistamiento'; end if;
  if v_task.assigned_profile_id is distinct from v_actor and not (erp_supply.has_role('jefe_logistica') or erp_supply.has_role('super_admin')) then raise exception 'Pedido asignado a otro auxiliar' using errcode='42501'; end if;
  if jsonb_typeof(coalesce(p_items,'[]'::jsonb))<>'array' then raise exception 'Resultados inválidos'; end if;
  for v_row in select value from jsonb_array_elements(p_items) loop
    v_id:=erp_supply.safe_uuid(v_row->>'orderItemId');v_result:=upper(coalesce(v_row->>'result',''));v_novelty:=nullif(trim(v_row->>'novelty'),'');
    select * into v_item from erp_supply.order_items where id=v_id and order_id=p_order_id and item_status not in('FULFILLED','CANCELLED');
    if not found then raise exception 'Línea no disponible'; end if;
    if v_item.requires_cut and not exists(select 1 from erp_supply.cut_requirements r where r.order_item_id=v_item.id and r.process_status='READY' and r.collection_status='COLLECTED') then raise exception 'La línea % todavía está en Corte',v_item.line_number; end if;
    if v_result not in('FOUND','MISSING') then raise exception 'Marca Encontrado o No encontrado'; end if;
    if v_result='MISSING' and v_novelty is null then raise exception 'Explica el faltante de la línea %',v_item.line_number; end if;
    insert into erp_supply.picking_prechecks(order_item_id,organization_id,order_id,task_id,result,novelty,checked_by,metadata)
    values(v_item.id,v_org,p_order_id,v_task.id,v_result,v_novelty,v_actor,jsonb_build_object('lineNumber',v_item.line_number,'source','PARALLEL_PICKING_V10_12'))
    on conflict(order_item_id) do update set result=excluded.result,novelty=excluded.novelty,checked_by=excluded.checked_by,checked_at=now(),task_id=excluded.task_id,metadata=erp_supply.picking_prechecks.metadata||excluded.metadata;
    v_count:=v_count+1;
  end loop;
  insert into erp_supply.order_events(organization_id,order_id,task_id,event_type,action_code,from_step_code,to_step_code,actor_profile_id,actor_role_code,payload)
  values(v_org,p_order_id,v_task.id,'DOMAIN_RECORD','PICKING_PRECHECK','ALISTAMIENTO','ALISTAMIENTO',v_actor,(erp_supply.current_roles())[1],jsonb_build_object('items',v_count));
  return jsonb_build_object('success',true,'saved',v_count);
end;$$;

grant execute on function public.erp_x_picking_precheck(uuid) to authenticated;
grant execute on function public.erp_x_save_picking_precheck(uuid,jsonb) to authenticated;

create or replace function erp_supply.trg_clear_picking_prechecks()
returns trigger language plpgsql security definer set search_path=erp_supply,public as $$ begin delete from erp_supply.picking_prechecks where order_id=new.order_id; return new; end; $$;
drop trigger if exists trg_clear_picking_prechecks on erp_supply.picking_rounds;
create trigger trg_clear_picking_prechecks after insert on erp_supply.picking_rounds for each row execute function erp_supply.trg_clear_picking_prechecks();

-- Nota / Novedad / Reporte transversales.
create or replace function public.erp_x_create_order_issue(p_order_id uuid,p_payload jsonb)
returns jsonb language plpgsql security definer set search_path=erp_supply,public,auth as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_order erp_supply.orders%rowtype;v_task erp_supply.order_tasks%rowtype;v_type text:=upper(trim(coalesce(p_payload->>'type','')));v_title text:=nullif(trim(p_payload->>'title'),'');v_detail text:=nullif(trim(p_payload->>'detail'),'');v_target text:=nullif(trim(p_payload->>'targetRole'),'');v_issue erp_supply.order_issues%rowtype;v_status text;begin
  if v_type not in('NOTE','NOVELTY','REPORT') then raise exception 'Tipo de registro inválido'; end if;
  if v_detail is null then raise exception 'Escribe el detalle'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org and erp_supply.can_view_order_or_reception_shadow(id) for update;
  if not found then raise exception 'Pedido no disponible' using errcode='42501'; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if v_target is not null and not exists(select 1 from erp_supply.roles where code=v_target and active) then v_target:=null; end if;
  if v_type='REPORT' and v_target is null then v_target:='jefe_logistica'; end if;
  if v_type='NOVELTY' and v_target is null then v_target:=v_order.current_role_code; end if;
  insert into erp_supply.order_issues(organization_id,order_id,task_id,issue_type,source_code,title,detail,status,blocking,target_role_code,created_by,metadata)
  values(v_org,p_order_id,v_task.id,v_type,nullif(trim(p_payload->>'sourceCode'),''),coalesce(v_title,case v_type when 'NOTE' then 'Nota' when 'NOVELTY' then 'Novedad' else 'Reporte' end),v_detail,case when v_type='NOTE' then 'CLOSED' else 'OPEN' end,v_type<>'NOTE',v_target,v_actor,coalesce(p_payload->'metadata','{}'::jsonb)) returning * into v_issue;
  insert into erp_supply.order_comments(order_id,author_profile_id,comment_type,visibility,body,metadata)
  values(p_order_id,v_actor,v_type,'INTERNAL',v_detail,jsonb_build_object('issueId',v_issue.id,'source','ISSUE_ENGINE_V10_12'));
  if v_type<>'NOTE' and v_task.id is not null then
    update erp_supply.task_sessions s set ended_at=now(),raw_seconds=greatest(0,extract(epoch from(now()-s.started_at))::bigint),business_seconds=erp_supply.business_seconds_between(v_org,s.started_at,now()),note=coalesce(s.note,'')||' · Pausa por '||lower(v_type) where s.task_id=v_task.id and s.ended_at is null;
    v_status:=case when v_type='REPORT' then 'BLOCKED' else 'WAITING' end;
    update erp_supply.order_tasks set status=v_status,result_code=v_type,result_detail=v_detail,blocked_at=case when v_type='REPORT' then now() else blocked_at end where id=v_task.id;
    update erp_supply.orders set status=v_status,metadata=metadata||jsonb_build_object('exceptionState',jsonb_build_object('type',v_type,'label',case when v_type='REPORT' then 'REPORTE' else 'ESPERA_CON_NOVEDAD' end,'issueId',v_issue.id,'openedAt',now())),version=version+1,updated_at=now() where id=p_order_id returning * into v_order;
  end if;
  insert into erp_supply.order_events(organization_id,order_id,task_id,event_type,action_code,from_step_code,to_step_code,actor_profile_id,actor_role_code,payload)
  values(v_org,p_order_id,v_task.id,'ISSUE',v_type,v_order.current_step_code,v_order.current_step_code,v_actor,(erp_supply.current_roles())[1],jsonb_build_object('issueId',v_issue.id,'blocking',v_issue.blocking,'targetRole',v_target));
  return jsonb_build_object('success',true,'issue',to_jsonb(v_issue),'orderStatus',v_order.status);
end;$$;

create or replace function public.erp_x_order_issues(p_order_id uuid)
returns jsonb language plpgsql stable security definer set search_path=erp_supply,public,auth as $$
begin
  perform erp_supply.require_profile();
  if not exists(select 1 from erp_supply.orders where id=p_order_id and organization_id=erp_supply.current_org_id() and erp_supply.can_view_order_or_reception_shadow(id)) then raise exception 'Pedido no disponible' using errcode='42501'; end if;
  return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'type',i.issue_type,'title',i.title,'detail',i.detail,'status',i.status,'blocking',i.blocking,'sourceCode',i.source_code,'targetRole',i.target_role_code,'createdBy',p.display_name,'createdAt',i.created_at,'resolvedBy',rp.display_name,'resolvedAt',i.resolved_at,'resolution',i.resolution,'resolutionCode',i.resolution_code,'metadata',i.metadata) order by i.created_at desc),'[]'::jsonb) from erp_supply.order_issues i join erp_supply.profiles p on p.id=i.created_by left join erp_supply.profiles rp on rp.id=i.resolved_by where i.order_id=p_order_id));
end;$$;

create or replace function public.erp_x_resolve_order_issue(p_issue_id uuid,p_payload jsonb)
returns jsonb language plpgsql security definer set search_path=erp_supply,public,auth as $$
declare v_actor uuid:=erp_supply.require_profile();v_roles text[]:=erp_supply.current_roles();v_issue erp_supply.order_issues%rowtype;v_order erp_supply.orders%rowtype;v_task erp_supply.order_tasks%rowtype;v_resolution text:=nullif(trim(p_payload->>'resolution'),'');v_code text:=upper(coalesce(nullif(trim(p_payload->>'resolutionCode'),''),'RESOLVED'));v_remaining int;begin
  if v_resolution is null then raise exception 'Describe cómo se solucionó'; end if;
  select * into v_issue from erp_supply.order_issues where id=p_issue_id and organization_id=erp_supply.current_org_id() for update;
  if not found or v_issue.status<>'OPEN' then raise exception 'La gestión ya fue cerrada o no existe'; end if;
  select * into v_order from erp_supply.orders where id=v_issue.order_id for update;
  if not (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica') or v_issue.target_role_code=any(v_roles) or v_order.current_assignee_id=v_actor or (v_issue.source_code='NO_DELIVERY' and erp_supply.can_access_module('shipping','update'))) then raise exception 'No autorizado para cerrar esta gestión' using errcode='42501'; end if;
  update erp_supply.order_issues set status='RESOLVED',resolved_by=v_actor,resolved_at=now(),resolution=v_resolution,resolution_code=v_code where id=v_issue.id returning * into v_issue;
  if v_issue.source_code='NO_DELIVERY' then
    update erp_supply.deliveries set status=case when v_code='RETURN' then 'CANCELLED' when v_code='REPROGRAM' then 'REPROGRAMMED' else 'IN_TRANSIT' end,metadata=metadata||jsonb_build_object('noDeliveryResolvedAt',now(),'noDeliveryResolution',v_resolution),updated_at=now() where id=(select id from erp_supply.deliveries where order_id=v_order.id order by created_at desc limit 1);
    update erp_supply.orders set metadata=(metadata-'deliveryExceptionOpen')||jsonb_build_object('noDeliveryResolvedAt',now(),'noDeliveryResolution',v_resolution) where id=v_order.id;
  end if;
  select count(*) into v_remaining from erp_supply.order_issues where order_id=v_order.id and blocking and status='OPEN';
  if v_remaining=0 then
    select * into v_task from erp_supply.order_tasks where order_id=v_order.id and status in('WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
    if found then update erp_supply.order_tasks set status=case when assigned_profile_id is null then 'QUEUED' else 'ASSIGNED' end,result_code='ISSUE_RESOLVED',result_detail=v_resolution,blocked_at=null where id=v_task.id; end if;
    update erp_supply.orders set status=case when current_assignee_id is null then 'QUEUED' else 'ASSIGNED' end,metadata=metadata-'exceptionState',version=version+1,updated_at=now() where id=v_order.id returning * into v_order;
  end if;
  insert into erp_supply.order_events(organization_id,order_id,task_id,event_type,action_code,from_step_code,to_step_code,actor_profile_id,actor_role_code,payload)
  values(v_order.organization_id,v_order.id,v_issue.task_id,'ISSUE_RESOLVED',v_issue.issue_type,v_order.current_step_code,v_order.current_step_code,v_actor,(v_roles)[1],jsonb_build_object('issueId',v_issue.id,'resolution',v_resolution,'resolutionCode',v_code));
  return jsonb_build_object('success',true,'issue',to_jsonb(v_issue),'remainingBlocking',v_remaining,'orderStatus',v_order.status);
end;$$;

grant execute on function public.erp_x_create_order_issue(uuid,jsonb) to authenticated;
grant execute on function public.erp_x_order_issues(uuid) to authenticated;
grant execute on function public.erp_x_resolve_order_issue(uuid,jsonb) to authenticated;

-- No entrega se convierte en Reporte bloqueante para Logística.
create or replace function public.erp_x_shipping_report_no_delivery(p_order_id uuid,p_payload jsonb)
returns jsonb language plpgsql security definer set search_path=erp_supply,public,auth as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_order erp_supply.orders%rowtype;v_delivery erp_supply.deliveries%rowtype;v_reason text:=nullif(trim(p_payload->>'reason'),'');v_action text:=coalesce(nullif(p_payload->>'requestedAction',''),'REVIEW');v_issue jsonb;begin
  if not (erp_supply.has_role('ventas') or erp_supply.has_role('super_admin')) then raise exception 'Solo Ventas o Superadministración pueden registrar una no entrega' using errcode='42501'; end if;
  if v_reason is null then raise exception 'Motivo de no entrega requerido'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org for update;
  if not found or (not erp_supply.has_role('super_admin') and v_order.seller_profile_id is distinct from v_actor) then raise exception 'Pedido no disponible para este asesor' using errcode='42501'; end if;
  select * into v_delivery from erp_supply.deliveries where order_id=p_order_id and dispatched_at is not null order by created_at desc limit 1 for update;
  if not found then raise exception 'El pedido todavía no figura como enviado'; end if;
  if v_delivery.status='DELIVERED' or v_order.status='CLOSED' then raise exception 'El pedido ya fue finalizado y no admite una no entrega'; end if;
  update erp_supply.deliveries set status='NOT_DELIVERED',no_delivery_reason=v_reason,metadata=metadata||jsonb_build_object('noDeliveryReportedAt',now(),'requestedAction',v_action),updated_at=now() where id=v_delivery.id returning * into v_delivery;
  select public.erp_x_create_order_issue(p_order_id,jsonb_build_object('type','REPORT','title','No entrega reportada','detail',v_reason,'targetRole','jefe_logistica','sourceCode','NO_DELIVERY','metadata',jsonb_build_object('requestedAction',v_action,'deliveryId',v_delivery.id))) into v_issue;
  update erp_supply.orders set metadata=metadata||jsonb_build_object('deliveryExceptionOpen',true,'noDeliveryReason',v_reason,'noDeliveryRequestedAction',v_action,'noDeliveryReportedAt',now()),updated_at=now() where id=p_order_id;
  return jsonb_build_object('success',true,'delivery',to_jsonb(v_delivery),'issue',v_issue);
end;$$;

-- Espera de mercancía PVE visible en Recepción mientras Compras trabaja.
create or replace function erp_supply.finalize_arrived_purchase(p_order_id uuid,p_actor uuid)
returns boolean language plpgsql security definer set search_path=erp_supply,public as $$
declare v_order erp_supply.orders%rowtype;v_task erp_supply.order_tasks%rowtype;v_receipt uuid;v_version int;begin
  select * into v_order from erp_supply.orders where id=p_order_id for update;
  if not found or v_order.current_step_code<>'RECEPCION_MERCANCIA' then return false; end if;
  select * into v_task from erp_supply.order_tasks where order_id=p_order_id and step_code='RECEPCION_MERCANCIA' and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED') order by sequence_no desc limit 1 for update;
  if not found then return false; end if;
  insert into erp_supply.receipts(order_id,receipt_number,purchase_order,supplier_name,status,received_by,received_at,metadata)
  values(p_order_id,'ARR-'||replace(p_order_id::text,'-',''),(select po_number from erp_supply.purchase_orders where order_id=p_order_id order by created_at desc limit 1),(select supplier_name from erp_supply.purchase_orders where order_id=p_order_id order by created_at desc limit 1),'CONFORMING',p_actor,now(),jsonb_build_object('source','MERCANCIA_OK_V10_12'))
  on conflict(order_id,receipt_number) do update set status='CONFORMING',received_by=excluded.received_by,received_at=excluded.received_at returning id into v_receipt;
  insert into erp_supply.receipt_lines(receipt_id,order_item_id,sku,description,expected_quantity,received_quantity,accepted_quantity,rejected_quantity,unit,location,quality_status,metadata)
  select v_receipt,i.id,i.sku,i.description,i.quantity,i.quantity,i.quantity,0,i.unit,'RECEPCION','ACCEPTED',jsonb_build_object('source','MERCANCIA_OK_V10_12') from erp_supply.order_items i where i.order_id=p_order_id
  on conflict do nothing;
  update erp_supply.task_checklist set completed=true,completed_by=p_actor,completed_at=now(),note='Mercancía OK confirmada desde Recepción',metadata=metadata||jsonb_build_object('source','MERCANCIA_OK_V10_12') where task_id=v_task.id and required;
  select version into v_version from erp_supply.orders where id=p_order_id;
  perform erp_supply.execute_action_internal(p_order_id,'COMPLETE',jsonb_build_object('resultCode','MERCHANDISE_OK','detail','Mercancía recibida en sede'),p_actor,true,v_version,'ARRIVAL-'||p_order_id::text);
  return true;
end;$$;

create or replace function erp_supply.trg_auto_finalize_arrival()
returns trigger language plpgsql security definer set search_path=erp_supply,public as $$
declare v_actor uuid;begin
  -- Se dispara cuando create_task ya actualizó la etapa principal del pedido.
  if new.current_step_code='RECEPCION_MERCANCIA' and old.current_step_code is distinct from new.current_step_code then
    select marked_by into v_actor from erp_supply.purchase_arrival_state where order_id=new.id and status='ARRIVED';
    if v_actor is not null then perform erp_supply.finalize_arrived_purchase(new.id,v_actor); end if;
  end if;
  return new;
end;$$;
drop trigger if exists trg_auto_finalize_arrival on erp_supply.order_tasks;
drop trigger if exists trg_auto_finalize_arrival_order on erp_supply.orders;
create trigger trg_auto_finalize_arrival_order after update of current_step_code on erp_supply.orders for each row execute function erp_supply.trg_auto_finalize_arrival();

create or replace function public.erp_x_set_purchase_arrival(p_order_id uuid,p_status text)
returns jsonb language plpgsql security definer set search_path=erp_supply,public,auth as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_order erp_supply.orders%rowtype;v_status text:=upper(trim(coalesce(p_status,'')));v_row erp_supply.purchase_arrival_state%rowtype;begin
  if not (erp_supply.can_access_module('receiving','update') or erp_supply.has_role('jefe_logistica') or erp_supply.has_role('super_admin')) then raise exception 'No autorizado para confirmar llegada' using errcode='42501'; end if;
  if v_status not in('WAITING','ARRIVED') then raise exception 'Estado de llegada inválido'; end if;
  select * into v_order from erp_supply.orders where id=p_order_id and organization_id=v_org and order_type_code='PVE' and current_step_code in('COMPRAS','RECEPCION_MERCANCIA','RECEPCION_PEDIDO') for update;
  if not found then raise exception 'Este pedido no está disponible para seguimiento de Compras'; end if;
  if exists(select 1 from erp_supply.order_issues oi where oi.order_id=p_order_id and oi.blocking and oi.status='OPEN') then
    raise exception 'El pedido está detenido por una novedad o reporte pendiente. Resuélvelo antes de cambiar la llegada de mercancía.';
  end if;
  insert into erp_supply.purchase_arrival_state(order_id,organization_id,status,marked_by,marked_at,arrived_at,metadata)
  values(p_order_id,v_org,v_status,v_actor,now(),case when v_status='ARRIVED' then now() else null end,jsonb_build_object('source','RECEIVING_PURCHASE_WATCH_V10_12'))
  on conflict(order_id) do update set status=excluded.status,marked_by=excluded.marked_by,marked_at=now(),arrived_at=case when excluded.status='ARRIVED' then now() else erp_supply.purchase_arrival_state.arrived_at end,metadata=erp_supply.purchase_arrival_state.metadata||excluded.metadata returning * into v_row;
  update erp_supply.orders set metadata=metadata||jsonb_build_object('purchaseArrival',jsonb_build_object('status',v_status,'markedAt',now(),'markedBy',v_actor)),updated_at=now(),version=version+1 where id=p_order_id;
  if v_status='ARRIVED' then perform erp_supply.finalize_arrived_purchase(p_order_id,v_actor); end if;
  return jsonb_build_object('success',true,'arrival',to_jsonb(v_row),'currentStep',(select current_step_code from erp_supply.orders where id=p_order_id));
end;$$;
grant execute on function public.erp_x_set_purchase_arrival(uuid,text) to authenticated;

-- Aprobación especializada para remanentes críticos de Corte.
create or replace function public.erp_x_request_cut_remainder_approval(p_group_key text,p_payload jsonb)
returns jsonb language plpgsql security definer set search_path=erp_supply,public,auth as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_order_id uuid;v_reel numeric:=erp_supply.safe_numeric(p_payload->>'reelLength');v_scrap numeric:=coalesce(erp_supply.safe_numeric(p_payload->>'scrapLength'),0);v_needed numeric;v_remaining numeric;v_assigned text:=coalesce(nullif(trim(p_payload->>'assignedRole'),''),'jefe_logistica');v_req erp_supply.approval_requests%rowtype;begin
  select min(r.order_id),coalesce(sum(r.total_length),0) into v_order_id,v_needed from erp_supply.cut_requirements r where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY';
  if v_order_id is null then raise exception 'Grupo sin cortes pendientes'; end if;
  if v_reel is null then raise exception 'Indica la medida del carreto'; end if;v_remaining:=v_reel-v_needed-v_scrap;
  if v_remaining>=50 or v_remaining<=0 then raise exception 'La aprobación solo aplica cuando el remanente queda entre 0 y 50 m'; end if;
  if v_assigned not in('auditoria','gerencia','jefe_logistica') then raise exception 'La aprobación debe dirigirse a Auditoría, Gerencia o Jefatura Logística'; end if;
  if exists(select 1 from erp_supply.approval_requests where order_id=v_order_id and request_type='STOCK_EXCEPTION' and status='PENDING' and request_payload->>'groupKey'=p_group_key) then raise exception 'Ya existe una aprobación pendiente para este remanente'; end if;
  insert into erp_supply.approval_requests(organization_id,order_id,request_type,requested_by,assigned_role_code,reason,request_payload)
  values(v_org,v_order_id,'STOCK_EXCEPTION',v_actor,v_assigned,coalesce(nullif(trim(p_payload->>'reason'),''),format('Autorizar remanente de %s m en Corte',round(v_remaining,3))),jsonb_build_object('exceptionCode','LOW_REEL_REMAINDER','groupKey',p_group_key,'reelLength',v_reel,'requestedLength',v_needed,'scrapLength',v_scrap,'remainingLength',v_remaining)) returning * into v_req;
  return jsonb_build_object('success',true,'requestId',v_req.id,'remainingLength',v_remaining);
end;$$;
grant execute on function public.erp_x_request_cut_remainder_approval(text,jsonb) to authenticated;

-- Solo Auditoría, Gerencia, Jefatura Logística y Superadministración deciden aprobaciones.
create or replace function public.erp_x_decide_approval(p_request_id uuid,p_decision text,p_reason text)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_roles text[]:=erp_supply.current_roles();
  v_req erp_supply.approval_requests%rowtype;
  v_order erp_supply.orders%rowtype;
  v_dec text:=upper(trim(coalesce(p_decision,'')));
  v_route text;
  v_old_task erp_supply.order_tasks%rowtype;
  v_next_sequence integer;
  v_final_status text;
  v_before_step text;
  v_before_status text;
  v_now timestamptz:=now();
begin
  select * into v_req from erp_supply.approval_requests
  where id=p_request_id and organization_id=erp_supply.current_org_id()
  for update;
  if not found then raise exception 'Solicitud no encontrada'; end if;
  if v_req.status<>'PENDING' then raise exception 'La solicitud ya fue decidida'; end if;
  if v_dec not in('APPROVED','REJECTED') then raise exception 'Decisión inválida'; end if;
  if nullif(trim(p_reason),'') is null then raise exception 'Debe registrar el motivo de la decisión'; end if;
  if not (
    erp_supply.has_role('auditoria')
    or erp_supply.has_role('gerencia')
    or erp_supply.has_role('jefe_logistica')
    or erp_supply.has_role('super_admin')
  ) then
    raise exception 'Solo Auditoría, Gerencia, Jefatura Logística o Superadministración pueden aprobar' using errcode='42501';
  end if;

  select * into v_order from erp_supply.orders where id=v_req.order_id for update;
  if not found then raise exception 'Pedido asociado no encontrado'; end if;
  v_before_step:=v_order.current_step_code;
  v_before_status:=v_order.status;

  update erp_supply.approval_requests
  set status=v_dec,decision_reason=trim(p_reason),decided_by=v_actor,decided_at=v_now
  where id=p_request_id returning * into v_req;

  if v_dec='APPROVED' then
    case v_req.request_type
      when 'CANCELLATION' then
        if v_order.status in('CLOSED','CANCELLED') then raise exception 'El pedido ya está finalizado'; end if;
        update erp_supply.task_sessions s
        set ended_at=v_now,
            raw_seconds=greatest(0,extract(epoch from(v_now-s.started_at))::bigint),
            business_seconds=erp_supply.business_seconds_between(v_order.organization_id,s.started_at,v_now),
            note=coalesce(s.note,'')||case when s.note is null then '' else ' · ' end||'Cerrada por cancelación aprobada'
        from erp_supply.order_tasks t
        where s.task_id=t.id and t.order_id=v_order.id and s.ended_at is null;
        update erp_supply.order_tasks set status='CANCELLED',completed_at=v_now,result_code='CANCELLED_BY_APPROVAL'
        where order_id=v_order.id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED');
        update erp_supply.orders set status='CANCELLED',cancelled_at=v_now,current_assignee_id=null,current_role_code=null,version=version+1
        where id=v_order.id returning * into v_order;

      when 'PRIORITY' then
        if v_order.status in('CLOSED','CANCELLED') then raise exception 'El pedido ya está finalizado'; end if;
        update erp_supply.orders set priority=upper(v_req.request_payload->>'priority'),version=version+1
        where id=v_order.id returning * into v_order;

      when 'ROUTE_CHANGE' then
        if v_order.status in('CLOSED','CANCELLED') then raise exception 'El pedido ya está finalizado'; end if;
        v_route:=upper(v_req.request_payload->>'route');
        if not exists(select 1 from erp_supply.delivery_routes where code=v_route and active) then raise exception 'Ruta aprobada inválida'; end if;
        if v_order.current_step_code in('CLIENT_POINT','CLIENT_PICKUP','LOCAL_DISPATCH','NATIONAL_DISPATCH') then
          select * into v_old_task from erp_supply.order_tasks
          where order_id=v_order.id and status in('QUEUED','ASSIGNED','IN_PROGRESS','WAITING','BLOCKED')
          order by sequence_no desc limit 1 for update;
          update erp_supply.task_sessions s set ended_at=v_now,
            raw_seconds=greatest(0,extract(epoch from(v_now-s.started_at))::bigint),
            business_seconds=erp_supply.business_seconds_between(v_order.organization_id,s.started_at,v_now),
            note=coalesce(s.note,'')||case when s.note is null then '' else ' · ' end||'Cerrada por cambio de ruta'
          where s.task_id=v_old_task.id and s.ended_at is null;
          update erp_supply.order_tasks set status='CANCELLED',completed_at=v_now,result_code='ROUTE_CHANGED'
          where id=v_old_task.id;
          v_next_sequence:=coalesce(v_old_task.sequence_no,0)+1;
          update erp_supply.orders set delivery_route_code=v_route,current_step_code=v_route,status='QUEUED',
            current_assignee_id=null,current_role_code=null,version=version+1
          where id=v_order.id returning * into v_order;
          perform erp_supply.create_task(v_order,v_route,v_next_sequence);
          select * into v_order from erp_supply.orders where id=v_order.id;
        else
          update erp_supply.orders set delivery_route_code=v_route,version=version+1
          where id=v_order.id returning * into v_order;
        end if;

      when 'REOPEN' then
        if v_order.status<>'CLOSED' then raise exception 'Solo se pueden reabrir pedidos cerrados'; end if;
        v_next_sequence:=(select coalesce(max(sequence_no),0)+1 from erp_supply.order_tasks where order_id=v_order.id);
        update erp_supply.orders set status='QUEUED',closed_at=null,current_step_code='CLOSURE',
          current_assignee_id=null,current_role_code=null,version=version+1
        where id=v_order.id returning * into v_order;
        perform erp_supply.create_task(v_order,'CLOSURE',v_next_sequence);
        select * into v_order from erp_supply.orders where id=v_order.id;

      when 'STOCK_EXCEPTION' then null;
      when 'FLOW_EXCEPTION' then null;
      when 'PAYMENT_EXCEPTION' then null;
      when 'DATA_CORRECTION' then null;
      else raise exception 'Tipo de solicitud no implementado: %',v_req.request_type;
    end case;

    update erp_supply.approval_requests set status='EXECUTED',executed_at=v_now where id=p_request_id returning status into v_final_status;
  else
    v_final_status:='REJECTED';
  end if;

  insert into erp_supply.order_events(organization_id,order_id,event_type,action_code,from_step_code,to_step_code,
    from_status,to_status,actor_profile_id,actor_role_code,payload)
  values(v_req.organization_id,v_req.order_id,'APPROVAL_DECISION',v_dec,v_before_step,v_order.current_step_code,
    v_before_status,v_order.status,v_actor,(v_roles)[1],jsonb_build_object('requestId',v_req.id,'requestType',v_req.request_type,'reason',p_reason,'finalRequestStatus',v_final_status));

  insert into erp_supply.system_audit(organization_id,actor_profile_id,action,entity_type,entity_id,before_data,after_data,metadata)
  values(v_req.organization_id,v_actor,'APPROVAL_'||v_dec,'APPROVAL_REQUEST',v_req.id::text,
    jsonb_build_object('status','PENDING'),jsonb_build_object('status',v_final_status,'orderStatus',v_order.status,'orderVersion',v_order.version),
    jsonb_build_object('requestType',v_req.request_type,'reason',p_reason));

  insert into erp_supply.outbox_events(organization_id,event_type,aggregate_type,aggregate_id,payload)
  values(v_req.organization_id,'APPROVAL_DECIDED','ORDER',v_order.id,
    jsonb_build_object('requestId',v_req.id,'decision',v_dec,'requestType',v_req.request_type,'orderNumber',v_order.order_number));

  return jsonb_build_object('success',true,'requestId',v_req.id,'decision',v_dec,'requestStatus',v_final_status,
    'orderId',v_order.id,'orderStatus',v_order.status,'currentStep',v_order.current_step_code,'version',v_order.version);
end;
$$;


-- Gate central: novedades/reportes abiertos, prioridad y salida sin factura aprobada.
create or replace function erp_supply.validate_task_completion()
returns trigger
language plpgsql
security definer
set search_path=erp_supply,public
as $$
declare
  v_order erp_supply.orders%rowtype;
  v_missing integer;
begin
  if new.status<>'COMPLETED' or old.status='COMPLETED' then return new; end if;
  select * into v_order from erp_supply.orders where id=new.order_id;
  if v_order.is_test then return new; end if;

  if exists(
    select 1 from erp_supply.order_issues i
    where i.order_id=v_order.id and i.blocking and i.status='OPEN'
  ) then
    raise exception 'El pedido tiene una novedad o reporte pendiente de solución';
  end if;

  if v_order.priority in('URGENT','CRITICAL') and not exists(
    select 1 from erp_supply.approval_requests a
    where a.order_id=v_order.id
      and a.request_type='FLOW_EXCEPTION'
      and upper(coalesce(a.request_payload->>'exceptionCode',''))='PRIORITY_RELEASE'
      and a.status in('APPROVED','EXECUTED')
  ) then
    raise exception 'APROBACION_REQUERIDA: los pedidos urgentes o críticos requieren aprobación antes de avanzar';
  end if;

  select count(*) into v_missing
  from erp_supply.task_checklist
  where task_id=new.id and required and not completed;
  if v_missing>0 then
    raise exception 'No puede finalizar: quedan % controles obligatorios sin completar',v_missing;
  end if;

  case new.step_code
    when 'CARTERA' then
      if not exists(
        select 1 from erp_supply.financial_validations
        where order_id=v_order.id and validation_type='CARTERA' and decision='APPROVED'
      ) then
        raise exception 'Debe registrar una validación aprobada de Cartera';
      end if;

    when 'CAJA' then
      if not exists(
        select 1 from erp_supply.financial_validations
        where order_id=v_order.id and validation_type='CAJA' and decision='APPROVED'
      ) then
        raise exception 'Debe registrar una validación aprobada de Caja';
      end if;

    when 'COMPRAS' then
      if not exists(
        select 1 from erp_supply.purchase_orders
        where order_id=v_order.id and status in('ISSUED','CONFIRMED','PARTIAL','RECEIVED')
      ) then
        raise exception 'Debe registrar una orden de compra válida';
      end if;

    when 'RECEPCION_MERCANCIA' then
      if not exists(
        select 1 from erp_supply.receipts
        where order_id=v_order.id and status in('PARTIAL','CONFORMING','CLOSED')
      ) then
        raise exception 'Debe registrar la recepción física y su resultado de calidad';
      end if;

    when 'CORTE' then
      if v_order.requires_cut and not exists(
        select 1 from erp_supply.cut_jobs
        where order_id=v_order.id and status='COMPLETED'
      ) then
        raise exception 'Debe registrar al menos un corte completado';
      end if;

    when 'FACTURACION' then
      if upper(v_order.order_type_code)='PVP' then
        if not exists(
          select 1 from erp_supply.drive_files f
          where f.order_id=v_order.id
            and f.task_id=new.id
            and upper(f.file_category)='PVP_ANNEX'
        ) then
          raise exception 'Debe cargar el Anexo PVP antes de enviar el pedido a despacho';
        end if;
      else
        if not exists(
          select 1
          from erp_supply.invoices i
          join erp_supply.drive_files f on f.id=i.drive_file_id
          where i.order_id=v_order.id
            and i.status='REGISTERED'
            and f.task_id=new.id
        ) and not exists(
          select 1 from erp_supply.approval_requests a
          where a.order_id=v_order.id and a.request_type='PAYMENT_EXCEPTION'
            and upper(coalesce(a.request_payload->>'exceptionCode',''))='NO_INVOICE'
            and a.status in('APPROVED','EXECUTED')
        ) then
          raise exception 'Debe cargar la factura o contar con aprobación para salida sin factura';
        end if;
      end if;

    when 'CAJA_FACTURACION' then
      if not exists(
        select 1
        from erp_supply.invoices i
        join erp_supply.drive_files f on f.id=i.drive_file_id
        where i.order_id=v_order.id and i.status='REGISTERED' and f.task_id=new.id
      ) and not exists(
        select 1 from erp_supply.approval_requests a
        where a.order_id=v_order.id and a.request_type='PAYMENT_EXCEPTION'
          and upper(coalesce(a.request_payload->>'exceptionCode',''))='NO_INVOICE'
          and a.status in('APPROVED','EXECUTED')
      ) then
        raise exception 'Debe cargar la factura o contar con aprobación para salida sin factura';
      end if;

    -- V10.11.7: en despacho ya NO se exige entrega/foto.
    -- La guía + estado de salida son suficientes para crear CLOSURE.
    when 'CLIENT_POINT' then
      if not exists(
        select 1 from erp_supply.deliveries d
        where d.order_id=v_order.id
          and nullif(trim(d.tracking_number),'') is not null
          and d.status in('DISPATCHED','IN_TRANSIT','DELIVERED')
      ) then
        raise exception 'Debe registrar la guía antes de pasar a cierre';
      end if;

    when 'CLIENT_PICKUP' then
      if not exists(
        select 1 from erp_supply.deliveries d
        where d.order_id=v_order.id
          and nullif(trim(d.tracking_number),'') is not null
          and d.status in('DISPATCHED','IN_TRANSIT','DELIVERED')
      ) then
        raise exception 'Debe registrar la guía antes de pasar a cierre';
      end if;

    when 'LOCAL_DISPATCH' then
      if not exists(
        select 1 from erp_supply.deliveries d
        where d.order_id=v_order.id
          and nullif(trim(d.tracking_number),'') is not null
          and d.status in('DISPATCHED','IN_TRANSIT','DELIVERED')
      ) then
        raise exception 'Debe registrar la guía antes de pasar a cierre';
      end if;

    when 'NATIONAL_DISPATCH' then
      if not exists(
        select 1 from erp_supply.deliveries d
        where d.order_id=v_order.id
          and nullif(trim(d.tracking_number),'') is not null
          and d.status in('DISPATCHED','IN_TRANSIT','DELIVERED')
      ) then
        raise exception 'Debe registrar la guía antes de pasar a cierre';
      end if;

    -- Cierre conserva controles reales: documento comercial previo, foto y entrega.
    when 'CLOSURE' then
      if upper(v_order.order_type_code)='PVP' then
        if not exists(
          select 1 from erp_supply.drive_files
          where order_id=v_order.id and upper(file_category)='PVP_ANNEX'
        ) then
          raise exception 'El pedido no tiene Anexo PVP';
        end if;
      elsif not exists(
        select 1 from erp_supply.invoices
        where order_id=v_order.id and status='REGISTERED'
      ) and not exists(
        select 1 from erp_supply.approval_requests a
        where a.order_id=v_order.id and a.request_type='PAYMENT_EXCEPTION'
          and upper(coalesce(a.request_payload->>'exceptionCode',''))='NO_INVOICE'
          and a.status in('APPROVED','EXECUTED')
      ) then
        raise exception 'El pedido no tiene factura registrada ni aprobación de salida sin factura';
      end if;

      if not exists(
        select 1 from erp_supply.drive_files f
        where f.order_id=v_order.id
          and f.task_id=new.id
          and upper(f.file_category)='DELIVERY_EVIDENCE'
      ) then
        raise exception 'Debes subir la foto de entrega antes de finalizar';
      end if;

      if not exists(
        select 1 from erp_supply.deliveries
        where order_id=v_order.id and status='DELIVERED'
      ) then
        raise exception 'El pedido no tiene entrega confirmada';
      end if;

    else null;
  end case;

  return new;
end;
$$;


drop trigger if exists trg_validate_task_completion on erp_supply.order_tasks;
create trigger trg_validate_task_completion before update of status on erp_supply.order_tasks for each row execute function erp_supply.validate_task_completion();

-- Listado de pedidos enriquecido con etiqueta de excepción y PVE visible en Recepción mientras está en Compras.
create or replace function public.erp_x_list_orders(
  p_search text default null,p_step text default null,p_status text default null,p_order_type text default null,p_route text default null,
  p_assignment text default 'ALL',p_page integer default 1,p_page_size integer default 50,p_include_history boolean default true
)
returns jsonb language plpgsql stable security definer set search_path=erp_supply,public,auth as $$
declare v_org uuid:=erp_supply.current_org_id();v_profile uuid:=erp_supply.require_profile();v_page int:=greatest(coalesce(p_page,1),1);v_size int:=least(greatest(coalesce(p_page_size,50),1),250);v_total bigint;v_items jsonb;begin
  with filtered as (
    select o.*,p.display_name assignee_name,s.name step_name,s.sla_hours,
      erp_supply.business_seconds_between(v_org,o.updated_at,now()) age_business_seconds,
      pa.status arrival_status,
      (p_step='RECEPCION_PEDIDO' and o.order_type_code='PVE' and o.current_step_code in('COMPRAS','RECEPCION_MERCANCIA')) purchase_shadow,
      o.metadata#>>'{exceptionState,label}' exception_label,
      (select count(*) from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') open_issue_count
    from erp_supply.orders o left join erp_supply.profiles p on p.id=o.current_assignee_id join erp_supply.workflow_steps s on s.code=o.current_step_code left join erp_supply.purchase_arrival_state pa on pa.order_id=o.id
    where o.organization_id=v_org and not o.is_test and erp_supply.can_view_order_or_reception_shadow(o.id) and (p_include_history or not o.is_history)
      and (p_search is null or p_search='' or lower(o.order_number||' '||o.client_name||' '||coalesce(o.external_reference,'')) like '%'||lower(p_search)||'%')
      and (p_step is null or p_step='' or o.current_step_code=p_step or (p_step='RECEPCION_PEDIDO' and o.order_type_code='PVE' and o.current_step_code in('COMPRAS','RECEPCION_MERCANCIA')))
      and (p_status is null or p_status='' or o.status=p_status) and (p_order_type is null or p_order_type='' or o.order_type_code=p_order_type) and (p_route is null or p_route='' or o.delivery_route_code=p_route)
      and (upper(coalesce(p_assignment,'ALL'))='ALL' or (upper(p_assignment)='MINE' and o.current_assignee_id=v_profile) or (upper(p_assignment)='UNASSIGNED' and o.current_assignee_id is null))
  ) select count(*) into v_total from filtered;
  with filtered as (
    select o.*,p.display_name assignee_name,s.name step_name,s.sla_hours,erp_supply.business_seconds_between(v_org,o.updated_at,now()) age_business_seconds,pa.status arrival_status,
      (p_step='RECEPCION_PEDIDO' and o.order_type_code='PVE' and o.current_step_code in('COMPRAS','RECEPCION_MERCANCIA')) purchase_shadow,o.metadata#>>'{exceptionState,label}' exception_label,
      (select count(*) from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') open_issue_count
    from erp_supply.orders o left join erp_supply.profiles p on p.id=o.current_assignee_id join erp_supply.workflow_steps s on s.code=o.current_step_code left join erp_supply.purchase_arrival_state pa on pa.order_id=o.id
    where o.organization_id=v_org and not o.is_test and erp_supply.can_view_order_or_reception_shadow(o.id) and (p_include_history or not o.is_history)
      and (p_search is null or p_search='' or lower(o.order_number||' '||o.client_name||' '||coalesce(o.external_reference,'')) like '%'||lower(p_search)||'%')
      and (p_step is null or p_step='' or o.current_step_code=p_step or (p_step='RECEPCION_PEDIDO' and o.order_type_code='PVE' and o.current_step_code in('COMPRAS','RECEPCION_MERCANCIA')))
      and (p_status is null or p_status='' or o.status=p_status) and (p_order_type is null or p_order_type='' or o.order_type_code=p_order_type) and (p_route is null or p_route='' or o.delivery_route_code=p_route)
      and (upper(coalesce(p_assignment,'ALL'))='ALL' or (upper(p_assignment)='MINE' and o.current_assignee_id=v_profile) or (upper(p_assignment)='UNASSIGNED' and o.current_assignee_id is null))
    order by case o.priority when 'CRITICAL' then 1 when 'URGENT' then 2 when 'HIGH' then 3 when 'MEDIUM' then 4 else 5 end,o.updated_at desc offset (v_page-1)*v_size limit v_size
  ) select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'orderNumber',order_number,'externalReference',external_reference,'orderType',order_type_code,'clientName',client_name,'paymentCondition',payment_condition_code,'route',delivery_route_code,
    'currentStep',current_step_code,'stepName',case when purchase_shadow then 'Recepción · seguimiento de Compras' else step_name end,'status',status,'priority',priority,'requiresCut',requires_cut,'requiresPurchase',requires_purchase,
    'assigneeId',current_assignee_id,'assigneeName',assignee_name,'roleCode',current_role_code,'ageBusinessSeconds',age_business_seconds,'slaExceeded',(sla_hours is not null and age_business_seconds>sla_hours*3600),
    'version',version,'isHistory',is_history,'createdAt',created_at,'updatedAt',updated_at,'fulfillmentStatus',metadata#>>'{fulfillment,status}','partialLabel',coalesce((metadata#>>'{fulfillment,partialLabel}')::boolean,false),
    'pendingItemCount',coalesce(erp_supply.safe_integer(metadata#>>'{fulfillment,pendingItemCount}'),0),'pickingRoundCount',coalesce(erp_supply.safe_integer(metadata#>>'{fulfillment,roundCount}'),0),
    'exceptionLabel',exception_label,'openIssueCount',open_issue_count,'purchaseShadow',purchase_shadow,'arrivalStatus',arrival_status
  )),'[]'::jsonb) into v_items from filtered;
  return jsonb_build_object('items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_size,'totalItems',v_total,'totalPages',ceil(v_total::numeric/v_size)::int),'generatedAt',now());
end;$$;

-- Verificación de integridad de los RPC nuevos.
do $$
begin
  if to_regprocedure('public.erp_x_create_order_issue(uuid,jsonb)') is null then raise exception 'Falta RPC de incidencias'; end if;
  if to_regprocedure('public.erp_x_set_purchase_arrival(uuid,text)') is null then raise exception 'Falta RPC de llegada PVE'; end if;
  if to_regprocedure('public.erp_x_save_picking_precheck(uuid,jsonb)') is null then raise exception 'Falta RPC de prealistamiento paralelo'; end if;
end;$$;

notify pgrst,'reload schema';
commit;

-- ============================================================================
-- 029_operational_intelligence_v10_13.sql
-- ============================================================================
-- ERP EI V10.13
-- Inteligencia operacional estructural: SLA/escalamiento, Centro de Excepciones,
-- analítica causal y optimizador de carretos para Corte.
-- Base requerida: V10.12 + migración 028 aplicada.

begin;

-- ---------------------------------------------------------------------------
-- 1. REGLAS SLA Y ALERTAS OPERACIONALES
-- ---------------------------------------------------------------------------

create table if not exists erp_supply.exception_sla_rules (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references erp_supply.organizations(id) on delete cascade,
  object_type text not null check (object_type in ('ISSUE','APPROVAL')),
  subtype text not null default '*',
  warning_seconds integer not null check (warning_seconds > 0),
  escalation_1_seconds integer not null check (escalation_1_seconds >= warning_seconds),
  escalation_2_seconds integer not null check (escalation_2_seconds >= escalation_1_seconds),
  escalation_role_1 text references erp_supply.roles(code),
  escalation_role_2 text references erp_supply.roles(code),
  active boolean not null default true,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, object_type, subtype)
);

create table if not exists erp_supply.operational_alerts (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references erp_supply.organizations(id) on delete cascade,
  order_id uuid references erp_supply.orders(id) on delete cascade,
  source_type text not null check (source_type in ('ISSUE','APPROVAL')),
  source_id uuid not null,
  alert_level integer not null check (alert_level between 1 and 3),
  severity text not null check (severity in ('WARNING','HIGH','CRITICAL')),
  target_role_code text references erp_supply.roles(code),
  message text not null,
  status text not null default 'OPEN' check (status in ('OPEN','ACKNOWLEDGED','CLOSED')),
  acknowledged_by uuid references erp_supply.profiles(id),
  acknowledged_at timestamptz,
  created_at timestamptz not null default now(),
  closed_at timestamptz,
  metadata jsonb not null default '{}'::jsonb
);

create unique index if not exists uq_operational_alert_source_level
on erp_supply.operational_alerts(organization_id,source_type,source_id,alert_level);

create index if not exists idx_operational_alerts_open
on erp_supply.operational_alerts(organization_id,status,severity,created_at desc);

create index if not exists idx_approval_requests_sla
on erp_supply.approval_requests(organization_id,status,created_at);

-- SLA en segundos laborales. Los valores pueden administrarse posteriormente sin cambiar código.
insert into erp_supply.exception_sla_rules(
  organization_id,object_type,subtype,warning_seconds,escalation_1_seconds,escalation_2_seconds,
  escalation_role_1,escalation_role_2,metadata
)
select o.id,v.object_type,v.subtype,v.warning_seconds,v.escalation_1_seconds,v.escalation_2_seconds,
       v.role_1,v.role_2,jsonb_build_object('seed','V10.13')
from erp_supply.organizations o
cross join (values
  ('ISSUE','NOVELTY',7200,14400,28800,'jefe_logistica','gerencia'),
  ('ISSUE','REPORT',3600,7200,14400,'jefe_logistica','gerencia'),
  ('APPROVAL','*',3600,7200,14400,'gerencia','auditoria')
) as v(object_type,subtype,warning_seconds,escalation_1_seconds,escalation_2_seconds,role_1,role_2)
on conflict(organization_id,object_type,subtype) do update set
  warning_seconds=excluded.warning_seconds,
  escalation_1_seconds=excluded.escalation_1_seconds,
  escalation_2_seconds=excluded.escalation_2_seconds,
  escalation_role_1=excluded.escalation_role_1,
  escalation_role_2=excluded.escalation_role_2,
  metadata=erp_supply.exception_sla_rules.metadata||excluded.metadata,
  updated_at=now();

create or replace function erp_supply.refresh_exception_sla(p_organization_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_org uuid;
  v_issue record;
  v_approval record;
  v_rule erp_supply.exception_sla_rules%rowtype;
  v_age bigint;
  v_level integer;
  v_severity text;
  v_target text;
  v_inserted integer:=0;
  v_updated integer:=0;
begin
  for v_org in
    select id from erp_supply.organizations
    where p_organization_id is null or id=p_organization_id
  loop
    for v_issue in
      select i.*,o.order_number,o.priority,o.current_role_code
      from erp_supply.order_issues i
      join erp_supply.orders o on o.id=i.order_id
      where i.organization_id=v_org and i.status='OPEN' and i.issue_type in('NOVELTY','REPORT')
    loop
      select * into v_rule
      from erp_supply.exception_sla_rules r
      where r.organization_id=v_org and r.active and r.object_type='ISSUE'
        and r.subtype in(v_issue.issue_type,'*')
      order by case when r.subtype=v_issue.issue_type then 0 else 1 end
      limit 1;
      if not found then continue; end if;

      v_age:=erp_supply.business_seconds_between(v_org,v_issue.created_at,now());
      v_level:=case
        when v_age>=v_rule.escalation_2_seconds then 3
        when v_age>=v_rule.escalation_1_seconds then 2
        when v_age>=v_rule.warning_seconds then 1
        else 0
      end;
      if v_level>0 then
        v_severity:=case v_level when 1 then 'WARNING' when 2 then 'HIGH' else 'CRITICAL' end;
        v_target:=case v_level
          when 1 then coalesce(v_issue.target_role_code,v_issue.current_role_code,'jefe_logistica')
          when 2 then coalesce(v_rule.escalation_role_1,'jefe_logistica')
          else coalesce(v_rule.escalation_role_2,'gerencia')
        end;
        insert into erp_supply.operational_alerts(
          organization_id,order_id,source_type,source_id,alert_level,severity,target_role_code,message,metadata
        ) values(
          v_org,v_issue.order_id,'ISSUE',v_issue.id,v_level,v_severity,v_target,
          format('%s %s del pedido %s supera su SLA operativo',case when v_issue.issue_type='NOVELTY' then 'La novedad' else 'El reporte' end,v_issue.title,v_issue.order_number),
          jsonb_build_object('ageBusinessSeconds',v_age,'priority',v_issue.priority,'slaVersion','10.13')
        ) on conflict(organization_id,source_type,source_id,alert_level) do nothing;
        if found then v_inserted:=v_inserted+1; end if;
      end if;
      update erp_supply.order_issues
      set metadata=metadata||jsonb_build_object('sla',jsonb_build_object(
        'ageBusinessSeconds',v_age,
        'warningSeconds',v_rule.warning_seconds,
        'escalation1Seconds',v_rule.escalation_1_seconds,
        'escalation2Seconds',v_rule.escalation_2_seconds,
        'level',v_level,
        'refreshedAt',now()
      ))
      where id=v_issue.id;
      v_updated:=v_updated+1;
    end loop;

    for v_approval in
      select a.*,o.order_number,o.priority
      from erp_supply.approval_requests a
      join erp_supply.orders o on o.id=a.order_id
      where a.organization_id=v_org and a.status='PENDING'
    loop
      select * into v_rule
      from erp_supply.exception_sla_rules r
      where r.organization_id=v_org and r.active and r.object_type='APPROVAL'
        and r.subtype in(v_approval.request_type,'*')
      order by case when r.subtype=v_approval.request_type then 0 else 1 end
      limit 1;
      if not found then continue; end if;

      v_age:=erp_supply.business_seconds_between(v_org,v_approval.created_at,now());
      v_level:=case
        when v_age>=v_rule.escalation_2_seconds then 3
        when v_age>=v_rule.escalation_1_seconds then 2
        when v_age>=v_rule.warning_seconds then 1
        else 0
      end;
      if v_level>0 then
        v_severity:=case v_level when 1 then 'WARNING' when 2 then 'HIGH' else 'CRITICAL' end;
        v_target:=case v_level
          when 1 then coalesce(v_approval.assigned_role_code,'jefe_logistica')
          when 2 then coalesce(v_rule.escalation_role_1,'gerencia')
          else coalesce(v_rule.escalation_role_2,'auditoria')
        end;
        insert into erp_supply.operational_alerts(
          organization_id,order_id,source_type,source_id,alert_level,severity,target_role_code,message,metadata
        ) values(
          v_org,v_approval.order_id,'APPROVAL',v_approval.id,v_level,v_severity,v_target,
          format('La aprobación %s del pedido %s supera su SLA operativo',v_approval.request_type,v_approval.order_number),
          jsonb_build_object('ageBusinessSeconds',v_age,'priority',v_approval.priority,'slaVersion','10.13')
        ) on conflict(organization_id,source_type,source_id,alert_level) do nothing;
        if found then v_inserted:=v_inserted+1; end if;
      end if;
      update erp_supply.approval_requests
      set request_payload=request_payload||jsonb_build_object('sla',jsonb_build_object(
        'ageBusinessSeconds',v_age,
        'warningSeconds',v_rule.warning_seconds,
        'escalation1Seconds',v_rule.escalation_1_seconds,
        'escalation2Seconds',v_rule.escalation_2_seconds,
        'level',v_level,
        'refreshedAt',now()
      ))
      where id=v_approval.id;
      v_updated:=v_updated+1;
    end loop;

    update erp_supply.operational_alerts a
    set status='CLOSED',closed_at=coalesce(closed_at,now())
    where a.organization_id=v_org and a.status<>'CLOSED' and (
      (a.source_type='ISSUE' and not exists(
        select 1 from erp_supply.order_issues i where i.id=a.source_id and i.status='OPEN'
      )) or
      (a.source_type='APPROVAL' and not exists(
        select 1 from erp_supply.approval_requests r where r.id=a.source_id and r.status='PENDING'
      ))
    );
  end loop;
  return jsonb_build_object('processed',v_updated,'alertsCreated',v_inserted,'refreshedAt',now());
end;
$$;

-- Si pg_cron ya está habilitado en el proyecto, se programa una revisión cada 5 minutos.
-- Si no está disponible, no falla la migración: los RPC del Centro de Excepciones refrescan el SLA al consultar.
do $$
begin
  if to_regprocedure('cron.schedule(text,text,text)') is null and exists(select 1 from pg_available_extensions where name='pg_cron') then
    begin
      execute 'create extension if not exists pg_cron';
    exception when others then
      null;
    end;
  end if;
  if to_regprocedure('cron.schedule(text,text,text)') is not null then
    begin
      execute 'select cron.schedule($1,$2,$3)'
      using 'erp-ei-exception-sla-v10-13','*/5 * * * *','select erp_supply.refresh_exception_sla(null);';
    exception when others then
      null;
    end;
  end if;
end;
$$;

create or replace function public.erp_x_refresh_operational_sla()
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare v_org uuid:=erp_supply.current_org_id();begin
  perform erp_supply.require_profile();
  return erp_supply.refresh_exception_sla(v_org);
end;
$$;
grant execute on function public.erp_x_refresh_operational_sla() to authenticated;

-- ---------------------------------------------------------------------------
-- 2. CENTRO DE EXCEPCIONES Y APROBACIONES
-- ---------------------------------------------------------------------------

create or replace function public.erp_x_exception_summary()
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_roles text[]:=erp_supply.current_roles();
  v_control boolean;
begin
  perform erp_supply.refresh_exception_sla(v_org);
  v_control:=erp_supply.has_role('super_admin') or erp_supply.has_role('gerencia') or erp_supply.has_role('auditoria') or erp_supply.has_role('jefe_logistica') or erp_supply.can_access_module('approvals','read');
  return jsonb_build_object(
    'openNovelties',(select count(*) from erp_supply.order_issues i join erp_supply.orders o on o.id=i.order_id where i.organization_id=v_org and i.status='OPEN' and i.issue_type='NOVELTY' and (v_control or i.created_by=v_actor or i.target_role_code=any(v_roles) or o.current_assignee_id=v_actor)),
    'openReports',(select count(*) from erp_supply.order_issues i join erp_supply.orders o on o.id=i.order_id where i.organization_id=v_org and i.status='OPEN' and i.issue_type='REPORT' and (v_control or i.created_by=v_actor or i.target_role_code=any(v_roles) or o.current_assignee_id=v_actor)),
    'pendingApprovals',(select count(*) from erp_supply.approval_requests a where a.organization_id=v_org and a.status='PENDING' and (v_control or a.requested_by=v_actor or a.assigned_profile_id=v_actor or a.assigned_role_code=any(v_roles))),
    'slaWarnings',(select count(*) from erp_supply.operational_alerts a where a.organization_id=v_org and a.status='OPEN' and a.alert_level=1 and (v_control or a.target_role_code=any(v_roles))),
    'escalated',(select count(*) from erp_supply.operational_alerts a where a.organization_id=v_org and a.status='OPEN' and a.alert_level>=2 and (v_control or a.target_role_code=any(v_roles))),
    'critical',(select count(*) from erp_supply.operational_alerts a where a.organization_id=v_org and a.status='OPEN' and a.alert_level=3 and (v_control or a.target_role_code=any(v_roles))),
    'generatedAt',now()
  );
end;
$$;
grant execute on function public.erp_x_exception_summary() to authenticated;

create or replace function public.erp_x_exception_center(
  p_kind text default null,
  p_state text default 'OPEN',
  p_page integer default 1,
  p_page_size integer default 100
)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_roles text[]:=erp_supply.current_roles();
  v_control boolean;
  v_kind text:=upper(nullif(trim(coalesce(p_kind,'')),''));
  v_state text:=upper(nullif(trim(coalesce(p_state,'')),''));
  v_page integer:=greatest(coalesce(p_page,1),1);
  v_size integer:=least(greatest(coalesce(p_page_size,100),1),250);
  v_total bigint;
  v_items jsonb;
begin
  perform erp_supply.refresh_exception_sla(v_org);
  v_control:=erp_supply.has_role('super_admin') or erp_supply.has_role('gerencia') or erp_supply.has_role('auditoria') or erp_supply.has_role('jefe_logistica') or erp_supply.can_access_module('approvals','read');

  with unified as (
    select
      i.id,'ISSUE'::text item_type,i.issue_type subtype,i.order_id,o.order_number,o.client_name,o.priority,
      coalesce(t.step_code,o.current_step_code) process_code,i.title,i.detail,i.status,
      i.target_role_code target_role,i.created_by actor_id,p.display_name actor_name,i.created_at,
      i.resolved_at closed_at,
      coalesce((i.metadata#>>'{sla,ageBusinessSeconds}')::bigint,erp_supply.business_seconds_between(v_org,i.created_at,coalesce(i.resolved_at,now()))) age_business_seconds,
      coalesce((i.metadata#>>'{sla,level}')::integer,0) sla_level,
      i.blocking,
      i.source_code source_code,
      null::text decision_reason,
      (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica') or i.target_role_code=any(v_roles) or o.current_assignee_id=v_actor or (i.source_code='NO_DELIVERY' and erp_supply.can_access_module('shipping','update'))) can_resolve,
      (select oa.target_role_code from erp_supply.operational_alerts oa where oa.organization_id=v_org and oa.source_type='ISSUE' and oa.source_id=i.id and oa.status='OPEN' order by oa.alert_level desc limit 1) escalated_role
    from erp_supply.order_issues i
    join erp_supply.orders o on o.id=i.order_id
    join erp_supply.profiles p on p.id=i.created_by
    left join erp_supply.order_tasks t on t.id=i.task_id
    where i.organization_id=v_org
      and (v_control or i.created_by=v_actor or i.target_role_code=any(v_roles) or o.current_assignee_id=v_actor)

    union all

    select
      a.id,'APPROVAL'::text item_type,a.request_type subtype,a.order_id,o.order_number,o.client_name,o.priority,
      o.current_step_code process_code,coalesce(a.request_payload->>'exceptionCode',a.request_type) title,a.reason detail,a.status,
      a.assigned_role_code target_role,a.requested_by actor_id,p.display_name actor_name,a.created_at,
      a.decided_at closed_at,
      coalesce((a.request_payload#>>'{sla,ageBusinessSeconds}')::bigint,erp_supply.business_seconds_between(v_org,a.created_at,coalesce(a.decided_at,now()))) age_business_seconds,
      coalesce((a.request_payload#>>'{sla,level}')::integer,0) sla_level,
      true blocking,
      coalesce(a.request_payload->>'exceptionCode',a.request_type) source_code,
      a.decision_reason,
      (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica') or erp_supply.has_role('auditoria') or erp_supply.has_role('gerencia')) can_resolve,
      (select oa.target_role_code from erp_supply.operational_alerts oa where oa.organization_id=v_org and oa.source_type='APPROVAL' and oa.source_id=a.id and oa.status='OPEN' order by oa.alert_level desc limit 1) escalated_role
    from erp_supply.approval_requests a
    join erp_supply.orders o on o.id=a.order_id
    join erp_supply.profiles p on p.id=a.requested_by
    where a.organization_id=v_org
      and (v_control or a.requested_by=v_actor or a.assigned_profile_id=v_actor or a.assigned_role_code=any(v_roles))
  ), filtered as (
    select * from unified u
    where (v_kind is null or u.item_type=v_kind or u.subtype=v_kind)
      and (
        v_state is null
        or (v_state='OPEN' and ((u.item_type='ISSUE' and u.status='OPEN') or (u.item_type='APPROVAL' and u.status='PENDING')))
        or (v_state='CLOSED' and ((u.item_type='ISSUE' and u.status<>'OPEN') or (u.item_type='APPROVAL' and u.status<>'PENDING')))
        or u.status=v_state
      )
  )
  select count(*) into v_total from filtered;

  with unified as (
    select
      i.id,'ISSUE'::text item_type,i.issue_type subtype,i.order_id,o.order_number,o.client_name,o.priority,
      coalesce(t.step_code,o.current_step_code) process_code,i.title,i.detail,i.status,
      i.target_role_code target_role,p.display_name actor_name,i.created_at,i.resolved_at closed_at,
      coalesce((i.metadata#>>'{sla,ageBusinessSeconds}')::bigint,erp_supply.business_seconds_between(v_org,i.created_at,coalesce(i.resolved_at,now()))) age_business_seconds,
      coalesce((i.metadata#>>'{sla,level}')::integer,0) sla_level,i.blocking,i.source_code source_code,null::text decision_reason,
      (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica') or i.target_role_code=any(v_roles) or o.current_assignee_id=v_actor or (i.source_code='NO_DELIVERY' and erp_supply.can_access_module('shipping','update'))) can_resolve,
      (select oa.target_role_code from erp_supply.operational_alerts oa where oa.organization_id=v_org and oa.source_type='ISSUE' and oa.source_id=i.id and oa.status='OPEN' order by oa.alert_level desc limit 1) escalated_role
    from erp_supply.order_issues i
    join erp_supply.orders o on o.id=i.order_id
    join erp_supply.profiles p on p.id=i.created_by
    left join erp_supply.order_tasks t on t.id=i.task_id
    where i.organization_id=v_org and (v_control or i.created_by=v_actor or i.target_role_code=any(v_roles) or o.current_assignee_id=v_actor)
    union all
    select
      a.id,'APPROVAL'::text item_type,a.request_type subtype,a.order_id,o.order_number,o.client_name,o.priority,
      o.current_step_code process_code,coalesce(a.request_payload->>'exceptionCode',a.request_type) title,a.reason detail,a.status,
      a.assigned_role_code target_role,p.display_name actor_name,a.created_at,a.decided_at closed_at,
      coalesce((a.request_payload#>>'{sla,ageBusinessSeconds}')::bigint,erp_supply.business_seconds_between(v_org,a.created_at,coalesce(a.decided_at,now()))) age_business_seconds,
      coalesce((a.request_payload#>>'{sla,level}')::integer,0) sla_level,true blocking,
      coalesce(a.request_payload->>'exceptionCode',a.request_type) source_code,a.decision_reason,
      (erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica') or erp_supply.has_role('auditoria') or erp_supply.has_role('gerencia')) can_resolve,
      (select oa.target_role_code from erp_supply.operational_alerts oa where oa.organization_id=v_org and oa.source_type='APPROVAL' and oa.source_id=a.id and oa.status='OPEN' order by oa.alert_level desc limit 1) escalated_role
    from erp_supply.approval_requests a
    join erp_supply.orders o on o.id=a.order_id
    join erp_supply.profiles p on p.id=a.requested_by
    where a.organization_id=v_org and (v_control or a.requested_by=v_actor or a.assigned_profile_id=v_actor or a.assigned_role_code=any(v_roles))
  ), filtered as (
    select * from unified u
    where (v_kind is null or u.item_type=v_kind or u.subtype=v_kind)
      and (
        v_state is null
        or (v_state='OPEN' and ((u.item_type='ISSUE' and u.status='OPEN') or (u.item_type='APPROVAL' and u.status='PENDING')))
        or (v_state='CLOSED' and ((u.item_type='ISSUE' and u.status<>'OPEN') or (u.item_type='APPROVAL' and u.status<>'PENDING')))
        or u.status=v_state
      )
  ), page_rows as (
    select * from filtered
    order by
      case when (item_type='ISSUE' and status='OPEN') or (item_type='APPROVAL' and status='PENDING') then 0 else 1 end,
      sla_level desc,
      case priority when 'CRITICAL' then 5 when 'URGENT' then 4 when 'HIGH' then 3 when 'MEDIUM' then 2 else 1 end desc,
      age_business_seconds desc,created_at asc
    offset (v_page-1)*v_size limit v_size
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',id,'itemType',item_type,'subtype',subtype,'orderId',order_id,'orderNumber',order_number,'clientName',client_name,
    'priority',priority,'processCode',process_code,'title',title,'detail',detail,'status',status,'targetRole',target_role,
    'actorName',actor_name,'createdAt',created_at,'closedAt',closed_at,'ageBusinessSeconds',age_business_seconds,
    'slaLevel',sla_level,'blocking',blocking,'sourceCode',source_code,'decisionReason',decision_reason,'canResolve',can_resolve,'escalatedRole',escalated_role
  ) order by
    case when (item_type='ISSUE' and status='OPEN') or (item_type='APPROVAL' and status='PENDING') then 0 else 1 end,
    sla_level desc,age_business_seconds desc),'[]'::jsonb)
  into v_items from page_rows;

  return jsonb_build_object(
    'items',v_items,
    'summary',public.erp_x_exception_summary(),
    'pagination',jsonb_build_object('page',v_page,'pageSize',v_size,'totalItems',v_total,'totalPages',ceil(v_total::numeric/v_size)::integer),
    'generatedAt',now()
  );
end;
$$;
grant execute on function public.erp_x_exception_center(text,text,integer,integer) to authenticated;

-- Listado de aprobaciones actualizado con SLA, manteniendo la firma usada por el frontend existente.
create or replace function public.erp_x_list_approvals(p_status text default 'PENDING',p_page integer default 1,p_page_size integer default 50)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_org uuid:=erp_supply.current_org_id();
  v_profile uuid:=erp_supply.require_profile();
  v_roles text[]:=erp_supply.current_roles();
  v_total bigint;
  v_items jsonb;
  v_page int:=greatest(p_page,1);
  v_size int:=least(greatest(p_page_size,1),200);
begin
  perform erp_supply.refresh_exception_sla(v_org);
  select count(*) into v_total
  from erp_supply.approval_requests a
  where a.organization_id=v_org and (p_status is null or a.status=p_status)
    and (a.requested_by=v_profile or a.assigned_profile_id=v_profile or a.assigned_role_code=any(v_roles) or erp_supply.has_role('super_admin') or erp_supply.has_role('gerencia') or erp_supply.has_role('auditoria') or erp_supply.has_role('jefe_logistica'));

  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into v_items from (
    select a.id,a.order_id "orderId",o.order_number "orderNumber",o.client_name "clientName",o.priority,
      o.current_step_code "processCode",a.request_type "requestType",a.status,a.reason,a.request_payload "requestPayload",
      rq.display_name "requestedBy",a.assigned_role_code "assignedRole",a.decision_reason "decisionReason",
      a.created_at "createdAt",a.decided_at "decidedAt",
      coalesce((a.request_payload#>>'{sla,ageBusinessSeconds}')::bigint,erp_supply.business_seconds_between(v_org,a.created_at,coalesce(a.decided_at,now()))) "ageBusinessSeconds",
      coalesce((a.request_payload#>>'{sla,level}')::integer,0) "slaLevel"
    from erp_supply.approval_requests a
    join erp_supply.orders o on o.id=a.order_id
    join erp_supply.profiles rq on rq.id=a.requested_by
    where a.organization_id=v_org and (p_status is null or a.status=p_status)
      and (a.requested_by=v_profile or a.assigned_profile_id=v_profile or a.assigned_role_code=any(v_roles) or erp_supply.has_role('super_admin') or erp_supply.has_role('gerencia') or erp_supply.has_role('auditoria') or erp_supply.has_role('jefe_logistica'))
    order by coalesce((a.request_payload#>>'{sla,level}')::integer,0) desc,a.created_at asc
    offset (v_page-1)*v_size limit v_size
  ) x;
  return jsonb_build_object('items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_size,'totalItems',v_total,'totalPages',ceil(v_total::numeric/v_size)::int));
end;
$$;

-- Incidencias del pedido con SLA visible en cualquier popup.
create or replace function public.erp_x_order_issues(p_order_id uuid)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare v_org uuid:=erp_supply.current_org_id();begin
  perform erp_supply.require_profile();
  if not erp_supply.can_view_order_or_reception_shadow(p_order_id) then raise exception 'Pedido no disponible' using errcode='42501'; end if;
  perform erp_supply.refresh_exception_sla(v_org);
  return jsonb_build_object('items',(
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',i.id,'type',i.issue_type,'title',i.title,'detail',i.detail,'status',i.status,'blocking',i.blocking,
      'sourceCode',i.source_code,'targetRole',i.target_role_code,'createdBy',p.display_name,'createdAt',i.created_at,
      'resolvedBy',rp.display_name,'resolvedAt',i.resolved_at,'resolution',i.resolution,'resolutionCode',i.resolution_code,
      'ageBusinessSeconds',coalesce((i.metadata#>>'{sla,ageBusinessSeconds}')::bigint,erp_supply.business_seconds_between(v_org,i.created_at,coalesce(i.resolved_at,now()))),
      'slaLevel',coalesce((i.metadata#>>'{sla,level}')::integer,0),'metadata',i.metadata
    ) order by i.created_at desc),'[]'::jsonb)
    from erp_supply.order_issues i
    join erp_supply.profiles p on p.id=i.created_by
    left join erp_supply.profiles rp on rp.id=i.resolved_by
    where i.order_id=p_order_id
  ));
end;
$$;
grant execute on function public.erp_x_order_issues(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. ANALÍTICA CAUSAL / PARETO
-- ---------------------------------------------------------------------------

create or replace function public.erp_x_cause_analytics(p_date_from date default null,p_date_to date default null)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_org uuid:=erp_supply.current_org_id();
  v_from date:=coalesce(p_date_from,current_date-30);
  v_to date:=coalesce(p_date_to,current_date);
  v_result jsonb;
begin
  perform erp_supply.require_profile();
  if not (erp_supply.can_access_module('reports','read') or erp_supply.has_role('auditoria') or erp_supply.has_role('gerencia') or erp_supply.has_role('jefe_logistica') or erp_supply.has_role('super_admin')) then
    raise exception 'No autorizado para consultar analítica causal' using errcode='42501';
  end if;
  if v_to<v_from then raise exception 'Rango de fechas inválido'; end if;

  with events as (
    select
      i.created_at event_at,
      coalesce(nullif(i.source_code,''),nullif(i.title,''),'INCIDENCIA') cause_code,
      null::text reference,
      coalesce(t.step_code,o.current_step_code) process_code,
      seller.display_name seller_name,
      po.supplier_name supplier_name
    from erp_supply.order_issues i
    join erp_supply.orders o on o.id=i.order_id
    left join erp_supply.order_tasks t on t.id=i.task_id
    left join erp_supply.profiles seller on seller.id=o.seller_profile_id
    left join lateral (
      select p.supplier_name from erp_supply.purchase_orders p where p.order_id=o.id order by p.created_at desc limit 1
    ) po on true
    where i.organization_id=v_org and i.issue_type in('NOVELTY','REPORT')
      and i.created_at>=v_from::timestamptz and i.created_at<(v_to+1)::timestamptz

    union all

    select
      pc.checked_at,'MERCANCIA_NO_ENCONTRADA',coalesce(oi.reference,oi.sku,oi.description),'ALISTAMIENTO',
      seller.display_name,po.supplier_name
    from erp_supply.picking_prechecks pc
    join erp_supply.orders o on o.id=pc.order_id
    join erp_supply.order_items oi on oi.id=pc.order_item_id
    left join erp_supply.profiles seller on seller.id=o.seller_profile_id
    left join lateral (
      select p.supplier_name from erp_supply.purchase_orders p where p.order_id=o.id order by p.created_at desc limit 1
    ) po on true
    where pc.organization_id=v_org and pc.result='MISSING'
      and pc.checked_at>=v_from::timestamptz and pc.checked_at<(v_to+1)::timestamptz

    union all

    select
      coalesce(cr.ready_at,cr.updated_at),'CORTE_ASIGNADO_INCORRECTAMENTE',coalesce(cr.reference,cr.sku,cr.description),'CORTE',
      seller.display_name,po.supplier_name
    from erp_supply.cut_requirements cr
    join erp_supply.orders o on o.id=cr.order_id
    left join erp_supply.profiles seller on seller.id=o.seller_profile_id
    left join lateral (
      select p.supplier_name from erp_supply.purchase_orders p where p.order_id=o.id order by p.created_at desc limit 1
    ) po on true
    where cr.organization_id=v_org and cr.resolution_code='NO_CUT'
      and coalesce(cr.ready_at,cr.updated_at)>=v_from::timestamptz and coalesce(cr.ready_at,cr.updated_at)<(v_to+1)::timestamptz

    union all

    select
      r.received_at,'RECEPCION_CON_RECHAZO',coalesce(oi.reference,oi.sku,oi.description),'RECEPCION_MERCANCIA',
      seller.display_name,r.supplier_name
    from erp_supply.receipt_lines rl
    join erp_supply.receipts r on r.id=rl.receipt_id
    join erp_supply.orders o on o.id=r.order_id
    left join erp_supply.order_items oi on oi.id=rl.order_item_id
    left join erp_supply.profiles seller on seller.id=o.seller_profile_id
    where o.organization_id=v_org and coalesce(rl.rejected_quantity,0)>0 and r.received_at is not null
      and r.received_at>=v_from::timestamptz and r.received_at<(v_to+1)::timestamptz
  )
  select jsonb_build_object(
    'from',v_from,'to',v_to,'totalEvents',(select count(*) from events),
    'causes',(select coalesce(jsonb_agg(jsonb_build_object('label',label,'count',n) order by n desc),'[]'::jsonb) from (select coalesce(nullif(cause_code,''),'Sin clasificar') label,count(*) n from events group by 1 order by n desc limit 12) x),
    'references',(select coalesce(jsonb_agg(jsonb_build_object('label',label,'count',n) order by n desc),'[]'::jsonb) from (select coalesce(nullif(reference,''),'Sin referencia') label,count(*) n from events where reference is not null group by 1 order by n desc limit 12) x),
    'sellers',(select coalesce(jsonb_agg(jsonb_build_object('label',label,'count',n) order by n desc),'[]'::jsonb) from (select coalesce(nullif(seller_name,''),'Sin asesor') label,count(*) n from events group by 1 order by n desc limit 12) x),
    'suppliers',(select coalesce(jsonb_agg(jsonb_build_object('label',label,'count',n) order by n desc),'[]'::jsonb) from (select coalesce(nullif(supplier_name,''),'Sin proveedor') label,count(*) n from events where supplier_name is not null group by 1 order by n desc limit 12) x),
    'processes',(select coalesce(jsonb_agg(jsonb_build_object('label',label,'count',n) order by n desc),'[]'::jsonb) from (select coalesce(nullif(process_code,''),'SIN_ETAPA') label,count(*) n from events group by 1 order by n desc limit 12) x),
    'generatedAt',now()
  ) into v_result;
  return v_result;
end;
$$;
grant execute on function public.erp_x_cause_analytics(date,date) to authenticated;

-- ---------------------------------------------------------------------------
-- 4. OPTIMIZADOR DE CARRETOS PARA CORTE
-- ---------------------------------------------------------------------------

create or replace function public.erp_x_cutting_optimizer(p_group_key text)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth
as $$
declare
  v_actor uuid:=erp_supply.require_profile();
  v_org uuid:=erp_supply.current_org_id();
  v_override boolean:=erp_supply.has_role('jefe_logistica') or erp_supply.has_role('super_admin') or erp_supply.has_role('gerencia');
  v_needed numeric;
  v_reference text;
  v_sku text;
  v_description text;
  v_candidates jsonb;
  v_recommended jsonb;
  v_best_use jsonb;
begin
  if not (erp_supply.can_access_module('cutting','read') or erp_supply.has_role('auxiliar_corte') or v_override) then
    raise exception 'No autorizado para consultar el optimizador de Corte' using errcode='42501';
  end if;
  if nullif(trim(p_group_key),'') is null then raise exception 'Grupo de corte requerido'; end if;

  select coalesce(sum(r.total_length),0),max(r.reference),max(r.sku),max(r.description)
  into v_needed,v_reference,v_sku,v_description
  from erp_supply.cut_requirements r
  join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
  where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
    and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
    and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor);
  if v_needed<=0 then raise exception 'El grupo ya no tiene cortes pendientes'; end if;

  with candidates as (
    select
      l.id lot_id,l.lot_number,l.location,
      l.quantity_available usable_length,
      l.quantity_available-v_needed projected_remaining,
      case when l.quantity_available>=v_needed then true else false end sufficient,
      case when l.quantity_available-v_needed>0
                 and l.quantity_available-v_needed<50 then true else false end approval_required,
      case when l.quantity_available>0 then round((v_needed/l.quantity_available*100)::numeric,2) else 0 end utilization_pct,
      ii.sku,ii.reference,ii.description
    from erp_supply.inventory_items ii
    join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
    where ii.organization_id=v_org and ii.active
      and l.quantity_available>0
      and ((v_sku is not null and ii.sku=v_sku) or (v_reference is not null and ii.reference=v_reference) or ii.metadata->>'cutGroupKey'=p_group_key)
  ), ranked as (
    select c.*,
      row_number() over(order by
        case when c.sufficient and (c.projected_remaining=0 or c.projected_remaining>=50) then 0 when c.sufficient then 1 else 2 end,
        case when c.sufficient then c.projected_remaining else -c.usable_length end asc,
        c.lot_number nulls last
      ) operational_rank,
      row_number() over(order by
        case when c.sufficient then 0 else 1 end,
        case when c.sufficient then c.projected_remaining else -c.usable_length end asc
      ) material_rank
    from candidates c
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'lotId',lot_id,'lotNumber',lot_number,'location',location,'usableLength',usable_length,
    'projectedRemaining',projected_remaining,'sufficient',sufficient,'approvalRequired',approval_required,
    'utilizationPct',utilization_pct,'operationalRank',operational_rank,'materialRank',material_rank
  ) order by operational_rank),'[]'::jsonb) into v_candidates
  from (select * from ranked order by operational_rank limit 8) x;

  with candidates as (
    select l.id lot_id,l.lot_number,l.location,l.quantity_available usable_length,
      l.quantity_available-v_needed projected_remaining
    from erp_supply.inventory_items ii join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
    where ii.organization_id=v_org and ii.active and l.quantity_available>0
      and ((v_sku is not null and ii.sku=v_sku) or (v_reference is not null and ii.reference=v_reference) or ii.metadata->>'cutGroupKey'=p_group_key)
  )
  select jsonb_build_object('lotId',lot_id,'lotNumber',lot_number,'location',location,'usableLength',usable_length,'projectedRemaining',projected_remaining,
    'approvalRequired',(projected_remaining>0 and projected_remaining<50))
  into v_recommended
  from candidates
  order by
    case when usable_length>=v_needed and (projected_remaining=0 or projected_remaining>=50) then 0 when usable_length>=v_needed then 1 else 2 end,
    case when usable_length>=v_needed then projected_remaining else -usable_length end asc
  limit 1;

  with candidates as (
    select l.id lot_id,l.lot_number,l.location,l.quantity_available usable_length,
      l.quantity_available-v_needed projected_remaining
    from erp_supply.inventory_items ii join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
    where ii.organization_id=v_org and ii.active and l.quantity_available>0
      and ((v_sku is not null and ii.sku=v_sku) or (v_reference is not null and ii.reference=v_reference) or ii.metadata->>'cutGroupKey'=p_group_key)
  )
  select jsonb_build_object('lotId',lot_id,'lotNumber',lot_number,'location',location,'usableLength',usable_length,'projectedRemaining',projected_remaining,
    'approvalRequired',(projected_remaining>0 and projected_remaining<50))
  into v_best_use
  from candidates
  order by case when usable_length>=v_needed then 0 else 1 end,
           case when usable_length>=v_needed then projected_remaining else -usable_length end asc
  limit 1;

  return jsonb_build_object(
    'groupKey',p_group_key,'reference',v_reference,'sku',v_sku,'description',v_description,
    'requiredLength',v_needed,'recommended',v_recommended,'bestMaterialUse',v_best_use,
    'candidates',v_candidates,'generatedAt',now(),
    'rule',jsonb_build_object('criticalRemainderMeters',50,'strategy','Menor remanente sin forzar aprobación; si no existe, mejor aprovechamiento disponible')
  );
end;
$$;
grant execute on function public.erp_x_cutting_optimizer(text) to authenticated;

-- ---------------------------------------------------------------------------
-- 5. CIERRE AUTOMÁTICO DE ALERTAS AL RESOLVER / DECIDIR
-- ---------------------------------------------------------------------------

create or replace function erp_supply.trg_close_operational_alerts()
returns trigger
language plpgsql
security definer
set search_path=erp_supply,public
as $$
begin
  if tg_table_name='order_issues' and new.status<>'OPEN' and old.status='OPEN' then
    update erp_supply.operational_alerts set status='CLOSED',closed_at=coalesce(closed_at,now())
    where source_type='ISSUE' and source_id=new.id and status<>'CLOSED';
  elsif tg_table_name='approval_requests' and new.status<>'PENDING' and old.status='PENDING' then
    update erp_supply.operational_alerts set status='CLOSED',closed_at=coalesce(closed_at,now())
    where source_type='APPROVAL' and source_id=new.id and status<>'CLOSED';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_close_issue_alerts on erp_supply.order_issues;
create trigger trg_close_issue_alerts after update of status on erp_supply.order_issues
for each row execute function erp_supply.trg_close_operational_alerts();

drop trigger if exists trg_close_approval_alerts on erp_supply.approval_requests;
create trigger trg_close_approval_alerts after update of status on erp_supply.approval_requests
for each row execute function erp_supply.trg_close_operational_alerts();

-- Validación de instalación.
do $$
begin
  if to_regprocedure('public.erp_x_exception_center(text,text,integer,integer)') is null then raise exception 'Falta Centro de Excepciones V10.13'; end if;
  if to_regprocedure('public.erp_x_cause_analytics(date,date)') is null then raise exception 'Falta Analítica Causal V10.13'; end if;
  if to_regprocedure('public.erp_x_cutting_optimizer(text)') is null then raise exception 'Falta Optimizador de Corte V10.13'; end if;
end;
$$;

notify pgrst,'reload schema';
commit;

-- ============================================================================
-- 030_siesa_material_master_v10_14.sql
-- ============================================================================
-- ERP EI V10.14
-- Maestro oficial Siesa: catálogo único de materiales, inventario físico, Ventas, Recepción y Corte.
-- Fuente inicial: Excel_siesa(1).xls
-- SHA-256: 800a3a12e54125913cebb3eb5c112f4483109f9afd6318ee7963a7762bb19f7e
-- Filas físicas: 2961 · Materiales oficiales únicos: 1959

begin;

-- ---------------------------------------------------------------------------
-- 1. MAESTRO OFICIAL Y SINCRONIZACIÓN
-- ---------------------------------------------------------------------------

create table if not exists erp_supply.material_master (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references erp_supply.organizations(id) on delete cascade,
  reference text not null,
  exact_name text not null,
  normalized_name text not null,
  unit text not null,
  weight numeric(18,6),
  attributes jsonb not null default '{}'::jsonb,
  source_system text not null default 'SIESA',
  source_hash text,
  active boolean not null default true,
  last_sync_batch_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(organization_id,reference)
);
create index if not exists idx_material_master_search on erp_supply.material_master(organization_id,active,reference);
create index if not exists idx_material_master_name on erp_supply.material_master(organization_id,normalized_name);

create table if not exists erp_supply.material_variants (
  id uuid primary key default gen_random_uuid(),
  material_master_id uuid not null references erp_supply.material_master(id) on delete cascade,
  variant_label text not null,
  normalized_label text not null,
  metadata jsonb not null default '{}'::jsonb,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(material_master_id,normalized_label)
);
create index if not exists idx_material_variants_master on erp_supply.material_variants(material_master_id,active);

create table if not exists erp_supply.material_sync_batches (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references erp_supply.organizations(id) on delete cascade,
  file_name text not null,
  file_sha256 text,
  expected_rows integer not null check(expected_rows>0),
  staged_rows integer not null default 0,
  status text not null default 'STAGING' check(status in('STAGING','APPLYING','COMPLETED','FAILED')),
  imported_by uuid references erp_supply.profiles(id),
  summary jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists idx_material_sync_batches_org on erp_supply.material_sync_batches(organization_id,created_at desc);

create table if not exists erp_supply.material_sync_stage (
  batch_id uuid not null references erp_supply.material_sync_batches(id) on delete cascade,
  row_number integer not null,
  row_data jsonb not null,
  primary key(batch_id,row_number)
);

alter table erp_supply.inventory_items add column if not exists material_master_id uuid references erp_supply.material_master(id);
alter table erp_supply.inventory_lots add column if not exists material_variant_id uuid references erp_supply.material_variants(id);
alter table erp_supply.inventory_lots add column if not exists source_system text;
alter table erp_supply.inventory_lots add column if not exists source_key text;
alter table erp_supply.inventory_lots add column if not exists source_active boolean not null default true;
alter table erp_supply.inventory_lots add column if not exists warehouse_code text;
alter table erp_supply.inventory_lots add column if not exists source_location_code text;
alter table erp_supply.inventory_lots add column if not exists source_location_name text;
alter table erp_supply.order_items add column if not exists material_master_id uuid references erp_supply.material_master(id);
alter table erp_supply.order_items add column if not exists material_variant_id uuid references erp_supply.material_variants(id);
alter table erp_supply.cut_requirements add column if not exists material_master_id uuid references erp_supply.material_master(id);
alter table erp_supply.cut_requirements add column if not exists material_variant_id uuid references erp_supply.material_variants(id);

create unique index if not exists uq_inventory_official_material
  on erp_supply.inventory_items(organization_id,material_master_id)
  where material_master_id is not null;
create unique index if not exists uq_inventory_lot_source
  on erp_supply.inventory_lots(inventory_item_id,source_system,source_key)
  where source_key is not null;
create index if not exists idx_order_items_material on erp_supply.order_items(material_master_id,material_variant_id);
create index if not exists idx_cut_requirements_material on erp_supply.cut_requirements(material_master_id,material_variant_id);

create or replace function erp_supply.material_norm(p_value text)
returns text
language sql
immutable
as $$
  select upper(regexp_replace(trim(coalesce(p_value,'')),'\s+',' ','g'))
$$;

create or replace function erp_supply.material_unit(p_value text)
returns text
language sql
immutable
as $$
  select case upper(trim(coalesce(p_value,'')))
    when 'UND' then 'UND' when 'M' then 'M' when 'KG' then 'KG' when 'GR' then 'GR'
    else upper(trim(coalesce(nullif(p_value,''),'UND')))
  end
$$;

create or replace function erp_supply.apply_material_sync(p_batch_id uuid)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,pg_catalog
as $$
declare
  v_batch erp_supply.material_sync_batches%rowtype;
  v_count integer;
  v_materials integer;
  v_variants integer;
  v_lots integer;
  v_summary jsonb;
begin
  select * into v_batch from erp_supply.material_sync_batches where id=p_batch_id for update;
  if not found then raise exception 'Lote de actualización Siesa no encontrado'; end if;
  if v_batch.status not in('STAGING','APPLYING') then
    if v_batch.status='COMPLETED' then return v_batch.summary; end if;
    raise exception 'El lote Siesa no se puede aplicar en estado %',v_batch.status;
  end if;

  select count(*) into v_count from erp_supply.material_sync_stage where batch_id=p_batch_id;
  if v_count<>v_batch.expected_rows then
    raise exception 'La carga está incompleta: se esperaban % filas y llegaron %',v_batch.expected_rows,v_count;
  end if;

  if exists(
    select 1 from erp_supply.material_sync_stage
    where batch_id=p_batch_id and (
      nullif(trim(row_data->>'reference'),'') is null or
      nullif(trim(row_data->>'name'),'') is null or
      nullif(trim(row_data->>'unit'),'') is null or
      nullif(trim(row_data->>'warehouse'),'') is null or
      nullif(trim(row_data->>'location'),'') is null or
      nullif(trim(row_data->>'sourceKey'),'') is null
    )
  ) then raise exception 'El archivo contiene filas sin referencia, nombre, unidad, bodega, ubicación o identidad física'; end if;

  if exists(
    select 1
    from erp_supply.material_sync_stage
    where batch_id=p_batch_id
    group by trim(row_data->>'reference')
    having count(distinct erp_supply.material_norm(row_data->>'name'))>1
       or count(distinct erp_supply.material_unit(row_data->>'unit'))>1
  ) then raise exception 'Una referencia aparece con nombres o unidades incompatibles. Corrige el Excel antes de actualizar'; end if;

  if exists(
    select 1 from erp_supply.material_sync_stage
    where batch_id=p_batch_id
    group by row_data->>'sourceKey'
    having count(*)>1
  ) then raise exception 'El archivo contiene dos filas físicas idénticas para la misma referencia/bodega/ubicación/lote/variante'; end if;

  update erp_supply.material_sync_batches set status='APPLYING',staged_rows=v_count where id=p_batch_id;

  -- El snapshot es completo: se desactiva lo ausente, pero nunca se borra historial.
  update erp_supply.material_master
  set active=false,updated_at=now()
  where organization_id=v_batch.organization_id and source_system='SIESA';

  with first_rows as (
    select distinct on (trim(s.row_data->>'reference'))
      trim(s.row_data->>'reference') reference,s.row_data
    from erp_supply.material_sync_stage s
    where s.batch_id=p_batch_id
    order by trim(s.row_data->>'reference'),s.row_number
  )
  insert into erp_supply.material_master(
    organization_id,reference,exact_name,normalized_name,unit,weight,attributes,
    source_system,source_hash,active,last_sync_batch_id,updated_at
  )
  select v_batch.organization_id,reference,trim(row_data->>'name'),
    erp_supply.material_norm(row_data->>'name'),erp_supply.material_unit(row_data->>'unit'),
    nullif(row_data->>'weight','')::numeric,
    jsonb_build_object(
      'criteria',coalesce(row_data->'criteria','[]'::jsonb),
      'source','SIESA','sourceFile',v_batch.file_name
    ),
    'SIESA',v_batch.file_sha256,true,p_batch_id,now()
  from first_rows
  on conflict(organization_id,reference) do update set
    exact_name=excluded.exact_name,normalized_name=excluded.normalized_name,unit=excluded.unit,
    weight=excluded.weight,attributes=excluded.attributes,source_system='SIESA',
    source_hash=excluded.source_hash,active=true,last_sync_batch_id=p_batch_id,updated_at=now();

  update erp_supply.material_variants v
  set active=false,updated_at=now()
  from erp_supply.material_master m
  where v.material_master_id=m.id and m.organization_id=v_batch.organization_id and m.source_system='SIESA';

  insert into erp_supply.material_variants(material_master_id,variant_label,normalized_label,metadata,active,updated_at)
  select distinct m.id,trim(s.row_data->>'ext1'),erp_supply.material_norm(s.row_data->>'ext1'),
    jsonb_build_object('source','SIESA','lastSyncBatchId',p_batch_id),true,now()
  from erp_supply.material_sync_stage s
  join erp_supply.material_master m on m.organization_id=v_batch.organization_id and m.reference=trim(s.row_data->>'reference')
  where s.batch_id=p_batch_id and nullif(trim(s.row_data->>'ext1'),'') is not null
  on conflict(material_master_id,normalized_label) do update set
    variant_label=excluded.variant_label,metadata=erp_supply.material_variants.metadata||excluded.metadata,active=true,updated_at=now();

  -- Si un registro de prueba usó por accidente el SKU oficial con otro nombre, se conserva
  -- como histórico/QA pero se retira del inventario operativo.
  update erp_supply.inventory_items ii
  set sku='LEGACY-'||ii.sku||'-'||substr(ii.id::text,1,8),active=false,
      metadata=ii.metadata||jsonb_build_object('quarantinedBySiesa',true,'originalSku',ii.sku,'quarantinedAt',now()),
      updated_at=now()
  from erp_supply.material_master m
  where m.organization_id=v_batch.organization_id and m.active
    and ii.organization_id=m.organization_id and ii.sku=m.reference
    and ii.material_master_id is null
    and erp_supply.material_norm(ii.description)<>m.normalized_name;

  -- Enlaza una fila real preexistente si referencia y nombre coinciden exactamente.
  with ranked as (
    select ii.id,m.id material_id,
      row_number() over(partition by m.id order by ii.created_at,ii.id) rn
    from erp_supply.inventory_items ii
    join erp_supply.material_master m on m.organization_id=ii.organization_id and m.active
      and (ii.sku=m.reference or ii.reference=m.reference)
      and erp_supply.material_norm(ii.description)=m.normalized_name
    where ii.organization_id=v_batch.organization_id and ii.material_master_id is null
      and not exists(select 1 from erp_supply.inventory_items x where x.organization_id=m.organization_id and x.material_master_id=m.id)
  )
  update erp_supply.inventory_items ii
  set material_master_id=case when r.rn=1 then r.material_id else null end,active=(r.rn=1),
      sku=case when r.rn=1 then m.reference else 'LEGACY-'||ii.sku||'-'||substr(ii.id::text,1,8) end,
      reference=m.reference,description=m.exact_name,unit=m.unit,
      metadata=ii.metadata||jsonb_build_object('officialSiesa',r.rn=1,'linkedAt',now()),updated_at=now()
  from ranked r join erp_supply.material_master m on m.id=r.material_id
  where ii.id=r.id;

  update erp_supply.inventory_items ii
  set active=false,updated_at=now()
  from erp_supply.material_master m
  where ii.material_master_id=m.id and m.organization_id=v_batch.organization_id and not m.active;

  -- El snapshot Siesa reemplaza el saldo operativo anterior. Los lotes legacy/manuales
  -- se conservan para auditoría, pero no se suman al inventario oficial para evitar dobles saldos.
  update erp_supply.inventory_lots l
  set source_active=false,
      metadata=coalesce(l.metadata,'{}'::jsonb)||jsonb_build_object(
        'excludedFromOfficialInventory',true,
        'excludedBy','SIESA_V10_14',
        'excludedAt',now()
      )
  from erp_supply.inventory_items ii
  where l.inventory_item_id=ii.id
    and ii.organization_id=v_batch.organization_id
    and ii.material_master_id is not null
    and coalesce(l.source_system,'') not in('SIESA','ERP_CUT');

  insert into erp_supply.inventory_items(
    organization_id,sku,reference,description,unit,item_type,active,material_master_id,metadata,updated_at
  )
  select m.organization_id,m.reference,m.reference,m.exact_name,m.unit,
    case when m.unit='M' then 'CUTTABLE' else 'STANDARD' end,true,m.id,
    jsonb_build_object('officialSiesa',true,'source','SIESA','lastSyncBatchId',p_batch_id),now()
  from erp_supply.material_master m
  where m.organization_id=v_batch.organization_id and m.active
  on conflict(organization_id,sku) do update set
    reference=excluded.reference,description=excluded.description,unit=excluded.unit,item_type=excluded.item_type,
    active=true,material_master_id=excluded.material_master_id,
    metadata=erp_supply.inventory_items.metadata||excluded.metadata,updated_at=now();

  -- Toda fila Siesa anterior que ya no venga en el snapshot queda oculta, no borrada.
  update erp_supply.inventory_lots l set source_active=false
  from erp_supply.inventory_items ii
  where l.inventory_item_id=ii.id and ii.organization_id=v_batch.organization_id and l.source_system='SIESA';

  insert into erp_supply.inventory_lots(
    inventory_item_id,lot_number,serial_number,location,
    quantity_available,quantity_reserved,quantity_blocked,
    material_variant_id,source_system,source_key,source_active,
    warehouse_code,source_location_code,source_location_name,metadata
  )
  select ii.id,
    nullif(trim(s.row_data->>'lot'),''),
    nullif(trim(s.row_data->>'ext2'),''),
    trim(s.row_data->>'location'),
    greatest(coalesce(nullif(s.row_data->>'available','')::numeric,0),0),
    greatest(coalesce(nullif(s.row_data->>'committed','')::numeric,0),0),
    greatest(coalesce(nullif(s.row_data->>'existence','')::numeric,0)
      -coalesce(nullif(s.row_data->>'available','')::numeric,0)
      -coalesce(nullif(s.row_data->>'committed','')::numeric,0),0),
    mv.id,'SIESA',s.row_data->>'sourceKey',true,
    trim(s.row_data->>'warehouse'),trim(s.row_data->>'location'),nullif(trim(s.row_data->>'locationName'),''),
    jsonb_build_object(
      'sourceRow',s.row_data->'sourceRow','variantLabel',nullif(trim(s.row_data->>'ext1'),''),
      'secondaryDescription',nullif(trim(s.row_data->>'ext2'),''),
      'physicalExistence',coalesce(nullif(s.row_data->>'existence','')::numeric,0),
      'abcCost',s.row_data->>'abcCost','abcTurns',s.row_data->>'abcTurns',
      'dates',coalesce(s.row_data->'dates','{}'::jsonb),
      'averageCostUnit',s.row_data->'avgCostUnit','averageCostTotal',s.row_data->'avgCostTotal',
      'lastCostUnit',s.row_data->'lastCostUnit','lastCostTotal',s.row_data->'lastCostTotal',
      'averageConsumption',s.row_data->'avgConsumption',
      'lastSyncBatchId',p_batch_id,'sourceFile',v_batch.file_name
    )
  from erp_supply.material_sync_stage s
  join erp_supply.material_master m on m.organization_id=v_batch.organization_id and m.reference=trim(s.row_data->>'reference') and m.active
  join erp_supply.inventory_items ii on ii.organization_id=m.organization_id and ii.material_master_id=m.id and ii.active
  left join erp_supply.material_variants mv on mv.material_master_id=m.id
    and mv.normalized_label=erp_supply.material_norm(s.row_data->>'ext1') and mv.active
  where s.batch_id=p_batch_id
  on conflict(inventory_item_id,source_system,source_key) where source_key is not null do update set
    inventory_item_id=excluded.inventory_item_id,lot_number=excluded.lot_number,serial_number=excluded.serial_number,
    location=excluded.location,quantity_available=excluded.quantity_available,quantity_reserved=excluded.quantity_reserved,
    quantity_blocked=excluded.quantity_blocked,material_variant_id=excluded.material_variant_id,source_active=true,
    warehouse_code=excluded.warehouse_code,source_location_code=excluded.source_location_code,
    source_location_name=excluded.source_location_name,metadata=excluded.metadata;

  -- Backfill prudente de pedidos reales antiguos: referencia + nombre deben coincidir.
  update erp_supply.order_items oi
  set material_master_id=m.id,sku=m.reference,reference=m.reference,description=m.exact_name,unit=m.unit,
      metadata=oi.metadata||jsonb_build_object('materialMasterId',m.id,'materialBackfill','SIESA_V10_14'),updated_at=now()
  from erp_supply.orders o,erp_supply.material_master m
  where oi.order_id=o.id and not o.is_test and o.organization_id=v_batch.organization_id
    and m.organization_id=o.organization_id and m.active
    and oi.material_master_id is null and trim(coalesce(oi.reference,oi.sku,''))=m.reference
    and erp_supply.material_norm(oi.description)=m.normalized_name;

  update erp_supply.cut_requirements r
  set material_master_id=oi.material_master_id,material_variant_id=oi.material_variant_id,updated_at=now()
  from erp_supply.order_items oi
  where r.order_item_id=oi.id and oi.material_master_id is not null;

  select count(*) into v_materials from erp_supply.material_master where organization_id=v_batch.organization_id and source_system='SIESA' and active;
  select count(*) into v_variants from erp_supply.material_variants v join erp_supply.material_master m on m.id=v.material_master_id where m.organization_id=v_batch.organization_id and v.active;
  select count(*) into v_lots from erp_supply.inventory_lots l join erp_supply.inventory_items ii on ii.id=l.inventory_item_id where ii.organization_id=v_batch.organization_id and l.source_system='SIESA' and l.source_active;

  update erp_supply.material_sync_batches set
    status='COMPLETED',staged_rows=v_count,completed_at=now(),
    summary=jsonb_build_object(
      'materials',v_materials,'variants',v_variants,'stockRows',v_lots,
      'sourceRows',v_count,'fileName',file_name,'fileSha256',file_sha256,
      'completedAt',now()
    )
  where id=p_batch_id
  returning summary into v_summary;

  return v_summary;
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. GUARDIA DE IDENTIDAD OFICIAL EN LÍNEAS DE PEDIDO
-- ---------------------------------------------------------------------------

create or replace function erp_supply.trg_order_item_official_material()
returns trigger
language plpgsql
security definer
set search_path=erp_supply,public,pg_catalog
as $$
declare
  v_test boolean;
  v_org uuid;
  v_material erp_supply.material_master%rowtype;
  v_variant erp_supply.material_variants%rowtype;
  v_variant_count integer;
  v_id uuid;
  v_variant_id uuid;
  v_name_matches integer;
begin
  select is_test,organization_id into v_test,v_org from erp_supply.orders where id=new.order_id;
  if coalesce(v_test,false) then return new; end if;

  v_id:=new.material_master_id;
  if v_id is null then
    begin v_id:=nullif(new.metadata->>'materialMasterId','')::uuid; exception when others then v_id:=null; end;
  end if;

  if v_id is not null then
    select * into v_material from erp_supply.material_master
    where id=v_id and organization_id=v_org and active;
  elsif nullif(trim(coalesce(new.reference,new.sku,'')),'') is not null then
    select * into v_material from erp_supply.material_master
    where organization_id=v_org and active and reference=trim(coalesce(new.reference,new.sku,''))
    limit 1;
  else
    select count(*) into v_name_matches from erp_supply.material_master
    where organization_id=v_org and active and normalized_name=erp_supply.material_norm(new.description);
    if v_name_matches=1 then
      select * into v_material from erp_supply.material_master
      where organization_id=v_org and active and normalized_name=erp_supply.material_norm(new.description)
      limit 1;
    end if;
  end if;

  if v_material.id is null then
    raise exception 'MATERIAL_NO_OFICIAL: selecciona una referencia del maestro Siesa para la línea %',new.line_number;
  end if;

  v_variant_id:=new.material_variant_id;
  if v_variant_id is null then
    begin v_variant_id:=nullif(new.metadata->>'materialVariantId','')::uuid; exception when others then v_variant_id:=null; end;
  end if;
  if v_variant_id is null and nullif(trim(new.metadata->>'variantLabel'),'') is not null then
    select id into v_variant_id from erp_supply.material_variants
    where material_master_id=v_material.id and active
      and normalized_label=erp_supply.material_norm(new.metadata->>'variantLabel') limit 1;
  end if;

  select count(*) into v_variant_count from erp_supply.material_variants where material_master_id=v_material.id and active;
  if v_variant_id is not null then
    select * into v_variant from erp_supply.material_variants where id=v_variant_id and material_master_id=v_material.id and active;
    if not found then raise exception 'La variante seleccionada no corresponde a la referencia %',v_material.reference; end if;
  elsif v_variant_count=1 then
    select * into v_variant from erp_supply.material_variants where material_master_id=v_material.id and active limit 1;
    v_variant_id:=v_variant.id;
  elsif v_variant_count>1 then
    raise exception 'VARIANTE_REQUERIDA: la referencia % tiene varias variantes. Selecciona color/variante.',v_material.reference;
  end if;

  new.material_master_id:=v_material.id;
  new.material_variant_id:=v_variant_id;
  new.sku:=v_material.reference;
  new.reference:=v_material.reference;
  new.description:=v_material.exact_name;
  new.unit:=v_material.unit;
  new.metadata:=coalesce(new.metadata,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
    'materialMasterId',v_material.id,'materialVariantId',v_variant_id,
    'variantLabel',case when v_variant_id is not null then v_variant.variant_label else null end,
    'materialSource','SIESA','materialValidatedAt',now()
  ));
  return new;
end;
$$;

drop trigger if exists trg_order_item_official_material on erp_supply.order_items;
create trigger trg_order_item_official_material
before insert or update of sku,reference,description,unit,material_master_id,material_variant_id
on erp_supply.order_items
for each row execute function erp_supply.trg_order_item_official_material();

-- Los carretos creados desde Corte heredan la variante del grupo.
create or replace function erp_supply.trg_inventory_lot_cut_variant()
returns trigger
language plpgsql
security definer
set search_path=erp_supply,public,pg_catalog
as $$
declare v_group text;
begin
  if new.material_variant_id is null then
    v_group:=nullif(new.metadata->>'cutGroupKey','');
    if v_group is not null then
      select r.material_variant_id into new.material_variant_id
      from erp_supply.cut_requirements r
      where r.group_key=v_group and r.material_variant_id is not null
      order by r.created_at limit 1;
    end if;
  end if;
  if new.source_system is null and nullif(new.metadata->>'cutGroupKey','') is not null then
    new.source_system:='ERP_CUT';
    new.source_active:=true;
  end if;
  return new;
end;
$$;
drop trigger if exists trg_inventory_lot_cut_variant on erp_supply.inventory_lots;
create trigger trg_inventory_lot_cut_variant
before insert or update of metadata,material_variant_id on erp_supply.inventory_lots
for each row execute function erp_supply.trg_inventory_lot_cut_variant();

-- Corte no puede consumir un carreto de otra referencia o variante aunque se manipule el navegador.
-- Se valida antes de registrar el lote de corte; cualquier error revierte toda la transacción de Corte.
create or replace function erp_supply.trg_cut_batch_official_identity()
returns trigger
language plpgsql
security definer
set search_path=erp_supply,public,pg_catalog
as $$
declare
  v_material uuid;
  v_variant uuid;
  v_item_material uuid;
  v_lot_variant uuid;
  v_lot_item uuid;
  v_lot_active boolean;
begin
  select min(r.material_master_id::text)::uuid,min(r.material_variant_id::text)::uuid
  into v_material,v_variant
  from erp_supply.cut_requirements r
  where r.organization_id=new.organization_id and r.group_key=new.group_key and r.process_status<>'READY';

  if v_material is null then
    raise exception 'CORTE_SIN_MATERIAL_OFICIAL: el grupo no está vinculado al maestro Siesa';
  end if;

  select material_master_id into v_item_material
  from erp_supply.inventory_items where id=new.inventory_item_id and organization_id=new.organization_id and active;
  if v_item_material is distinct from v_material then
    raise exception 'CARRETO_INCORRECTO: el inventario seleccionado no corresponde a la referencia oficial del corte';
  end if;

  select inventory_item_id,material_variant_id,source_active into v_lot_item,v_lot_variant,v_lot_active
  from erp_supply.inventory_lots where id=new.inventory_lot_id;
  if v_lot_item is distinct from new.inventory_item_id or not coalesce(v_lot_active,false) then
    raise exception 'CARRETO_INCORRECTO: el lote seleccionado no está activo para esta referencia';
  end if;
  if v_lot_variant is distinct from v_variant then
    raise exception 'VARIANTE_INCORRECTA: el carreto seleccionado no corresponde al color o variante solicitada';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_cut_batch_official_identity on erp_supply.cut_batches;
create trigger trg_cut_batch_official_identity
before insert or update of inventory_item_id,inventory_lot_id,group_key on erp_supply.cut_batches
for each row execute function erp_supply.trg_cut_batch_official_identity();

-- ---------------------------------------------------------------------------
-- 3. API DEL MAESTRO Y ACTUALIZACIÓN DESDE EXCEL SIESA
-- ---------------------------------------------------------------------------

create or replace function public.erp_x_material_search(p_query text default null,p_limit integer default 20)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_org uuid:=erp_supply.current_org_id();
  v_q text:=erp_supply.material_norm(p_query);
  v_limit integer:=least(greatest(coalesce(p_limit,20),1),50);
begin
  perform erp_supply.require_profile();
  return (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.rank_score,x.reference),'[]'::jsonb)
    from (
      select m.id,m.reference,m.exact_name "name",m.unit,m.weight,m.attributes,
        ii.id "inventoryItemId",
        coalesce((select sum(l.quantity_available) from erp_supply.inventory_lots l where l.inventory_item_id=ii.id and l.source_active),0) "available",
        coalesce((select sum(l.quantity_reserved) from erp_supply.inventory_lots l where l.inventory_item_id=ii.id and l.source_active),0) "committed",
        coalesce((select jsonb_agg(jsonb_build_object(
          'id',v.id,'label',v.variant_label,
          'available',coalesce((select sum(l.quantity_available) from erp_supply.inventory_lots l where l.inventory_item_id=ii.id and l.material_variant_id=v.id and l.source_active),0)
        ) order by v.variant_label) from erp_supply.material_variants v where v.material_master_id=m.id and v.active),'[]'::jsonb) variants,
        case
          when v_q='' then 10
          when erp_supply.material_norm(m.reference)=v_q then 0
          when m.normalized_name=v_q then 1
          when erp_supply.material_norm(m.reference) like v_q||'%' then 2
          when m.normalized_name like v_q||'%' then 3
          else 5
        end rank_score
      from erp_supply.material_master m
      left join erp_supply.inventory_items ii on ii.organization_id=m.organization_id and ii.material_master_id=m.id and ii.active
      where m.organization_id=v_org and m.active
        and (v_q='' or erp_supply.material_norm(m.reference) like '%'||v_q||'%'
          or m.normalized_name like '%'||v_q||'%'
          or erp_supply.material_norm(m.attributes::text) like '%'||v_q||'%')
      order by rank_score,m.reference
      limit v_limit
    ) x
  );
end;
$$;

create or replace function public.erp_x_material_resolve(p_lines jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_org uuid:=erp_supply.current_org_id();
  v_line jsonb;
  v_out jsonb:='[]'::jsonb;
  v_index integer:=0;
  v_material erp_supply.material_master%rowtype;
  v_variant erp_supply.material_variants%rowtype;
  v_material_id uuid;
  v_variant_id uuid;
  v_count integer;
  v_variants jsonb;
begin
  perform erp_supply.require_profile();
  if jsonb_typeof(coalesce(p_lines,'[]'::jsonb))<>'array' then raise exception 'Las líneas a resolver deben ser una lista'; end if;

  for v_line in select value from jsonb_array_elements(coalesce(p_lines,'[]'::jsonb)) loop
    v_index:=v_index+1; v_material:=null; v_variant:=null; v_material_id:=null; v_variant_id:=null;
    begin v_material_id:=nullif(v_line->>'materialMasterId','')::uuid; exception when others then v_material_id:=null; end;
    if v_material_id is not null then
      select * into v_material from erp_supply.material_master where id=v_material_id and organization_id=v_org and active;
    elsif nullif(trim(coalesce(v_line->>'reference',v_line->>'sku')),'') is not null then
      select * into v_material from erp_supply.material_master
      where organization_id=v_org and active and reference=trim(coalesce(v_line->>'reference',v_line->>'sku')) limit 1;
    elsif nullif(trim(v_line->>'description'),'') is not null then
      select count(*) into v_count from erp_supply.material_master
      where organization_id=v_org and active and normalized_name=erp_supply.material_norm(v_line->>'description');
      if v_count=1 then
        select * into v_material from erp_supply.material_master
        where organization_id=v_org and active and normalized_name=erp_supply.material_norm(v_line->>'description') limit 1;
      end if;
    end if;

    if v_material.id is null then
      v_out:=v_out||jsonb_build_array(jsonb_build_object('index',v_index-1,'status','NOT_FOUND'));
      continue;
    end if;

    begin v_variant_id:=nullif(v_line->>'materialVariantId','')::uuid; exception when others then v_variant_id:=null; end;
    if v_variant_id is null and nullif(trim(coalesce(v_line->>'variantLabel',v_line->>'color')),'') is not null then
      select id into v_variant_id from erp_supply.material_variants
      where material_master_id=v_material.id and active
        and normalized_label=erp_supply.material_norm(coalesce(v_line->>'variantLabel',v_line->>'color')) limit 1;
    end if;
    select count(*),coalesce(jsonb_agg(jsonb_build_object('id',id,'label',variant_label) order by variant_label),'[]'::jsonb)
      into v_count,v_variants
    from erp_supply.material_variants where material_master_id=v_material.id and active;
    if v_variant_id is not null then
      select * into v_variant from erp_supply.material_variants where id=v_variant_id and material_master_id=v_material.id and active;
      if not found then v_variant_id:=null; end if;
    elsif v_count=1 then
      select * into v_variant from erp_supply.material_variants where material_master_id=v_material.id and active limit 1;
      v_variant_id:=v_variant.id;
    end if;

    v_out:=v_out||jsonb_build_array(jsonb_build_object(
      'index',v_index-1,
      'status',case when v_count>1 and v_variant_id is null then 'VARIANT_REQUIRED' else 'MATCHED' end,
      'material',jsonb_build_object('id',v_material.id,'reference',v_material.reference,'name',v_material.exact_name,'unit',v_material.unit,'weight',v_material.weight),
      'materialVariantId',v_variant_id,'variantLabel',case when v_variant_id is not null then v_variant.variant_label else null end,
      'variants',v_variants
    ));
  end loop;
  return v_out;
end;
$$;

create or replace function public.erp_x_material_sync_begin(p_file_name text,p_file_sha256 text,p_expected_rows integer)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_batch erp_supply.material_sync_batches%rowtype;
begin
  if not (erp_supply.can_access_module('inventory','update') or erp_supply.has_role('jefe_logistica') or erp_supply.has_role('super_admin')) then
    raise exception 'No autorizado para actualizar el maestro Siesa' using errcode='42501';
  end if;
  if nullif(trim(p_file_name),'') is null or coalesce(p_expected_rows,0)<=0 then raise exception 'Archivo o cantidad de filas inválida'; end if;
  insert into erp_supply.material_sync_batches(organization_id,file_name,file_sha256,expected_rows,imported_by)
  values(v_org,trim(p_file_name),nullif(trim(p_file_sha256),''),p_expected_rows,v_actor)
  returning * into v_batch;
  return jsonb_build_object('batchId',v_batch.id,'status',v_batch.status,'expectedRows',v_batch.expected_rows);
end;
$$;

create or replace function public.erp_x_material_sync_append(p_batch_id uuid,p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_batch erp_supply.material_sync_batches%rowtype;v_row jsonb;v_added integer:=0;v_row_no integer;
begin
  select * into v_batch from erp_supply.material_sync_batches where id=p_batch_id and organization_id=v_org for update;
  if not found or v_batch.status<>'STAGING' then raise exception 'Lote Siesa no disponible para recibir filas'; end if;
  if v_batch.imported_by is distinct from v_actor and not erp_supply.has_role('super_admin') then raise exception 'El lote pertenece a otro usuario' using errcode='42501'; end if;
  if jsonb_typeof(coalesce(p_rows,'[]'::jsonb))<>'array' then raise exception 'Las filas deben enviarse como lista'; end if;
  for v_row in select value from jsonb_array_elements(p_rows) loop
    begin v_row_no:=(v_row->>'sourceRow')::integer; exception when others then v_row_no:=null; end;
    if v_row_no is null or v_row_no<=0 then raise exception 'Cada fila requiere sourceRow'; end if;
    insert into erp_supply.material_sync_stage(batch_id,row_number,row_data)
    values(p_batch_id,v_row_no,v_row)
    on conflict(batch_id,row_number) do update set row_data=excluded.row_data;
    v_added:=v_added+1;
  end loop;
  update erp_supply.material_sync_batches b set staged_rows=(select count(*) from erp_supply.material_sync_stage where batch_id=b.id) where id=p_batch_id returning * into v_batch;
  return jsonb_build_object('batchId',p_batch_id,'received',v_added,'stagedRows',v_batch.staged_rows,'expectedRows',v_batch.expected_rows);
end;
$$;

create or replace function public.erp_x_material_sync_finish(p_batch_id uuid)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();v_batch erp_supply.material_sync_batches%rowtype;v_summary jsonb;
begin
  select * into v_batch from erp_supply.material_sync_batches where id=p_batch_id and organization_id=v_org for update;
  if not found then raise exception 'Lote Siesa no encontrado'; end if;
  if v_batch.imported_by is distinct from v_actor and not erp_supply.has_role('super_admin') then raise exception 'El lote pertenece a otro usuario' using errcode='42501'; end if;
  v_summary:=erp_supply.apply_material_sync(p_batch_id);
  return jsonb_build_object('success',true,'batchId',p_batch_id,'summary',v_summary);
end;
$$;

create or replace function public.erp_x_material_sync_history(p_limit integer default 10)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare v_org uuid:=erp_supply.current_org_id();
begin
  perform erp_supply.require_profile();
  if not erp_supply.can_access_module('inventory','read') then raise exception 'No autorizado' using errcode='42501'; end if;
  return (
    select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb)
    from (
      select b.id,b.file_name "fileName",b.file_sha256 "fileSha256",b.expected_rows "expectedRows",b.staged_rows "stagedRows",
        b.status,b.summary,b.created_at "createdAt",b.completed_at "completedAt",p.display_name "importedBy"
      from erp_supply.material_sync_batches b left join erp_supply.profiles p on p.id=b.imported_by
      where b.organization_id=v_org order by b.created_at desc limit least(greatest(coalesce(p_limit,10),1),50)
    ) x
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. INVENTARIO OPERATIVO: SOLO MATERIAL OFICIAL
-- ---------------------------------------------------------------------------

create or replace function public.erp_x_inventory(p_search text default null,p_page integer default 1,p_page_size integer default 50)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare v_org uuid:=erp_supply.current_org_id();v_total bigint;v_items jsonb;v_page int:=greatest(coalesce(p_page,1),1);v_size int:=least(greatest(coalesce(p_page_size,50),1),250);v_q text:=erp_supply.material_norm(p_search);
begin
  perform erp_supply.require_profile();
  if not erp_supply.can_access_module('inventory','read') and not erp_supply.can_access_module('cutting','read') and not erp_supply.has_role('super_admin') then raise exception 'No autorizado' using errcode='42501'; end if;
  select count(*) into v_total
  from erp_supply.inventory_items i join erp_supply.material_master m on m.id=i.material_master_id
  where i.organization_id=v_org and i.active and m.active
    and (v_q='' or erp_supply.material_norm(m.reference||' '||m.exact_name||' '||m.attributes::text) like '%'||v_q||'%');

  select coalesce(jsonb_agg(to_jsonb(x) order by x.description),'[]'::jsonb) into v_items from (
    select i.id,i.sku,m.reference,m.exact_name description,m.unit,i.item_type "itemType",i.barcode,m.id "materialMasterId",
      coalesce(sum(l.quantity_available) filter(where l.source_active),0) available,
      coalesce(sum(l.quantity_reserved) filter(where l.source_active),0) reserved,
      coalesce(sum(l.quantity_blocked) filter(where l.source_active),0) blocked,
      count(l.id) filter(where l.source_active) lots,
      count(distinct l.material_variant_id) filter(where l.source_active and l.material_variant_id is not null) "variantCount",
      m.attributes
    from erp_supply.inventory_items i
    join erp_supply.material_master m on m.id=i.material_master_id and m.active
    left join erp_supply.inventory_lots l on l.inventory_item_id=i.id and l.source_active
    where i.organization_id=v_org and i.active
      and (v_q='' or erp_supply.material_norm(m.reference||' '||m.exact_name||' '||m.attributes::text) like '%'||v_q||'%')
    group by i.id,m.id
    order by m.exact_name
    offset (v_page-1)*v_size limit v_size
  ) x;
  return jsonb_build_object('items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_size,'totalItems',v_total,'totalPages',ceil(v_total::numeric/v_size)::int));
end;
$$;

create or replace function public.erp_x_inventory_lots(p_item_id uuid default null,p_search text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare v_org uuid:=erp_supply.current_org_id();v_q text:=erp_supply.material_norm(p_search);
begin
  perform erp_supply.require_profile();
  if not erp_supply.can_access_module('inventory','read') and not erp_supply.can_access_module('cutting','read') and not erp_supply.has_role('super_admin') then raise exception 'No autorizado' using errcode='42501'; end if;
  return (select coalesce(jsonb_agg(to_jsonb(x) order by x.description,x.location,x.lot_number),'[]'::jsonb) from (
    select l.id,l.inventory_item_id "itemId",i.sku,m.reference,m.exact_name description,m.unit,
      l.lot_number "lotNumber",l.serial_number "serialNumber",l.location,
      l.quantity_available available,l.quantity_reserved reserved,l.quantity_blocked blocked,l.expires_at "expiresAt",
      l.source_system "sourceSystem",l.warehouse_code "warehouseCode",l.source_location_name "locationName",
      v.id "materialVariantId",v.variant_label "variantLabel",l.metadata
    from erp_supply.inventory_lots l
    join erp_supply.inventory_items i on i.id=l.inventory_item_id
    join erp_supply.material_master m on m.id=i.material_master_id and m.active
    left join erp_supply.material_variants v on v.id=l.material_variant_id
    where i.organization_id=v_org and i.active and l.source_active
      and (p_item_id is null or i.id=p_item_id)
      and (v_q='' or erp_supply.material_norm(m.reference||' '||m.exact_name||' '||coalesce(l.lot_number,'')||' '||l.location||' '||coalesce(v.variant_label,'')||' '||coalesce(l.serial_number,'')) like '%'||v_q||'%')
  ) x);
end;
$$;

create or replace function public.erp_x_inventory_adjust(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();
  v_item erp_supply.inventory_items%rowtype;v_master erp_supply.material_master%rowtype;v_lot erp_supply.inventory_lots%rowtype;
  v_qty numeric;v_type text;v_order_id uuid:=erp_supply.safe_uuid(p_payload->>'orderId');
begin
  if not erp_supply.can_access_module('inventory','update') then raise exception 'No autorizado para ajustar inventario' using errcode='42501'; end if;
  select * into v_item from erp_supply.inventory_items where id=erp_supply.safe_uuid(p_payload->>'itemId') and organization_id=v_org and active;
  if not found or v_item.material_master_id is null then raise exception 'Solo se puede editar inventario vinculado al maestro oficial Siesa'; end if;
  select * into v_master from erp_supply.material_master where id=v_item.material_master_id and organization_id=v_org and active;
  if not found or v_item.reference is distinct from v_master.reference or erp_supply.material_norm(v_item.description)<>v_master.normalized_name then
    raise exception 'La referencia y el nombre no coinciden con el maestro Siesa. Este registro queda fuera de la operación normal.';
  end if;
  select * into v_lot from erp_supply.inventory_lots where id=erp_supply.safe_uuid(p_payload->>'lotId') and inventory_item_id=v_item.id and source_active for update;
  if not found then raise exception 'Lote oficial no encontrado'; end if;
  if v_order_id is not null and not erp_supply.can_view_order(v_order_id) then raise exception 'Pedido no disponible' using errcode='42501'; end if;
  v_qty:=erp_supply.safe_numeric(p_payload->>'quantity');v_type:=upper(trim(coalesce(p_payload->>'movementType','')));
  if v_qty is null or v_qty<=0 then raise exception 'Cantidad inválida'; end if;
  if v_type='TRANSFER' then v_type:='TRANSFER_OUT'; end if;
  if v_type not in('RECEIPT','RETURN','TRANSFER_IN','TRANSFER_OUT','ISSUE','ADJUSTMENT_IN','ADJUSTMENT_OUT','SCRAP') then raise exception 'Tipo de movimiento inválido'; end if;
  if v_type in('ISSUE','ADJUSTMENT_OUT','SCRAP','TRANSFER_OUT') then
    if v_lot.quantity_available<v_qty then raise exception 'Existencia insuficiente'; end if;
    update erp_supply.inventory_lots set quantity_available=quantity_available-v_qty,
      metadata=metadata||jsonb_build_object('lastManualAdjustmentAt',now(),'lastManualAdjustmentBy',v_actor)
    where id=v_lot.id returning * into v_lot;
  else
    update erp_supply.inventory_lots set quantity_available=quantity_available+v_qty,
      metadata=metadata||jsonb_build_object('lastManualAdjustmentAt',now(),'lastManualAdjustmentBy',v_actor)
    where id=v_lot.id returning * into v_lot;
  end if;
  insert into erp_supply.inventory_movements(organization_id,inventory_item_id,lot_id,order_id,movement_type,quantity,unit,from_location,to_location,actor_profile_id,reference,metadata)
  values(v_org,v_item.id,v_lot.id,v_order_id,v_type,v_qty,v_master.unit,p_payload->>'fromLocation',p_payload->>'toLocation',v_actor,p_payload->>'reference',
    coalesce(p_payload->'metadata','{}'::jsonb)||jsonb_build_object('materialMasterId',v_master.id,'officialReference',v_master.reference,'officialName',v_master.exact_name));
  return jsonb_build_object('success',true,'lot',to_jsonb(v_lot),'material',jsonb_build_object('id',v_master.id,'reference',v_master.reference,'name',v_master.exact_name));
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. CORTE EXACTO POR MATERIAL + VARIANTE
-- ---------------------------------------------------------------------------

create or replace function erp_supply.sync_parallel_cut_requirements(p_order_id uuid)
returns integer
language plpgsql
security definer
set search_path=erp_supply,public,pg_catalog
as $$
declare
  v_order erp_supply.orders%rowtype;
  v_cut_profile uuid;
  v_count integer:=0;
begin
  select * into v_order from erp_supply.orders where id=p_order_id for update;
  if not found then return 0; end if;
  v_cut_profile:=erp_supply.safe_uuid(v_order.metadata#>>'{receptionAssignment,cutProfileId}');

  delete from erp_supply.cut_requirements r
  where r.order_id=p_order_id and r.process_status='PENDING'
    and not exists(select 1 from erp_supply.order_items i where i.id=r.order_item_id and i.requires_cut and coalesce(i.metadata->>'receptionActive','true')<>'false');

  insert into erp_supply.cut_requirements(
    organization_id,order_id,order_item_id,task_id,group_key,sku,reference,description,
    unit,units_required,length_each,total_length,assigned_profile_id,material_master_id,material_variant_id,metadata
  )
  select v_order.organization_id,v_order.id,i.id,null,
    md5(i.material_master_id::text||'|'||coalesce(i.material_variant_id::text,'SIN_VARIANTE')),
    i.sku,i.reference,i.description,'M',i.quantity,i.requested_cut_length,
    round((i.quantity*i.requested_cut_length)::numeric,4),v_cut_profile,i.material_master_id,i.material_variant_id,
    jsonb_build_object('lineNumber',i.line_number,'source','SIESA_PARALLEL_CUT_V10_14',
      'materialMasterId',i.material_master_id,'materialVariantId',i.material_variant_id)
  from erp_supply.order_items i
  where i.order_id=v_order.id and coalesce(i.metadata->>'receptionActive','true')<>'false'
    and i.requires_cut and i.requested_cut_length is not null and i.requested_cut_length>0
    and i.material_master_id is not null
  on conflict(order_item_id) do update set
    group_key=excluded.group_key,sku=excluded.sku,reference=excluded.reference,description=excluded.description,
    units_required=excluded.units_required,length_each=excluded.length_each,total_length=excluded.total_length,
    material_master_id=excluded.material_master_id,material_variant_id=excluded.material_variant_id,
    assigned_profile_id=coalesce(excluded.assigned_profile_id,erp_supply.cut_requirements.assigned_profile_id),
    metadata=erp_supply.cut_requirements.metadata||excluded.metadata,updated_at=now();
  get diagnostics v_count=row_count;

  if exists(
    select 1 from erp_supply.order_items i where i.order_id=v_order.id and i.requires_cut
      and coalesce(i.metadata->>'receptionActive','true')<>'false' and i.material_master_id is null
  ) then raise exception 'Hay líneas de corte sin material oficial Siesa. Corrige la referencia en Recepción.'; end if;

  update erp_supply.orders set metadata=metadata||jsonb_build_object('cutFlow',coalesce(metadata->'cutFlow','{}'::jsonb)||jsonb_build_object(
    'version','10.14','parallel',true,'materialIdentity','SIESA_MASTER','syncedAt',now(),
    'pendingRequirements',(select count(*) from erp_supply.cut_requirements where order_id=p_order_id and process_status<>'READY')
  )),updated_at=now() where id=p_order_id;
  return v_count;
end;
$$;


create or replace function public.erp_x_cutting_groups(
  p_search text default null,p_page integer default 1,p_page_size integer default 50
)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_org uuid:=erp_supply.current_org_id();v_actor uuid:=erp_supply.require_profile();
  v_page integer:=greatest(coalesce(p_page,1),1);v_size integer:=least(greatest(coalesce(p_page_size,50),1),100);
  v_override boolean:=erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica');
  v_total bigint;v_items jsonb;
begin
  if not (erp_supply.can_access_module('cutting','read') or erp_supply.has_role('auxiliar_corte') or v_override) then raise exception 'No autorizado para consultar Corte' using errcode='42501'; end if;
  with eligible as (
    select r.* from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
    where r.organization_id=v_org and r.process_status<>'READY'
      and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
      and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)
      and (p_search is null or p_search='' or lower(coalesce(r.reference,'')||' '||coalesce(r.sku,'')||' '||r.description) like '%'||lower(p_search)||'%')
  ),grouped as(select group_key from eligible group by group_key)
  select count(*) into v_total from grouped;

  with eligible as (
    select r.*,o.order_number,o.client_name,o.priority,mv.variant_label
    from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
    left join erp_supply.material_variants mv on mv.id=r.material_variant_id
    where r.organization_id=v_org and r.process_status<>'READY'
      and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
      and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)
      and (p_search is null or p_search='' or lower(coalesce(r.reference,'')||' '||coalesce(r.sku,'')||' '||r.description||' '||coalesce(mv.variant_label,'')) like '%'||lower(p_search)||'%')
  ),grouped as (
    select group_key,max(reference) reference,max(sku) sku,max(description) description,
      min(material_master_id::text)::uuid material_master_id,min(material_variant_id::text)::uuid material_variant_id,max(variant_label) variant_label,
      count(*)::integer item_count,count(distinct order_id)::integer order_count,
      sum(units_required) cut_count,sum(total_length) total_length,min(created_at) oldest_at,
      bool_or(process_status='IN_PROGRESS') in_progress
    from eligible group by group_key order by in_progress desc,oldest_at
    offset (v_page-1)*v_size limit v_size
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'groupKey',group_key,'reference',reference,'sku',sku,'description',description,
    'materialMasterId',material_master_id,'materialVariantId',material_variant_id,'variantLabel',variant_label,
    'itemCount',item_count,'orderCount',order_count,'cutCount',cut_count,'totalLength',total_length,'oldestAt',oldest_at,'inProgress',in_progress
  )),'[]'::jsonb) into v_items from grouped;
  return jsonb_build_object('items',v_items,'pagination',jsonb_build_object('page',v_page,'pageSize',v_size,'totalItems',v_total,'totalPages',ceil(v_total::numeric/v_size)::integer),'generatedAt',now());
end;
$$;

create or replace function public.erp_x_cutting_group(p_group_key text)
returns jsonb
language plpgsql
stable
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_org uuid:=erp_supply.current_org_id();v_actor uuid:=erp_supply.require_profile();
  v_override boolean:=erp_supply.has_role('super_admin') or erp_supply.has_role('jefe_logistica');
  v_reference text;v_sku text;v_description text;v_material uuid;v_variant uuid;v_variant_label text;
begin
  if nullif(trim(p_group_key),'') is null then raise exception 'Grupo de corte requerido'; end if;
  if not (erp_supply.can_access_module('cutting','read') or erp_supply.has_role('auxiliar_corte') or v_override) then raise exception 'No autorizado para consultar Corte' using errcode='42501'; end if;
  select max(r.reference),max(r.sku),max(r.description),min(r.material_master_id::text)::uuid,min(r.material_variant_id::text)::uuid
  into v_reference,v_sku,v_description,v_material,v_variant
  from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
  where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
    and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
    and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor);
  if v_description is null then raise exception 'El grupo ya no tiene cortes pendientes'; end if;
  if v_material is null then raise exception 'El grupo no está vinculado al maestro Siesa. Corrige la referencia en Recepción.'; end if;
  select variant_label into v_variant_label from erp_supply.material_variants where id=v_variant;

  return jsonb_build_object(
    'group',jsonb_build_object('groupKey',p_group_key,'reference',v_reference,'sku',v_sku,'description',v_description,
      'materialMasterId',v_material,'materialVariantId',v_variant,'variantLabel',v_variant_label,
      'itemCount',(select count(*) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
      'orderCount',(select count(distinct r.order_id) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
      'cutCount',(select coalesce(sum(r.units_required),0) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
      'totalLength',(select coalesce(sum(r.total_length),0) from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED') where r.group_key=p_group_key and r.organization_id=v_org and r.process_status<>'READY' and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN') and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor))
    ),
    'items',(select coalesce(jsonb_agg(jsonb_build_object('requirementId',r.id,'orderId',r.order_id,'orderNumber',o.order_number,'clientName',o.client_name,
      'priority',o.priority,'orderItemId',r.order_item_id,'lineNumber',i.line_number,'sku',r.sku,'reference',r.reference,'description',r.description,'unit',r.unit,
      'materialMasterId',r.material_master_id,'materialVariantId',r.material_variant_id,'variantLabel',mv.variant_label,
      'unitsRequired',r.units_required,'lengthEach',r.length_each,'totalLength',r.total_length,'processStatus',r.process_status,
      'taskStatus',case when r.process_status='IN_PROGRESS' then 'IN_PROGRESS' else 'PENDING' end,'assigneeId',r.assigned_profile_id,'assigneeName',p.display_name
    ) order by o.priority desc,o.order_number,i.line_number),'[]'::jsonb)
      from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
      join erp_supply.order_items i on i.id=r.order_item_id left join erp_supply.profiles p on p.id=r.assigned_profile_id
      left join erp_supply.material_variants mv on mv.id=r.material_variant_id
      where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
        and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
        and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor)),
    'reels',(select coalesce(jsonb_agg(jsonb_build_object(
        'lotId',l.id,'inventoryItemId',ii.id,'lotNumber',l.lot_number,'serialNumber',l.serial_number,
        'variantLabel',mv.variant_label,'location',l.location,'locationName',l.source_location_name,
        'warehouseCode',l.warehouse_code,'quantityAvailable',l.quantity_available,'unit',ii.unit,
        'sourceSystem',l.source_system,'updatedAt',ii.updated_at
      ) order by l.quantity_available asc),'[]'::jsonb)
      from erp_supply.inventory_items ii join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
      left join erp_supply.material_variants mv on mv.id=l.material_variant_id
      where ii.organization_id=v_org and ii.active and ii.material_master_id=v_material and l.source_active and l.quantity_available>0
        and l.material_variant_id is not distinct from v_variant),
    'recentBatches',(select coalesce(jsonb_agg(to_jsonb(b) order by b.executed_at desc),'[]'::jsonb) from (select * from erp_supply.cut_batches where organization_id=v_org and group_key=p_group_key order by executed_at desc limit 5) b)
  );
end;
$$;

create or replace function public.erp_x_cutting_optimizer(p_group_key text)
returns jsonb
language plpgsql
security definer
set search_path=erp_supply,public,auth,pg_catalog
as $$
declare
  v_actor uuid:=erp_supply.require_profile();v_org uuid:=erp_supply.current_org_id();
  v_override boolean:=erp_supply.has_role('jefe_logistica') or erp_supply.has_role('super_admin') or erp_supply.has_role('gerencia');
  v_needed numeric;v_reference text;v_sku text;v_description text;v_material uuid;v_variant uuid;v_variant_label text;
  v_candidates jsonb;v_recommended jsonb;v_best_use jsonb;
begin
  if not (erp_supply.can_access_module('cutting','read') or erp_supply.has_role('auxiliar_corte') or v_override) then raise exception 'No autorizado para consultar el optimizador de Corte' using errcode='42501'; end if;
  if nullif(trim(p_group_key),'') is null then raise exception 'Grupo de corte requerido'; end if;

  select coalesce(sum(r.total_length),0),max(r.reference),max(r.sku),max(r.description),min(r.material_master_id::text)::uuid,min(r.material_variant_id::text)::uuid
  into v_needed,v_reference,v_sku,v_description,v_material,v_variant
  from erp_supply.cut_requirements r join erp_supply.orders o on o.id=r.order_id and o.status not in('CLOSED','CANCELLED')
  where r.organization_id=v_org and r.group_key=p_group_key and r.process_status<>'READY'
    and not exists(select 1 from erp_supply.order_issues oi where oi.order_id=o.id and oi.blocking and oi.status='OPEN')
    and (v_override or r.assigned_profile_id is null or r.assigned_profile_id=v_actor);
  if v_needed<=0 then raise exception 'El grupo ya no tiene cortes pendientes'; end if;
  if v_material is null then raise exception 'El grupo no tiene identidad oficial Siesa'; end if;
  select variant_label into v_variant_label from erp_supply.material_variants where id=v_variant;

  with candidates as (
    select l.id lot_id,l.lot_number,l.serial_number,l.location,l.source_location_name,l.warehouse_code,
      l.quantity_available usable_length,l.quantity_available-v_needed projected_remaining,
      (l.quantity_available>=v_needed) sufficient,
      (l.quantity_available-v_needed>0 and l.quantity_available-v_needed<50) approval_required,
      case when l.quantity_available>0 then round((v_needed/l.quantity_available*100)::numeric,2) else 0 end utilization_pct,
      l.source_system
    from erp_supply.inventory_items ii join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
    where ii.organization_id=v_org and ii.active and ii.material_master_id=v_material
      and l.source_active and l.quantity_available>0 and l.material_variant_id is not distinct from v_variant
  ),ranked as (
    select c.*,
      row_number() over(order by case when sufficient and (projected_remaining=0 or projected_remaining>=50) then 0 when sufficient then 1 else 2 end,
        case when sufficient then projected_remaining else -usable_length end asc,lot_number nulls last) operational_rank,
      row_number() over(order by case when sufficient then 0 else 1 end,
        case when sufficient then projected_remaining else -usable_length end asc) material_rank
    from candidates c
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'lotId',lot_id,'lotNumber',lot_number,'serialNumber',serial_number,'location',location,'locationName',source_location_name,
    'warehouseCode',warehouse_code,'sourceSystem',source_system,'usableLength',usable_length,
    'projectedRemaining',projected_remaining,'sufficient',sufficient,'approvalRequired',approval_required,
    'utilizationPct',utilization_pct,'operationalRank',operational_rank,'materialRank',material_rank
  ) order by operational_rank),'[]'::jsonb) into v_candidates from (select * from ranked order by operational_rank limit 10) x;

  with candidates as (
    select l.id lot_id,l.lot_number,l.serial_number,l.location,l.source_location_name,l.warehouse_code,l.source_system,
      l.quantity_available usable_length,l.quantity_available-v_needed projected_remaining
    from erp_supply.inventory_items ii join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
    where ii.organization_id=v_org and ii.active and ii.material_master_id=v_material
      and l.source_active and l.quantity_available>0 and l.material_variant_id is not distinct from v_variant
  )
  select jsonb_build_object('lotId',lot_id,'lotNumber',lot_number,'serialNumber',serial_number,'location',location,'locationName',source_location_name,
    'warehouseCode',warehouse_code,'sourceSystem',source_system,'usableLength',usable_length,'projectedRemaining',projected_remaining,
    'approvalRequired',(projected_remaining>0 and projected_remaining<50))
  into v_recommended from candidates
  order by case when usable_length>=v_needed and (projected_remaining=0 or projected_remaining>=50) then 0 when usable_length>=v_needed then 1 else 2 end,
    case when usable_length>=v_needed then projected_remaining else -usable_length end asc limit 1;

  with candidates as (
    select l.id lot_id,l.lot_number,l.serial_number,l.location,l.source_location_name,l.warehouse_code,l.source_system,
      l.quantity_available usable_length,l.quantity_available-v_needed projected_remaining
    from erp_supply.inventory_items ii join erp_supply.inventory_lots l on l.inventory_item_id=ii.id
    where ii.organization_id=v_org and ii.active and ii.material_master_id=v_material
      and l.source_active and l.quantity_available>0 and l.material_variant_id is not distinct from v_variant
  )
  select jsonb_build_object('lotId',lot_id,'lotNumber',lot_number,'serialNumber',serial_number,'location',location,'locationName',source_location_name,
    'warehouseCode',warehouse_code,'sourceSystem',source_system,'usableLength',usable_length,'projectedRemaining',projected_remaining,
    'approvalRequired',(projected_remaining>0 and projected_remaining<50))
  into v_best_use from candidates
  order by case when usable_length>=v_needed then 0 else 1 end,
    case when usable_length>=v_needed then projected_remaining else -usable_length end asc limit 1;

  return jsonb_build_object('groupKey',p_group_key,'reference',v_reference,'sku',v_sku,'description',v_description,
    'materialMasterId',v_material,'materialVariantId',v_variant,'variantLabel',v_variant_label,
    'requiredLength',v_needed,'recommended',v_recommended,'bestMaterialUse',v_best_use,'candidates',v_candidates,'generatedAt',now(),
    'rule',jsonb_build_object('criticalRemainderMeters',50,'strategy','Mismo material y misma variante; menor remanente sin forzar aprobación'));
end;
$$;

